local config = {
  ui_story_5040_50400101_1_dialog_content = "(Ahh... as férias são difíceis de passar...)",
  ui_story_5040_50400101_2_dialog_content = "(Não, controle-se!)",
  ui_story_5040_50400101_3_dialog_content = "\"(Bip) 3 dias até <color=#FFB400>dia da coroa lunar</color>.\"",
  ui_story_5040_50400101_4_dialog_content = "\"O Mooncrown Day é um feriado tradicional no Astra. É um dia para os casais expressarem seu amor e um dia popular para casamentos.\"",
  ui_story_5040_50400101_5_dialog_content = "Eu já sei! Se eu não estivesse tão ocupado que perdi no ano passado, eu não estaria—",
  ui_story_5040_50400101_6_dialog_content = "De qualquer forma, eu tenho que comprar aquele toca-discos em relevo de volta, aquele que Vice e Carleen estavam de olho. Isso vai ser uma boa surpresa de férias!",
  ui_story_5040_50400101_7_dialog_content = "(Recentemente, eles disseram que pretendiam fazer uma pequena pausa e não tenho ideia de para onde foram. Seja como for, terei que ir sozinho!)",
  ui_story_5040_50400101_8_dialog_content = "PlayerName, faz algum tempo. Posso ajudá-lo em alguma coisa?",
  ui_story_5040_50400101_9_dialog_content = "Desculpe, mas o Courier Union está sobrecarregado com o festival chegando, então não tenho tempo para conversar.",
  ui_story_5040_50400101_10_dialog_content = "Sem falar que meu colega da divisão Rediesel Wrench estragou um monte de cartas indo para Lumopolis...",
  ui_story_5040_50400101_11_dialog_content = "Uau... Posso ajudar em alguma coisa?",
  ui_story_5040_50400101_12_dialog_content = "Quero comprar algo para o feriado, então estou fazendo biscates para ganhar dinheiro.",
  ui_story_5040_50400101_13_dialog_content = "Eu realmente não queria incomodar você de novo, especialmente desde que você ajudou Piu-Piu da última vez.",
  ui_story_5040_50400101_14_dialog_content = "Mas já que você perguntou, tem uma coisa. Você acha que poderia passar pela divisão Rediesel Wrench?",
  ui_story_5040_50400101_15_dialog_content = "Um velho amigo de Northland vai se casar no Mooncrown Day, assim como vários outros.",
  ui_story_5040_50400101_16_dialog_content = "É que a noiva dele sofreu um leve acidente no deserto de Rediesel há algum tempo, e eles estão preocupados que não haverá tempo suficiente para chegar a Northland depois que ela se recuperar.",
  ui_story_5040_50400101_17_dialog_content = "E você quer pegar o Colossus emprestado para garantir que ela chegue lá, certo? Não tem problema, isso é feito facilmente.",
  ui_story_5040_50400101_18_dialog_content = "(Falando no casamento de sua amiga, Naroxel não vai ela mesma?)",
  ui_story_5040_50400101_19_dialog_content = "(De qualquer forma, é sempre melhor perguntar à pessoa envolvida sobre os detalhes. Esta deve ser a divisão Rediesel Wrench.)",
  ui_story_5040_50400101_20_dialog_content = "<color=#e8d9bb>TOC Toc-</color>",
  ui_story_5040_50400101_21_dialog_content = "Com licença...",
  ui_story_5040_50400101_22_dialog_content = "Você deve ser o jovem celestita aqui para ajudar! Eu estive esperando por você!",
  ui_story_5040_50400101_23_dialog_content = "Achei que você chegaria antes, pelo jeito que Naroxel sempre fala sobre a velocidade do Colosso.",
  ui_story_5040_50400101_X23_dialog_content = "(Que cobra enorme! Isso é um alto-falante!? É incrível!)",
  ui_story_5040_50400101_X24_dialog_content = "(E este escritório ... Refinado geralmente não é o estilo Rediesel Wrench.)",
  ui_story_5040_50400101_24_dialog_content = "(Uau, este escritório... Refinamento não costuma ser o estilo Rediesel Wrench.)",
  ui_story_5040_50400101_25_dialog_content = "Prazer em conhecê-lo. Eu sou PlayerName, aqui em nome de Naroxel.",
  ui_story_5040_50400101_26_dialog_content = "Quem são vocês?",
  ui_story_5040_50400101_27_dialog_content = "Você é mais jovem do que eu imaginava. De qualquer forma, deixe-me apresentar-me.",
  ui_story_5040_50400101_28_dialog_content = "Eu sou <color=#FFB400>Jerias</color>, Membro Sênior da Divisão de Chaves Rediesel da Courier Union. Isso é <color=#FFB400>tara</color>, nosso cliente para esta tarefa.",
  ui_story_5040_50400101_29_dialog_content = "Olá, eu sou a Tara! Nunca esperei encontrar o lendário Caelestita. Que sorte!",
  ui_story_5040_50400101_30_dialog_content = "Fico lisonjeado! Você também vem conosco para Northland, Lady Jeriah?",
  ui_story_5040_50400101_31_dialog_content = "Apenas Jeriah fará. Heheh, houve uma confusão com o correio, e não tive escolha a não ser pedir ajuda ao Naroxel.",
  ui_story_5040_50400101_32_dialog_content = "Vou representá-la como testemunha do casamento.",
  ui_story_5040_50400101_33_dialog_content = "(Eu me pergunto se ela é a colega que Naroxel mencionou que é responsável pela confusão de correio?)",
  ui_story_5040_50400101_34_dialog_content = "Testemunha? Ouvi dizer que ter alguém do Courier Union em um casamento traz boa sorte aos recém-casados.",
  ui_story_5040_50400101_35_dialog_content = "Certamente! Não foi fácil encontrar um mensageiro para um casamento no Mooncrown Day. Naroxel teve que pedir um favor só para nós!",
  ui_story_5040_50400101_36_dialog_content = "Naroxel está realmente tão ocupada que não consegue tirar um único dia de folga?",
  ui_story_5040_50400101_37_dialog_content = "Os períodos imediatamente antes e logo após o Mooncrown Day são sempre os mais movimentados para o Courier Union, com todos os tipos de convites e cartas voando por aí.",
  ui_story_5040_50400101_38_dialog_content = "Momento perfeito para o adorável Jeriah bagunçar \"acidentalmente\" um monte de pacotes com destino a Northland.",
  ui_story_5040_50400101_39_dialog_content = "Imagino que você tenha convidado nosso amigo celestita aqui para assuntos mais importantes do que para zombar de mim. Vamos indo. Você não sente falta do seu noivo?",
  ui_story_5040_50400101_40_dialog_content = "Boa ideia. Por mais rápido que o Colosso seja, é melhor partirmos o mais rápido possível.",
  ui_story_5040_50400101_41_dialog_content = "Uau! Seu Colosso é tão diferente do Lagarto Gigante!",
  ui_story_5040_50400101_42_dialog_content = "Haha, espere até embarcar.",
  ui_story_5040_50400101_43_dialog_content = "A propósito, uma noiva do deserto e um noivo nortista é uma combinação interessante. Esses tipos de uniões entre países são comuns?",
  ui_story_5040_50400101_44_dialog_content = "Hmm, bem... eu diria que eles são bem raros!",
  ui_story_5040_50400101_45_dialog_content = "O mundo é um lugar grande e tudo é possível. Mas para os aurorianos, é um pouco estranho.",
  ui_story_5040_50400101_46_dialog_content = "Uau! Sério?",
  ui_story_5040_50400101_47_dialog_content = "Rapaz... Jeriah, você também é do Deserto Rediesel?",
  ui_story_5040_50400101_48_dialog_content = "Não gosto de admitir, mas é verdade.",
  ui_story_5040_50400101_49_dialog_content = "É muito estranho como você nasceu e foi criado no deserto, mas não parece ter muitos amigos na Rediesel Wrench.",
  ui_story_5040_50400101_50_dialog_content = "Eu tive que pedir a um monte de gente para encontrar seu escritório.",
  ui_story_5040_50400101_51_dialog_content = "Bem, agora cada um segue seu próprio caminho na vida.",
  ui_story_5040_50400101_52_dialog_content = "Enfim, minha história de vida não importa. Você é a estrela do show hoje.",
  ui_story_5040_50400101_53_dialog_content = "Isso mesmo! Eu nunca conheci uma futura noiva antes!",
  ui_story_5040_50400101_54_dialog_content = "Não é grande coisa. Nós, moradores do deserto, temos a mente bastante aberta quando se trata de amor.",
  ui_story_5040_50400101_55_dialog_content = "De qualquer forma, não temos muito tempo, então eu realmente quero dar uma olhada no Colossus.",
  ui_story_5040_50400101_56_dialog_content = "Leve-me em turnê, PlayerName!",
  ui_story_5040_50400101_57_dialog_content = "Ah ok. Espere por mim!",
  ui_story_5040_50400101_58_dialog_content = "Isso pode soar ruim, mas Tara realmente não me parece muito... como uma noiva.",
  ui_story_5040_50400101_59_dialog_content = "Cada um tem seu estilo, pequena celestita. Não é bom fofocar pelas costas das pessoas.",
  ui_story_5040_50400101_60_dialog_content = "Sim, suponho que você esteja certo.",
  ui_story_5040_50400101_61_dialog_content = "(Jeriah parece completamente indiferente sobre o casamento...)",
  ui_story_5040_50400101_62_dialog_content = "Ufa! Finalmente chegamos.",
  ui_story_5040_50400101_63_dialog_content = "Tara saiu para encontrar seu noivo? Lembro-me de ver o que parecia ser uma aldeia nas proximidades.",
  ui_story_5040_50400101_64_dialog_content = "Origin Town, na fronteira de Northland. A maioria das pessoas ali são tradicionais, e realizam suas cerimônias de casamento no templo.",
  ui_story_5040_50400101_65_dialog_content = "Devemos ir para lá então?",
  ui_story_5040_50400101_66_dialog_content = "Acho que esses dois provavelmente estão em outro lugar agora.",
  ui_story_5040_50400101_67_dialog_content = "(Agora que o cliente já foi deixado, preciso ficar para o casamento em si??)",
  ui_story_5040_50400101_68_dialog_content = "Você está se perguntando se você pode voltar agora?",
  ui_story_5040_50400101_69_dialog_content = "(Ela me leu como um livro.)",
  ui_story_5040_50400101_70_dialog_content = "Visto que você é amigo de Naroxel, eles certamente o convidarão para o casamento.",
  ui_story_5040_50400101_71_dialog_content = "Afinal, você já está aqui. Embora os casamentos de Northland possam não ser tão animados quanto os de Lumopolis, eles certamente têm seu próprio caráter.",
  ui_story_5040_50400101_72_dialog_content = "Bom ponto. A propósito, você parece realmente familiarizado com Northland para alguém que é da Rediesel Wrench Division.",
  ui_story_5040_50400101_73_dialog_content = "Não apenas Northland! Ela sabe tudo o que há para saber sobre o mundo, exceto coisas relacionadas ao trabalho.",
  ui_story_5040_50400101_74_dialog_content = "Ahaha, você voltou! Onde está o noivo?",
  ui_story_5040_50400101_75_dialog_content = "Tara?",
  ui_story_5040_50400101_76_dialog_content = "Desculpe tê-lo deixado esperando...!",
  ui_story_5040_50400101_77_dialog_content = "Você realmente é um lento—",
  ui_story_5040_50400101_78_dialog_content = "Aqui é Jeriah da Divisão de Chaves Rediesel da Courier Union. Eu te contei sobre ela.",
  ui_story_5040_50400101_79_dialog_content = "E esta é a pessoa que nos trouxe até aqui! Encontrar PlayerName, um celestita! Esse Colossus é realmente incrível.",
  ui_story_5040_50400101_80_dialog_content = "ele é <color=#FFB400>Adônis</color>, meu noivo... Eh, é meio estranho dizer isso. Eu costumo usar apenas o nome dele.",
  ui_story_5040_50400101_81_dialog_content = "Prazer em conhecê-los, Lady Jeriah, PlayerName.",
  ui_story_5040_50400101_82_dialog_content = "Desculpe pela pressa hoje. Naroxel é um velho amigo meu da escola. Ela está sempre lá para ajudar em uma emergência.",
  ui_story_5040_50400101_83_dialog_content = "Se me der a honra de comparecer, PlayerName, adoraríamos tê-lo no casamento também.",
  ui_story_5040_50400101_84_dialog_content = "Oh sim, você já esteve em casa?",
  ui_story_5040_50400101_85_dialog_content = "Er, ainda não.",
  ui_story_5040_50400101_86_dialog_content = "Você ainda não contou a eles?",
  ui_story_5040_50400101_87_dialog_content = "Por quanto tempo exatamente você está planejando arrastar isso?",
  ui_story_5040_50400101_88_dialog_content = "Apenas alguns dias! Eu vou amanhã, eu prometo!",
  ui_story_5040_50400101_89_dialog_content = "E amanhã será o dia seguinte! Amanhã nunca vem! Você ainda QUER contar para seus pais?",
  ui_story_5040_50400101_90_dialog_content = "...",
  ui_story_5040_50400101_91_dialog_content = "(O que está acontecendo aqui?)",
  ui_story_5040_50400101_92_dialog_content = "Parece que estamos perdendo a história de fundo aqui.",
  ui_story_5040_50400101_93_dialog_content = "Já que o jovem celestita e eu fomos convidados aqui, você não deveria nos contar o que está acontecendo?",
  ui_story_5040_50400101_94_dialog_content = "Hmph. Você diz a eles!",
  ui_story_5040_50400101_95_dialog_content = "... Você provavelmente achará isso ridículo, mas para ser honesto ... estamos tendo uma cerimônia privada e secreta.",
  ui_story_5040_50400101_96_dialog_content = "Meus pais nunca quiseram que eu me casasse com Tara.",
  ui_story_5040_50400101_97_dialog_content = "Ah. Eu vejo.",
  ui_story_5040_50400101_98_dialog_content = "O casamento entre um nortista e um morador do deserto é bastante incomum.",
  ui_story_5040_50400101_99_dialog_content = "Estou falando sério, vou contar a eles desta vez!",
  ui_story_5040_50400101_100_dialog_content = "E então vamos sair daqui! Podemos ir ao Deserto Rediesel ou a qualquer outro lugar.",
  ui_story_5040_50400101_101_dialog_content = "Quer dizer que você está fugindo?",
  ui_story_5040_50400101_102_dialog_content = "Adoraria se pudesse influenciar meus pais, mas...",
  ui_story_5040_50400101_103_dialog_content = "Mas o que? Você nem tentou.",
  ui_story_5040_50400101_104_dialog_content = "É realmente tão difícil para você falar por si mesmo?!",
  ui_story_5040_50400101_105_dialog_content = "Eu...",
  ui_story_5040_50400101_106_dialog_content = "Estou curioso, Adonis, se você já deixou Northland antes?",
  ui_story_5040_50400101_107_dialog_content = "N-Não. Tara e eu nos conhecemos aqui.",
  ui_story_5040_50400101_108_dialog_content = "Ah! A flor da estufa deseja viver a vida de uma flor silvestre. Que corajoso.",
  ui_story_5040_50400101_109_dialog_content = "Estou pronto! Enquanto duas pessoas estiverem juntas, não há nada que não possa ser superado!",
  ui_story_5040_50400101_110_dialog_content = "Realmente? Que tal superar sua incapacidade de contar a seus pais?",
  ui_story_5040_50400101_111_dialog_content = "Hum, desculpe interromper...",
  ui_story_5040_50400101_112_dialog_content = "Tenho um pacote para você, Adonis. Você disse que era urgente, então eu trouxe direto.",
  ui_story_5040_50400101_113_dialog_content = "Ora, se não é o passarinho do Norte!",
  ui_story_5040_50400101_114_dialog_content = "L-Lady Jeriah?",
  ui_story_5040_50400101_115_dialog_content = "Obrigado por sua ajuda para resolver aquelas poucas cartas que foram enviadas para cá por acidente.",
  ui_story_5040_50400101_116_dialog_content = "Foi muito mais do que alguns! Por favor, seja mais cuidadoso da próxima vez.",
  ui_story_5040_50400101_117_dialog_content = "<size=33>Eu nunca mais quero ter que lidar com uma carga de trabalho tão assustadora...</size>",
  ui_story_5040_50400101_118_dialog_content = "Obrigado, <color=#FFB400>Kya</color>.",
  ui_story_5040_50400101_119_dialog_content = "O que foi?",
  ui_story_5040_50400101_120_dialog_content = "Ah, sim, o médium que enviou esta poção disse para ter muito cuidado ao usá-la. Aparentemente, é uma coisa muito potente.",
  ui_story_5040_50400101_121_dialog_content = "Poção? Que tipo de poção?",
  ui_story_5040_50400101_122_dialog_content = "Oh, er... Eu te conto mais tarde.",
  ui_story_5040_50400101_123_dialog_content = "Apenas me diga agora! O que há com todos os seus murmúrios?!",
  ui_story_5040_50400101_124_dialog_content = "Suspirar...",
  ui_story_5040_50400101_125_dialog_content = "É um <color=#FFB400>poção para todos os fins</color> feita por um médium super místico. Pode ser usado para ajudar a mudar o estado mental de várias maneiras, como aumentar a bravura.",
  ui_story_5040_50400101_126_dialog_content = "Achei que me daria mais confiança ao lidar com meus pais.",
  ui_story_5040_50400101_127_dialog_content = "(Eu nunca ouvi falar desse tipo de poção antes!)",
  ui_story_5040_50400101_128_dialog_content = "Ha?! O que você tem? Você realmente acredita nesse lixo? Dá aqui, deixa eu ver.",
  ui_story_5040_50400101_129_dialog_content = "Não acredito que ainda existam otários se apaixonando por médiuns hoje em dia.",
  ui_story_5040_50400101_130_dialog_content = "Estamos juntos há três anos e você AINDA precisa confiar em alguma poção de óleo de cobra para contar a seus pais sobre nós?",
  ui_story_5040_50400101_131_dialog_content = "Eu tenho isso para nos ajudar!",
  ui_story_5040_50400101_132_dialog_content = "Você é realmente tão covarde? Ou você tem tão pouca fé em nosso futuro?!",
  ui_story_5040_50400101_133_dialog_content = "Adonis, precisamos mesmo confiar na força externa para manter nosso relacionamento?",
  ui_story_5040_50400101_134_dialog_content = "Se você deve ser assim, talvez seja melhor simplesmente não...",
  ui_story_5040_50400101_135_dialog_content = "<color=#e8d9bb>Barulho... Barulho...</color>",
  ui_story_5040_50400101_136_dialog_content = "<size=45>Graaaah!</size>",
  ui_story_5040_50400101_137_dialog_content = "<size=45>Graa—!!</size>",
  ui_story_5040_50400101_138_dialog_content = "Eclipsitos? De onde eles vieram?",
  ui_story_5040_50400101_139_dialog_content = "O que os Eclipsites estão fazendo aqui?!",
  ui_story_5040_50400101_140_dialog_content = "Bem, isso é inesperado. Que incômodo.",
  ui_story_5040_50400201_1_dialog_content = "<color=#e8d9bb>... Swish!!!</color>",
  ui_story_5040_50400201_2_dialog_content = "Graaah!",
  ui_story_5040_50400201_3_dialog_content = "Graa-!",
  ui_story_5040_50400201_4_dialog_content = "O que está acontecendo? De onde eles estão vindo?!",
  ui_story_5040_50400201_5_dialog_content = "Por mais irritante que isso seja, é melhor ser cauteloso.",
  ui_story_5040_50400201_6_dialog_content = "Há algo estranho naquele Eclipsite no meio.",
  ui_story_5040_50400201_7_dialog_content = "Huff... Huff...",
  ui_story_5040_50400201_8_dialog_content = "Tara! Atrás de você!",
  ui_story_5040_50400201_9_dialog_content = "Adônis, fique para trás! Deixe-nos lidar com isso!",
  ui_story_5040_50400201_10_dialog_content = "Cuidado, Tara! Aquele estranho Eclipsite parece estar de olho em você!",
  ui_story_5040_50400201_11_dialog_content = "Dar...",
  ui_story_5040_50400201_12_dialog_content = "Me dê...",
  ui_story_5040_50400201_13_dialog_content = "eu quero... quero...",
  ui_story_5040_50400201_14_dialog_content = "O que você disse?!",
  ui_story_5040_50400201_15_dialog_content = "(Está falando Universese?)",
  ui_story_5040_50400201_16_dialog_content = "Tara! Livre-se dessa poção na sua mão!",
  ui_story_5040_50400201_17_dialog_content = "Wha-",
  ui_story_5040_50400201_18_dialog_content = "<color=#e8d9bb>Whoosh - Slam!</color>",
  ui_story_5040_50400201_19_dialog_content = "Tara!!",
  ui_story_5040_50400201_20_dialog_content = "Isso é perigoso. Encontre cobertura!",
  ui_story_5040_50400201_21_dialog_content = "<color=#e8d9bb>Splash...</color>",
  ui_story_5040_50400201_22_dialog_content = "Ahhhh!",
  ui_story_5040_50400201_23_dialog_content = "Huff...! Poção...",
  ui_story_5040_50400201_24_dialog_content = "Ah...",
  ui_story_5040_50400201_25_dialog_content = "Grah! Graaaaah!",
  ui_story_5040_50400201_27_dialog_content = "Eles simplesmente decolaram?",
  ui_story_5040_50400201_28_dialog_content = "Ainda restam alguns menores.",
  ui_story_5040_50400201_29_dialog_content = "Cuide da sua noiva, Adonis.",
  ui_story_5040_50400202_1_dialog_content = "Finalmente. Todos estão bem?",
  ui_story_5040_50400202_2_dialog_content = "Tara! Tara!!",
  ui_story_5040_50400202_3_dialog_content = "Oh não! Ela está fria!",
  ui_story_5040_50400202_4_dialog_content = "Vocês dois, saiam do caminho. Deixe-me ver.",
  ui_story_5040_50400202_5_dialog_content = "Não há nenhum ferimento grave. Não parece que o Eclipsite fez muito mal a ela.",
  ui_story_5040_50400202_6_dialog_content = "Apenas alguns arranhões.",
  ui_story_5040_50400202_7_dialog_content = "Mas por que ela desmaiaria, então? Ela pode ter batido a cabeça?",
  ui_story_5040_50400202_8_dialog_content = "Em primeiro lugar, acalme-se. Ela parece bem agora, mas precisamos levá-la para um lugar seguro.",
  ui_story_5040_50400202_9_dialog_content = "Hum, ela parece ter colocado um pouco daquela poção nela.",
  ui_story_5040_50400202_10_dialog_content = "Não há nada de ruim nisso, não é?!",
  ui_story_5040_50400202_11_dialog_content = "Eu não sei! Foi você quem quis, Adônis! Acabei de entregá-lo em nome daquele médium.",
  ui_story_5040_50400202_12_dialog_content = "Não se preocupe. O mais importante agora é levá-la a um lugar para descansar.",
  ui_story_5040_50400202_13_dialog_content = "Sim. Sinto muito pelo problema, pessoal. Podemos trazê-la para minha casa?",
  ui_story_5040_50400202_14_dialog_content = "Bem, vou terminar o resto das minhas entregas. Cuidem de Tara, pessoal.",
  ui_story_5040_50400202_15_dialog_content = "<color=#e8d9bb>Toc toc toc..</color>",
  ui_story_5040_50400202_16_dialog_content = "Adônis? Você sabe que horas são—",
  ui_story_5040_50400202_17_dialog_content = "O que é isso? O que aconteceu?!",
  ui_story_5040_50400202_18_dialog_content = "É uma longa história, padre. Vamos entrar primeiro.",
  ui_story_5040_50400202_19_dialog_content = "Esses são seus amigos, Adônis? E essa garota... É a Tara?",
  ui_story_5040_50400202_20_dialog_content = "Desculpe pela inconveniência.",
  ui_story_5040_50400202_21_dialog_content = "Ela está ferida, mãe. Deparamo-nos com alguns Eclipsites... Podemos apenas acomodá-la em algum lugar primeiro? Então eu vou te contar toda a história.",
  ui_story_5040_50400202_22_dialog_content = "Eclipsos?! Devíamos ter um kit de primeiros socorros em algum lugar. Existem feridas que precisam de cuidados? Você está ferido?!",
  ui_story_5040_50400202_23_dialog_content = "Não há motivo para alarme. Ela teve alguns arranhões e provavelmente está em estado de choque. Todo mundo está bem.",
  ui_story_5040_50400202_24_dialog_content = "Eu vou cuidar dela. Vocês conversam.",
  ui_story_5040_50400202_25_dialog_content = "Então, foi isso que aconteceu...",
  ui_story_5040_50400202_26_dialog_content = "Absurdo!",
  ui_story_5040_50400202_27_dialog_content = "Como você pode não contar a sua mãe e a mim sobre isso?",
  ui_story_5040_50400202_28_dialog_content = "Se ela não tivesse sido ferida, você simplesmente fugiria e deixaria Northland?",
  ui_story_5040_50400202_29_dialog_content = "Eu...",
  ui_story_5040_50400202_30_dialog_content = "Sempre pensei que você fosse um pouco estúpido, mas não pensei que você fosse um completo idiota!",
  ui_story_5040_50400202_31_dialog_content = "Tudo que Novio te ensinou entrou por um ouvido e saiu pelo outro?!",
  ui_story_5040_50400202_32_dialog_content = "Você realmente acha que pode se virar sozinho se deixar Northland? Então tudo bem, vá! E nunca mais volte!",
  ui_story_5040_50400202_33_dialog_content = "Vamos fingir que nunca tivemos um filho!",
  ui_story_5040_50400202_34_dialog_content = "Pai, mãe, por favor... Eu não quis dizer isso!",
  ui_story_5040_50400202_35_dialog_content = "Salve suas desculpas patéticas, não quero ouvir nada disso!",
  ui_story_5040_50400202_36_dialog_content = "Seu pai só está zangado, filho.",
  ui_story_5040_50400202_37_dialog_content = "Mas realmente, Adonis, estamos perdendo o juízo com você.",
  ui_story_5040_50400202_38_dialog_content = "...",
  ui_story_5040_50400202_39_dialog_content = "Hum...",
  ui_story_5040_50400202_40_dialog_content = "(... Não posso dizer que já testemunhei algo assim antes.)",
  ui_story_5040_50400202_41_option_content = "Conforto Adônis",
  ui_story_5040_50400202_42_dialog_content = "Não leve isso a sério. Eles só estão um pouco chateados.",
  ui_story_5040_50400202_43_dialog_content = "Quer dizer, é normal que eles fiquem um pouco emocionados, de repente, ouvindo tudo isso.",
  ui_story_5040_50400202_44_dialog_content = "Mas eles ainda são seus pais. Basta falar com eles mais tarde, e tenho certeza que tudo vai dar certo.",
  ui_story_5040_50400202_45_dialog_content = "Suspiro... meus pais não vão me perdoar, e a dor de Tara também.",
  ui_story_5040_50400202_46_dialog_content = "Eu sou realmente um fracasso.",
  ui_story_5040_50400202_47_dialog_content = "(Isso não é bom. Ele parece estar preso em um ciclo de pensamentos negativos sobre si mesmo...)",
  ui_story_5040_50400202_48_option_content = "Peça ajuda a Jeriah",
  ui_story_5040_50400202_49_dialog_content = "O que devemos fazer, Jeriah?",
  ui_story_5040_50400202_50_dialog_content = "Huh? Que?",
  ui_story_5040_50400202_51_dialog_content = "(Ela estava distraída? Em um momento como este?!)",
  ui_story_5040_50400202_52_dialog_content = "O que você diz nessas circunstâncias?",
  ui_story_5040_50400202_53_dialog_content = "Este é o problema dele. Não importa o que os outros digam.",
  ui_story_5040_50400202_54_dialog_content = "De qualquer forma, mesmo que você ofereça alguns chavões gentis, isso não resolve nada.",
  ui_story_5040_50400202_55_dialog_content = "(Ela não está errada, mas certamente não posso simplesmente dizer nada!)",
  ui_story_5040_50400202_56_dialog_content = "(Isso é tão estranho... A atmosfera é tão rígida e desconfortável.)",
  ui_story_5040_50400202_57_dialog_content = "Sinto muito, pessoal. Não consigo imaginar o que você deve estar pensando.",
  ui_story_5040_50400202_58_dialog_content = "Está tudo bem. Apenas deixe-nos saber se há algo que possamos fazer para ajudar.",
  ui_story_5040_50400202_59_dialog_content = "Eh... Eu trouxe tudo isso para mim.",
  ui_story_5040_50400202_60_dialog_content = "Você também percorreu um longo caminho e eu tenho sido um péssimo anfitrião.",
  ui_story_5040_50400202_61_dialog_content = "Não se preocupe com isso agora.",
  ui_story_5040_50400202_62_dialog_content = "Por que você não o leva para clarear a cabeça, PlayerName? Eu cuidarei de Tara.",
  ui_story_5040_50400202_63_dialog_content = "OK. Vamos tomar um pouco de ar fresco.",
  ui_story_5040_50400202_64_dialog_content = "Claro...",
  ui_story_5040_50400202_65_dialog_content = "...",
  ui_story_5040_50400202_66_dialog_content = "Já era hora de você se levantar, eu acho.",
  ui_story_5040_50400202_67_dialog_content = "?!",
  ui_story_5040_50400202_68_dialog_content = "Como você sabia que eu estava acordado?",
  ui_story_5040_50400202_69_dialog_content = "Aquele Eclipsite nem mesmo atacou você.",
  ui_story_5040_50400202_70_dialog_content = "Duvido muito que você pudesse ter ficado inconsciente por tanto tempo.",
  ui_story_5040_50400202_71_dialog_content = "...",
  ui_story_5040_50400202_72_dialog_content = "Só estou aqui para ajudar Naroxel, então não vou perder muito tempo me envolvendo.",
  ui_story_5040_50400202_73_dialog_content = "Este não é o meu negócio de qualquer maneira.",
  ui_story_5040_50400202_74_dialog_content = "Mas como estou fazendo um favor a ela, vou apenas arriscar uma pergunta. O que você planeja fazer?",
  ui_story_5040_50400202_75_dialog_content = "Eu...",
  ui_story_5040_50400202_76_dialog_content = "Honestamente? Eu não faço ideia. A vida no deserto nunca foi tão complicada. Estou tão irritado.",
  ui_story_5040_50400202_77_dialog_content = "Não posso negar que Adonis me traz muita felicidade. Mas sua falta de determinação me faz pensar se realmente posso me casar com ele.",
  ui_story_5040_50400202_78_dialog_content = "O caráter de alguém não se forma nem pode ser mudado da noite para o dia. Vocês estão juntos há tanto tempo, realmente só descobriram esse problema agora?",
  ui_story_5040_50400202_79_dialog_content = "Claro que não.",
  ui_story_5040_50400202_80_dialog_content = "Três anos atrás, fui atacado por Eclipsites enquanto procurava por ruínas em Northland. Consegui fugir, mas desmaiei na beira da estrada.",
  ui_story_5040_50400202_80X1_dialog_content = "Foi ele quem me encontrou e me trouxe para casa.",
  ui_story_5040_50400202_81_dialog_content = "Houve uma forte nevasca naquele dia também. Não quero pensar no que poderia ter acontecido se ele não tivesse me encontrado.",
  ui_story_5040_50400202_82_dialog_content = "*Suspiro* Depois disso, conversamos sobre tudo e qualquer coisa, sobre coisas que o outro nunca tinha visto.",
  ui_story_5040_50400202_83_dialog_content = "Mantivemos contato depois que voltei para o deserto, trocando cartas.",
  ui_story_5040_50400202_84_dialog_content = "Ele era tão atencioso e atencioso. Eu cresci sem pais, e ninguém nunca tinha me mostrado esse tipo de cuidado antes.",
  ui_story_5040_50400202_85_dialog_content = "Fiquei realmente emocionado.",
  ui_story_5040_50400202_86_dialog_content = "Ah, então foi assim que aconteceu.",
  ui_story_5040_50400202_87_dialog_content = "Mais tarde, porém, toda vez que o assunto de deixar Northland era levantado, ele sempre parecia hesitante. Eu sinto que ele realmente mudou.",
  ui_story_5040_50400202_88_dialog_content = "Ele não é como costumava ser. É realmente tão difícil se decidir?",
  ui_story_5040_50400202_89_dialog_content = "Nunca conheci um homem tão tímido, tão indeciso! Será que ele realmente gosta de mim?",
  ui_story_5040_50400202_90_dialog_content = "Estou planejando nosso casamento há tanto tempo e até preparei um presente muito especial. Mas agora... Meh.",
  ui_story_5040_50400202_91_dialog_content = "Isso provavelmente não é apropriado, mas você já se apaixonou antes dele?",
  ui_story_5040_50400202_92_dialog_content = "Antes de Adônis? Não, ele é meu primeiro amor.",
  ui_story_5040_50400202_93_dialog_content = "Bem, não é de admirar então. Você parece ter algumas expectativas irrealistas dele.",
  ui_story_5040_50400202_94_dialog_content = "O amor pode ser uma coisa linda, mas você também tem que respeitar quem a pessoa é. Cada indivíduo é uma criatura complicada e cheia de nuances; ninguém é simplesmente preto ou branco.",
  ui_story_5040_50400202_95_dialog_content = "O-O que você quer dizer? Não tenho certeza se estou acompanhando.",
  ui_story_5040_50400202_96_dialog_content = "Heheh... Algum dia, você pode entender.",
  ui_story_5040_50400202_97_dialog_content = "...",
  ui_story_5040_50400202_98_dialog_content = "Espere! Eu entendi! Eu tenho uma ideia!",
  ui_story_5040_50400202_99_dialog_content = "?",
  ui_story_5040_50400202_102_dialog_content = "É isso!",
  ui_story_5040_50400202_103_dialog_content = "Vou fingir que estou com amnésia! Comece tudo de novo, veja como ele age comigo!",
  ui_story_5040_50400202_104_dialog_content = "...",
  ui_story_5040_50400202_105_dialog_content = "Sério?",
  ui_story_5040_50400202_106_dialog_content = "Por favor, eu te imploro! Me ajude!",
  ui_story_5040_50400202_107_dialog_content = "Se vocês dois não vão se casar, eu provavelmente deveria ir.",
  ui_story_5040_50400202_108_dialog_content = "Oh vamos lá! Não vá! O que você diria a Naroxel?",
  ui_story_5040_50400202_109_dialog_content = "Você está tentando me ameaçar?",
  ui_story_5040_50400202_110_dialog_content = "Ah! Não, não, claro que não! Como eu poderia? Você tem sido tão gentil comigo... Por favor, eu imploro!",
  ui_story_5040_50400202_111_dialog_content = "Por favor, faça isso não apenas por Naroxel, mas por uma colega da Rediesel Wrench!",
  ui_story_5040_50400202_112_dialog_content = "Você com certeza sabe como manipular as pessoas.",
  ui_story_5040_50400202_113_dialog_content = "Que dor.",
  ui_story_5040_50400202_114_dialog_content = "Pleeeaaassee! Você é o melhor!",
  ui_story_5040_50400202_115_dialog_content = "Vocês dois precisam resolver seus próprios problemas. Eu sou apenas um espectador.",
  ui_story_5040_50400202_116_dialog_content = "Depende de você como seu teatro se desenrola.",
  ui_story_5040_50400202_117_dialog_content = "<color=#e8d9bb>No dia seguinte...</color>",
  ui_story_5040_50400202_118_dialog_content = "Bom dia, Jerias, Adônis.",
  ui_story_5040_50400202_119_dialog_content = "Bom dia, jovem celestita.",
  ui_story_5040_50400202_120_dialog_content = "Manhã. Vou verificar se a Tara está acordada...",
  ui_story_5040_50400202_121_dialog_content = "*Boceja*",
  ui_story_5040_50400202_122_dialog_content = "Tara! Você está acordado! Você está bem?",
  ui_story_5040_50400202_123_dialog_content = "...?",
  ui_story_5040_50400202_124_dialog_content = "O que está errado? Por que você está me olhando assim?",
  ui_story_5040_50400202_125_dialog_content = "Quem é você?",
  ui_story_5040_50400202_126_dialog_content = "O que você está falando? Tara?",
  ui_story_5040_50400202_127_dialog_content = "Eu não te conheço. Não me toque!",
  ui_story_5040_50400202_128_dialog_content = "Onde estou? Quem é você?",
  ui_story_5040_50400202_129_dialog_content = "Lembro-me de vir para Northland ontem com Jeriah no Colossus, mas... Que estranho, não consigo lembrar por quê.",
  ui_story_5040_50400202_130_dialog_content = "Isso não é engraçado, Tara...",
  ui_story_5040_50400202_131_dialog_content = "Não é nada engraçado!",
  ui_story_5040_50400202_132_dialog_content = "Tudo bem, Adônis?",
  ui_story_5040_50400202_133_dialog_content = "(Engraçado, Tara parece estranhamente calma, considerando todas as coisas. Ela disse isso de propósito?)",
  ui_story_5040_50400202_134_dialog_content = "(Eu realmente não entendo os assuntos do coração. As coisas podem piorar se eu me intrometer, então é melhor não se intrometer agora.)",
  ui_story_5040_50400202_135_dialog_content = "Isto é minha culpa! Tudo minha culpa!",
  ui_story_5040_50400202_136_dialog_content = "Essa poção miserável! Eu gostaria de nunca ter pensado nisso!",
  ui_story_5040_50400202_137_dialog_content = "Achas que a poção é responsável pela amnésia dela?",
  ui_story_5040_50400202_138_dialog_content = "O médium disse que era capaz de produzir todos os tipos de efeitos! Não consigo pensar em outra razão para isso!",
  ui_story_5040_50400202_139_dialog_content = "Deve ser isso. A poção derramou sobre ela, bem quando ela estava chateada comigo e desejando poder esquecer tudo sobre mim! Então foi isso que a poção fez!",
  ui_story_5040_50400202_140_dialog_content = "É tudo culpa minha!",
  ui_story_5040_50400202_141_dialog_content = "Se realmente é isso, então por que não ir perguntar ao médium?",
  ui_story_5040_50400202_142_dialog_content = "Não adianta ficar aqui sentado chorando sobre o leite derramado.",
  ui_story_5040_50400202_143_dialog_content = "Psíquico?",
  ui_story_5040_50400202_144_dialog_content = "Sim, você está certo! E acabei de lembrar que às vezes eles montam uma barraca no mercado!",
  ui_story_5040_50400202_145_dialog_content = "Eu irei! Eu vou agora mesmo!",
  ui_story_5040_50400202_146_dialog_content = "*Ofegante*... O-Ali!",
  ui_story_5040_50400202_147_dialog_content = "(Uau, ele está correndo tão rápido...)",
  ui_story_5040_50400202_148_dialog_content = "Hum? Quem voce pode ser?",
  ui_story_5040_50400202_149_dialog_content = "Eu sou o cara que comprou aquela poção multiuso! Tenho uma pergunta urgente para você!",
  ui_story_5040_50400202_150_dialog_content = "Huh...? Oh sim! Aquele sujeito!",
  ui_story_5040_50400202_151_dialog_content = "Como foi? Eu coloco meu coração e alma em cada garrafa, então confio que os resultados foram os esperados?",
  ui_story_5040_50400202_152_dialog_content = "É uma longa história, mas minha noiva usou a poção acidentalmente e agora ela não consegue se lembrar de nada! Por favor, você tem que me dar o antídoto!",
  ui_story_5040_50400202_153_dialog_content = "Huh?! Mas isso não é possível...",
  ui_story_5040_50400202_154_dialog_content = "Você não disse que poderia fazer qualquer coisa? O que quer que o coração desejasse?!",
  ui_story_5040_50400202_155_dialog_content = "Eu disse isso, sim.",
  ui_story_5040_50400202_156_dialog_content = "Mas se é um antídoto que você procura... Temo que possa exigir algum esforço.",
  ui_story_5040_50400202_157_dialog_content = "Huh? Por quê?!",
  ui_story_5040_50400202_158_dialog_content = "Porque é feito de algo que poucas pessoas já viram. O tesouro mais raro do Deserto de Rediesel, as escamas brilhantes do lendário verme da areia rosa!",
  ui_story_5040_50400202_159_dialog_content = "Eu também sou do deserto. Como é que eu nunca ouvi falar disso antes?",
  ui_story_5040_50400202_160_dialog_content = "!",
  ui_story_5040_50400202_161_dialog_content = "Bem, diga-me... Se todos vocês, plebeus, soubessem disso, ainda seria raro?",
  ui_story_5040_50400202_162_dialog_content = "A maioria das pessoas nunca verá o misterioso verme da areia rosa nem uma vez na vida.",
  ui_story_5040_50400202_163_dialog_content = "(Acho que esse médium está cheio disso. E quem iria querer ver uma coisa dessas, afinal?)",
  ui_story_5040_50400202_164_dialog_content = "Suas escamas brilham com todas as cores do arco-íris, enquanto seu corpo rosa é tão magnífico e deslumbrante quanto a mais bela concha!",
  ui_story_5040_50400202_165_dialog_content = "Se você insiste neste antídoto, não pode fazê-lo sem algumas de suas escamas. Talvez você deva pensar em como conseguir alguns!",
  ui_story_5040_50400202_166_dialog_content = "V-Você está intencionalmente dificultando as coisas, não é?!",
  ui_story_5040_50400202_167_dialog_content = "Ei, não sou eu quem quer o antídoto. Eu te disse de boa fé, agora me deixe em paz. Não quero que você afete meus negócios.",
  ui_story_5040_50400202_168_dialog_content = "...",
  ui_story_5040_50400202_169_dialog_content = "É isso. Acabou.",
  ui_story_5040_50400202_170_dialog_content = "Estou disposto e capaz de fazer o que for preciso, mas lutar contra um verme da areia...? Impossível.",
  ui_story_5040_50400202_171_dialog_content = "Até os vermes do meu jardim me apavoram. Não há como eu procurar um verme da areia do deserto!",
  ui_story_5040_50400202_172_dialog_content = "Sabe... não costumo encontrar homens tão fracos quanto você.",
  ui_story_5040_50400202_173_dialog_content = "(Por favor, não piore isso!)",
  ui_story_5040_50400202_174_dialog_content = "Olhe pelo lado bom. Pelo menos ela está viva e saudável, e pelo que entendi acabou de perder a memória de seu relacionamento.",
  ui_story_5040_50400202_175_dialog_content = "Em vez de ir em busca de ganso selvagem, talvez seja melhor pensar em como reacender esse fogo romântico.",
  ui_story_5040_50400202_176_dialog_content = "E de qualquer maneira, ela não esqueceu tudo. Desde que ela esteja bem, ainda há uma chance.",
  ui_story_5040_50400202_177_dialog_content = "Deve ter havido uma razão para vocês dois estarem juntos há tanto tempo. Eu não acho que deve ser muito difícil começar de novo, por assim dizer.",
  ui_story_5040_50400202_178_dialog_content = "Sim... suponho que você esteja certo.",
  ui_story_5040_50400202_179_dialog_content = "O problema é que não tenho a menor ideia de por onde começar. Ela me vê como um completo estranho.",
  ui_story_5040_50400202_180_dialog_content = "A propósito, tenho certeza de que vocês dois se lembram de que fui enviado aqui para o casamento em nome de Naroxel.",
  ui_story_5040_50400202_181_dialog_content = "Muitas pessoas se casam no Mooncrown Day, e a maioria delas quer um mensageiro para comparecer ao casamento.",
  ui_story_5040_50400202_182_dialog_content = "Já ouvi falar dessa tradição. Aparentemente, ter um mensageiro em seu casamento pode trazer felicidade e esperança.",
  ui_story_5040_50400202_183_dialog_content = "No local. É por isso que o Union vem realizando eventos especiais do Mooncrown Day nos últimos anos, voltados para noivos e casais.",
  ui_story_5040_50400202_184_dialog_content = "Também ajuda a aliviar parte da pressão sobre os correios. Afinal, é uma das épocas mais movimentadas do ano.",
  ui_story_5040_50400202_185_dialog_content = "Realmente? Eu nunca soube disso.",
  ui_story_5040_50400202_186_dialog_content = "Certo, isso é óbvio, porque eles são voltados para casais. Duvido muito que eles estariam no radar dos solteiros perpétuos.",
  ui_story_5040_50400202_187_dialog_content = "Ei!",
  ui_story_5040_50400202_188_dialog_content = "O que você quer dizer?",
  ui_story_5040_50400202_189_dialog_content = "Em alguns lugares, esse evento já substituiu o costume de mensageiros comparecerem ao casamento como uma bênção de sorte para casais felizes.",
  ui_story_5040_50400202_190_dialog_content = "Cada filial tem seu próprio evento, e aqueles que o vivenciam com sucesso recebem o Selo Pena da Courier Union.",
  ui_story_5040_50400202_191_dialog_content = "Você deveria considerar participar de um desses eventos com Tara. Você poderia verificar o mundo exterior enquanto está nisso.",
  ui_story_5040_50400202_192_dialog_content = "Quer dizer... sair de Northland?",
  ui_story_5040_50400202_193_dialog_content = "Muitas vezes, os amnésicos podem ter memórias do passado despertadas por eventos externos. Na verdade, é um antigo remédio popular.",
  ui_story_5040_50400202_194_dialog_content = "Tudo o que estou dizendo é que o evento Courier Union pode ser uma grande oportunidade. O que você faz com isso, se for o caso, depende de você.",
  ui_story_5040_50400202_195_dialog_content = "Você não conseguirá muito fechando-se e se preocupando em casa. Se você não sair e conhecer o mundo, como saberá se há solução?",
  ui_story_5040_50400202_196_dialog_content = "Não é da minha conta, mas quem pode dizer que você não pode descobrir uma maneira de recuperar as memórias dela saindo e viajando por aí?",
  ui_story_5040_50400202_197_dialog_content = "Concordo!",
  ui_story_5040_50400202_198_dialog_content = "Eu também passei muito tempo sozinho na solidão antes. Tudo o que eu sabia sobre o mundo me foi ensinado.",
  ui_story_5040_50400202_199_dialog_content = "Foi só quando saí que percebi que o mundo mais amplo continha tanto que eu não sabia nada.",
  ui_story_5040_50400202_200_dialog_content = "Se você sair e explorar, poderá refrescar as memórias de Tara e aprender mais sobre sua condição!",
  ui_story_5040_50400202_201_dialog_content = "Pessoal...!",
  ui_story_5040_50400202_202_dialog_content = "Na verdade, eu... hum, eu realmente não sei o que dizer.",
  ui_story_5040_50400202_203_dialog_content = "Sou grato a você por me ajudar a ter ideias. Neste momento, a condição de Tara é a única coisa em que consigo pensar.",
  ui_story_5040_50400202_204_dialog_content = "Você tem razão! Eu acredito no nosso amor. Tudo o que perdemos pode ser encontrado novamente!",
  ui_story_5040_50400202_205_dialog_content = "...",
  ui_story_5040_50400202_206_dialog_content = "...",
  ui_story_5040_50400202_207_dialog_content = "Isso é o que eu estou pensando!",
  ui_story_5040_50400202_208_dialog_content = "Eu sei que você pode não concordar, mas...",
  ui_story_5040_50400202_209_dialog_content = "Vá embora então.",
  ui_story_5040_50400202_210_dialog_content = "Hã?",
  ui_story_5040_50400202_211_dialog_content = "Se vocês dois voltaram de suas viagens e ainda desejam ter uma vida juntos, bem... podemos considerar isso seriamente.",
  ui_story_5040_50400202_212_dialog_content = "S-sério?",
  ui_story_5040_50400202_213_dialog_content = "Eu não posso acreditar! Mãe, Pai, muito obrigado!",
  ui_story_5040_50400202_214_dialog_content = "Apenas lembre-se de que você nunca saiu de Northland antes. É um mundo perigoso lá fora, então você tem que ter muito cuidado.",
  ui_story_5040_50400202_215_dialog_content = "<size=33>O que há com a mudança repentina de coração, Jeriah?</size>",
  ui_story_5040_50400202_216_dialog_content = "Eu me pergunto...",
  ui_story_5040_50400202_217_dialog_content = "Posso falar com você, senhor?",
  ui_story_5040_50400202_218_dialog_content = "Hum? Quem é você?",
  ui_story_5040_50400202_219_dialog_content = "Sou Jeriah, um membro sênior do Courier Union.",
  ui_story_5040_50400202_220_dialog_content = "Oh. Eu posso te ajudar com alguma coisa? Se tiver a ver com aquele filho malcriado e ingrato de...",
  ui_story_5040_50400202_221_dialog_content = "Eu entendo perfeitamente como se sente.",
  ui_story_5040_50400202_222_dialog_content = "Tudo o que os pais querem é que seus filhos sejam felizes. Suas preocupações talvez provenham do medo de que ele seja muito ingênuo e infantil.",
  ui_story_5040_50400202_223_dialog_content = "Alguém que nunca saiu de casa, de repente querendo viver uma vida romântica e errante.",
  ui_story_5040_50400202_224_dialog_content = "Acho que também não conseguiria aceitar.",
  ui_story_5040_50400202_225_dialog_content = "É como você diz. Nada na vida é tão fácil!",
  ui_story_5040_50400202_226_dialog_content = "Adonis estudou sob a tutela do Sr. Novio quando criança. Ele é atencioso e inteligente, só um pouco ingênuo demais.",
  ui_story_5040_50400202_227_dialog_content = "Ele não experimentou muito, então tem a tendência de ver o mundo através de lentes cor-de-rosa.",
  ui_story_5040_50400202_228_dialog_content = "Então, que tal deixá-lo ter a oportunidade de experimentar as coisas?",
  ui_story_5040_50400202_229_dialog_content = "Quanto mais tempo o filhote fica no ninho, menos capacidade ele tem de sobreviver sozinho.",
  ui_story_5040_50400202_230_dialog_content = "Aqueles que não são tão fortes quanto os outros nunca irão aproveitar a felicidade ativamente, apenas a receberão passivamente.",
  ui_story_5040_50400202_231_dialog_content = "Realmente não importa onde eles vão, ou com quem.",
  ui_story_5040_50400202_232_dialog_content = "Você parece um pai sensato. O que você acha?",
  ui_story_5040_50400202_233_dialog_content = "Não sei o que você disse, mas desde que dê tudo certo.",
  ui_story_5040_50400301_1_dialog_content = "Carta para você! Aqui você vai!",
  ui_story_5040_50400301_2_dialog_content = "Obrigado, Kya. Como é que você está trabalhando tão tarde?",
  ui_story_5040_50400301_3_dialog_content = "O festival está ao virar da esquina. Espero poder entregar mais, pois tenho certeza de que as pessoas estão esperando ansiosamente.",
  ui_story_5040_50400301_4_dialog_content = "Os novatos são sempre os que mais trabalham. Tudo de bom para você!",
  ui_story_5040_50400301_5_dialog_content = "Ufa, é tão tarde.",
  ui_story_5040_50400301_6_dialog_content = "Tudo entregue, enfim. Acho que vou encerrar o dia hoje.",
  ui_story_5040_50400301_7_dialog_content = "(Esta tarde eu ouvi Adonis dizer que Tara teve amnésia... Isso poderia estar relacionado ao ataque do Eclipsite de ontem?)",
  ui_story_5040_50400301_8_dialog_content = "(É preocupante. Talvez eu devesse voltar para onde aconteceu e dar uma olhada.)",
  ui_story_5040_50400301_9_dialog_content = "(Acho que foi por aqui.)",
  ui_story_5040_50400301_10_dialog_content = "Hã?",
  ui_story_5040_50400301_11_dialog_content = "Por que é roxo aqui? É por causa daquela poção?",
  ui_story_5040_50400301_12_dialog_content = "E parece haver rastros roxos indo para a floresta.",
  ui_story_5040_50400301_13_dialog_content = "Bem, é melhor eu verificar.",
  ui_story_5040_50400301_14_dialog_content = "<color=#e8d9bb>Cow, caw—</color>",
  ui_story_5040_50400301_15_dialog_content = "(Está tão escuro! Talvez eu devesse voltar. Isso é meio assustador.)",
  ui_story_5040_50400301_16_dialog_content = "Espere... As faixas acabam aqui?",
  ui_story_5040_50400301_17_dialog_content = "Ah...",
  ui_story_5040_50400301_18_dialog_content = "<size=50>Aaaaah!</size>",
  ui_story_5040_50400301_19_dialog_content = "Quem tá aí?!",
  ui_story_5040_50400301_20_dialog_content = "H-Socorro...",
  ui_story_5040_50400301_21_dialog_content = "Me ajude...",
  ui_story_5040_50400301_22_dialog_content = "Q-Quem está falando?!",
  ui_story_5040_50400301_23_dialog_content = "Eu... Eu!",
  ui_story_5040_50400301_24_dialog_content = "Um E-Eclipsite?!",
  ui_story_5040_50400301_25_dialog_content = "N-Não... Não...",
  ui_story_5040_50400301_26_dialog_content = "Eu... Não... Danos...",
  ui_story_5040_50400301_27_dialog_content = "O que? Isso é Universo? Mas você é o Eclipsite que atacou Tara ontem!",
  ui_story_5040_50400301_28_dialog_content = "Eu... Não... Machuquei... Você...",
  ui_story_5040_50400301_29_dialog_content = "Fique atrás! O que você está fazendo?",
  ui_story_5040_50400301_30_dialog_content = "Agradar você...",
  ui_story_5040_50400301_31_dialog_content = "Me ajude...",
  ui_story_5040_50400301_32_dialog_content = "O que você disse?",
  ui_story_5040_50400301_33_dialog_content = "Minha... memória... se foi...",
  ui_story_5040_50400301_34_dialog_content = "Eu... esqueci... quem... sou eu...",
  ui_story_5040_50400301_35_dialog_content = "Assustado...",
  ui_story_5040_50400301_36_dialog_content = "Muito assustado...",
  ui_story_5040_50400301_37_dialog_content = "Você não sabe quem você é? Então por que você nos atacou ontem?",
  ui_story_5040_50400301_38_dialog_content = "Eu... Não... Ataque...",
  ui_story_5040_50400301_39_dialog_content = "Quer... poção...",
  ui_story_5040_50400301_40_dialog_content = "Poção?",
  ui_story_5040_50400301_41_dialog_content = "Eu... escondo... mercado...",
  ui_story_5040_50400301_42_dialog_content = "Ouça... poção... poderosa...",
  ui_story_5040_50400301_43_dialog_content = "Quer... usar... restaurar... memória...",
  ui_story_5040_50400301_44_dialog_content = "Mas... eles... levaram...",
  ui_story_5040_50400301_45_dialog_content = "Então foi isso que aconteceu.",
  ui_story_5040_50400301_46_dialog_content = "Mas como poderia um Eclipsite ter memórias? Você poderia ter sido um auroriano?",
  ui_story_5040_50400301_47_dialog_content = "Pense... sim... mas... esqueci...",
  ui_story_5040_50400301_48_dialog_content = "Eu estou assustado...",
  ui_story_5040_50400301_49_dialog_content = "(Todo mundo despreza os Eclipsites, mas não parece estar mentindo...)",
  ui_story_5040_50400301_50_dialog_content = "(Se alguém descobrir que estou ajudando um Eclipsite, com certeza vou perder meu emprego de mensageiro. Posso até ser preso.)",
  ui_story_5040_50400301_51_dialog_content = "Resfriado…",
  ui_story_5040_50400301_52_dialog_content = "Isso é!",
  ui_story_5040_50400301_53_dialog_content = "Tudo bem. Venha, então.",
  ui_story_5040_50400301_54_dialog_content = "Agradecer...!",
  ui_story_5040_50400301_55_dialog_content = "Só para ficar claro, qualquer negócio engraçado e eu estou alertando o Orador!",
  ui_story_5040_50400301_56_dialog_content = "Sim!",
  ui_story_5040_50400301_57_dialog_content = "Certo, e agora...?",
  ui_story_5040_50400301_58_dialog_content = "Esconda-se aqui mais um pouco.",
  ui_story_5040_50400301_59_dialog_content = "Sim, isso deve funcionar!",
  ui_story_5040_50400301_60_dialog_content = "Posso...?",
  ui_story_5040_50400301_61_dialog_content = "Tem certeza que quer usar isso? É o meu antigo vestido de dama de honra.",
  ui_story_5040_50400301_62_dialog_content = "Você meio que parece um auroriano nele, mesmo que o vestido se destaque um pouco.",
  ui_story_5040_50400301_63_dialog_content = "Obrigado... Você... Vestido... Bom...",
  ui_story_5040_50400301_64_dialog_content = "Deixa para lá. Você pode usá-lo se quiser. A propósito, meu nome é Kya. Como devo chamá-lo em público? Você se lembra do seu nome?",
  ui_story_5040_50400301_65_dialog_content = "Não... sei...",
  ui_story_5040_50400301_66_dialog_content = "Acho que vou chamá-lo de Sable por enquanto, então. Como é isso?",
  ui_story_5040_50400301_67_dialog_content = "Tá... Tá bem...",
  ui_story_5040_50400301_68_dialog_content = "Você realmente não se lembra de nada?",
  ui_story_5040_50400301_69_dialog_content = "Não...",
  ui_story_5040_50400301_70_dialog_content = "Você sempre esteve em Northland?",
  ui_story_5040_50400301_71_dialog_content = "Não... eu acho... vem de... de longe...",
  ui_story_5040_50400301_72_dialog_content = "Hmm OK. Deixe-me pensar.",
  ui_story_5040_50400301_73_dialog_content = "<color=#e8d9bb>No dia seguinte-</color>",
  ui_story_5040_50400301_74_dialog_content = "Tudo pronto?",
  ui_story_5040_50400301_75_dialog_content = "Vocês estão indo em uma longa jornada. Certifique-se de que você tem tudo o que precisa.",
  ui_story_5040_50400301_76_dialog_content = "Sim! Temos arenque enlatado, carne de veado e carne de tubarão para pelo menos um mês.",
  ui_story_5040_50400301_77_dialog_content = "Quanto aos produtos secos, temos foca, camarão e peixe liofilizados para dois meses.",
  ui_story_5040_50400301_78_dialog_content = "Depois, em caso de emergência, tem fogão portátil, martelo de dez quilos, facas, pá, chaleira, botas, capas de chuva...",
  ui_story_5040_50400301_79_dialog_content = "Espere um segundo. Você está indo para Lumópolis, certo? E não para sobreviver no deserto do Território Secreto?",
  ui_story_5040_50400301_80_dialog_content = "Certamente isso é um pouco exagerado? Que tipo de lugar você acha que Lumopolis é?",
  ui_story_5040_50400301_81_dialog_content = "Estamos visitando Lumopolis, Gannon City e Rediesel Desert nesta viagem. Quero estar o mais preparado possível.",
  ui_story_5040_50400301_82_dialog_content = "Essa é a ideia certa, mas pense no que você realmente usará. Não é como se você pudesse passar fome em qualquer um dos lugares para onde vai.",
  ui_story_5040_50400301_83_dialog_content = "...",
  ui_story_5040_50400301_84_dialog_content = "O que? Viajando? Com um estranho?!",
  ui_story_5040_50400301_85_dialog_content = "Acalme-se, Tara. É uma viagem, mas esperamos que ajude você a recuperar sua memória.",
  ui_story_5040_50400301_86_dialog_content = "Certamente você quer se lembrar?",
  ui_story_5040_50400301_87_dialog_content = "Claro que sim, mas isso é uma loucura.",
  ui_story_5040_50400301_88_dialog_content = "E de qualquer forma, só esqueci coisas relacionadas a você.",
  ui_story_5040_50400301_89_dialog_content = "Você diz isso, mas nossas memórias juntos são importantes para você e para mim.",
  ui_story_5040_50400301_90_dialog_content = "Hum...",
  ui_story_5040_50400301_91_dialog_content = "Respeito sua opinião, claro que respeito, mas quero muito pelo menos tentar recuperar sua memória viajando.",
  ui_story_5040_50400301_92_dialog_content = "O que você acha? Eu não vou te forçar a ir se você realmente não quiser.",
  ui_story_5040_50400301_93_dialog_content = "(Nossa, não acredito que vamos fazer isso. Por que sou tão molenga?)",
  ui_story_5040_50400301_94_dialog_content = "Relaxe, Tara. Eu vou cuidar de você! Não há nada com que se preocupar!",
  ui_story_5040_50400301_95_dialog_content = "Seu trabalho nesta viagem é se divertir!",
  ui_story_5040_50400301_96_dialog_content = "Eu nem sei quem você é. Não pense que você pode simplesmente ser legal comigo e eu vou me emocionar ou algo assim.",
  ui_story_5040_50400301_97_dialog_content = "Eu quero ir para casa.",
  ui_story_5040_50400301_98_dialog_content = "Vou levá-lo para casa. Nossa última parada é o deserto.",
  ui_story_5040_50400301_99_dialog_content = "Nós apenas nos divertiremos ao longo do caminho! E, enquanto isso, pensaremos em maneiras de refrescar sua memória.",
  ui_story_5040_50400301_100_dialog_content = "Multar. Qualquer que seja.",
  ui_story_5040_50400301_101_dialog_content = "Bem, então, se você está pronto, então é hora de ir. Vou levá-lo para Lumopolis, pois preciso me reportar a Naroxel de qualquer maneira.",
  ui_story_5040_50400301_102_dialog_content = "PlayerName! Espere!",
  ui_story_5040_50400301_103_dialog_content = "Hã?",
  ui_story_5040_50400301_104_dialog_content = "*Pant* Ufa, estou feliz por ter me atualizado!",
  ui_story_5040_50400301_105_dialog_content = "Se não é o passarinho do Norte! Tão fofo, mesmo quando você está sem fôlego.",
  ui_story_5040_50400301_106_dialog_content = "Por favor, não me provoque, Lady Jeriah! Então, um... Ouvi dizer que vocês estão indo para Lumopolis. Você poderia nos levar também?",
  ui_story_5040_50400301_107_dialog_content = "\"Nós\"?",
  ui_story_5040_50400301_108_dialog_content = "Ela poderia estar se referindo a esse estranho indivíduo que parece suspeitosamente com um Eclipsite?",
  ui_story_5040_50400301_109_dialog_content = "V-Você não pode simplesmente dizer a alguém que ele se parece com um Eclipsite!",
  ui_story_5040_50400301_110_dialog_content = "Este é meu, uh, parente distante! Ela se chama Sable.",
  ui_story_5040_50400301_111_dialog_content = "O-Olá... Pessoal...",
  ui_story_5040_50400301_112_dialog_content = "(Tenho certeza absoluta que este Sable está emitindo Darkflow sério...)",
  ui_story_5040_50400301_113_dialog_content = "(Mas nenhum outro sinal de alarme está tocando. É melhor esperar para ver.)",
  ui_story_5040_50400301_114_dialog_content = "Um melrozinho, hein? Roupa interessante que você está usando.",
  ui_story_5040_50400301_115_dialog_content = "S-Sable gosta de roupas formais! Ela não sai muito, então ela queria se arrumar um pouco.",
  ui_story_5040_50400301_116_dialog_content = "(Por alguma razão inexplicável, ela parece realmente gostar daquele vestido. Tipo, muito. Poderia ser algum fetiche estranho?)",
  ui_story_5040_50400301_117_dialog_content = "E vocês também querem ir para Lumópolis?",
  ui_story_5040_50400301_118_dialog_content = "Eu quero mostrar a ela durante o festival. Você pode nos levar com você, por favor? Acontece que também tenho algumas cartas que preciso entregar em Lumopolis.",
  ui_story_5040_50400301_119_dialog_content = "Claro! Se estiver tudo pronto, podemos ir agora.",
  ui_story_5040_50400301_120_dialog_content = "<color=#e8d9bb>Soroz</color>",
  ui_story_5040_50400301_121_dialog_content = "Você não vai descansar um pouco, Jeriah?",
  ui_story_5040_50400301_122_dialog_content = "Hehe... Ler é um descanso pra mim.",
  ui_story_5040_50400301_123_dialog_content = "E não estou cansado.",
  ui_story_5040_50400301_124_dialog_content = "Vá dormir um pouco se estiver cansado, pequeno celestita.",
  ui_story_5040_50400301_125_dialog_content = "Uau, isso é impressionante. Eu não consigo nem entender o que você está lendo.",
  ui_story_5040_50400301_126_dialog_content = "Cada um de nós tem seus interesses. Gosto de ler textos antigos.",
  ui_story_5040_50400301_127_dialog_content = "É muito mais relaxante do que lidar com aurorianos.",
  ui_story_5040_50400301_128_dialog_content = "Hã?",
  ui_story_5040_50400301_129_dialog_content = "A propósito, quando chegarmos a Lumopolis, você vai encontrar Naroxel?",
  ui_story_5040_50400301_130_dialog_content = "Ainda temos coisas a fazer; Vou falar com ela primeiro assim que chegarmos lá.",
  ui_story_5040_50400301_131_dialog_content = "Aaaah!",
  ui_story_5040_50400301_132_dialog_content = "?!",
  ui_story_5040_50400301_133_dialog_content = "Eclipsitos! Senhora Jeriah, PlayerName, atenção!",
  ui_story_5040_50400301_134_dialog_content = "Socorro... ne...!",
  ui_story_5040_50400301_135_dialog_content = "Como os Eclipsites embarcaram? Eles seguiram alguém?",
  ui_story_5040_50400301_136_dialog_content = "Podemos falar sobre isso mais tarde. Vamos lidar com essas coisas feias primeiro.",
  ui_story_5040_50400302_1_dialog_content = "<color=#e8d9bb>Depois de lidar com os Eclipsites, todos conseguem descansar. Eles chegaram sãos e salvos em Lumópolis...</color>",
  ui_story_5040_50400302_2_dialog_content = "Ufa, foi uma inspeção alfandegária rigorosa, mas felizmente não dificultou muito as coisas.",
  ui_story_5040_50400302_3_dialog_content = "(Se o celestita não tivesse garantido por nós, o disfarce de Sable teria sido descoberto. Graças a Deus fomos capazes de nos acompanhar para entrar na cidade.)",
  ui_story_5040_50400302_4_dialog_content = "PlayerName! Senhora Jeriah! Vou mostrar a cidade ao meu parente e entregar algumas cartas enquanto isso! Até mais!",
  ui_story_5040_50400302_5_dialog_content = "Ela simplesmente decolou!",
  ui_story_5040_50400302_6_dialog_content = "...",
  ui_story_5040_50400302_7_dialog_content = "Nossa... Então aqui é Lumópolis! Certamente tem uma vibração bem diferente.",
  ui_story_5040_50400302_8_dialog_content = "O que você acha, Tara?",
  ui_story_5040_50400302_9_dialog_content = "... Não é minha primeira vez aqui.",
  ui_story_5040_50400302_10_dialog_content = "R-Certo...",
  ui_story_5040_50400302_11_dialog_content = "Não percamos tempo. Devíamos procurar o Naroxel.",
  ui_story_5040_50400302_12_dialog_content = "Naroxel! Tem sido para sempre!",
  ui_story_5040_50400302_13_dialog_content = "Espere, quem... Adônis?!",
  ui_story_5040_50400302_14_dialog_content = "Faz muito tempo! O que o traz a Lumópolis? Seus pais e o Sr. Novio estão bem?",
  ui_story_5040_50400302_15_dialog_content = "Todo mundo está indo muito bem.",
  ui_story_5040_50400302_16_dialog_content = "E é esse que sempre menciono em minhas cartas, Tara.",
  ui_story_5040_50400302_17_dialog_content = "...",
  ui_story_5040_50400302_18_dialog_content = "Na verdade, Naroxel, voltamos a Lumopolis porque temos um pequeno problema...",
  ui_story_5040_50400302_19_dialog_content = "<color=#e8d9bb>Depois de contar a história para Naroxel...</color>",
  ui_story_5040_50400302_20_dialog_content = "Como isso é possível?",
  ui_story_5040_50400302_21_dialog_content = "Nunca ouvi falar de uma poção que possa apagar a memória das pessoas.",
  ui_story_5040_50400302_22_dialog_content = "Sim, também estou achando difícil entender.",
  ui_story_5040_50400302_23_dialog_content = "Existe algo que eu possa fazer para ajudar? Nada mesmo? Somos velhos amigos, então não tenha medo de perguntar.",
  ui_story_5040_50400302_24_dialog_content = "Na verdade, Jeriah sugeriu que participássemos dos eventos do Mooncrown Day que a Courier Union organiza em diferentes cidades para obter Feather Seals!",
  ui_story_5040_50400302_25_dialog_content = "É uma grande oportunidade para visitar novos lugares e talvez encontrar algumas pistas para a cura da amnésia de Tara.",
  ui_story_5040_50400302_26_dialog_content = "Selos de penas?",
  ui_story_5040_50400302_27_dialog_content = "É verdade, o Courier Union oferece um desafio especial aos casais a cada Mooncrown Day.",
  ui_story_5040_50400302_28_dialog_content = "Mas...",
  ui_story_5040_50400302_29_dialog_content = "Mas o que? Há algum problema?",
  ui_story_5040_50400302_30_dialog_content = "Somos velhos amigos. Lembro-me de ver você e o Sr. Novio com frequência quando estudava com a rainha no Palácio de Inverno.",
  ui_story_5040_50400302_31_dialog_content = "E é por isso que espero que sua escolha de enfrentar os desafios da vida com Tara tenha sido ponderada, acima de tudo.",
  ui_story_5040_50400302_32_dialog_content = "Mooncrown Day, eventos Courier Union, o que quer que seja... São todos superficiais.",
  ui_story_5040_50400302_33_dialog_content = "Sim, entendi.",
  ui_story_5040_50400302_34_dialog_content = "Vou apoiá-lo, caso deseje aproveitar esta oportunidade.",
  ui_story_5040_50400302_35_dialog_content = "Obrigado, Naroxel!",
  ui_story_5040_50400302_36_dialog_content = "Quanto ao evento Mooncrown Day...",
  ui_story_5040_50400302_37_dialog_content = "Este é um livro de selos comemorativos especiais, emitidos pela Courier Union para celebrar o Mooncrown Day deste ano. Venda-os todos e você passará no teste.",
  ui_story_5040_50400302_38_dialog_content = "Isso vai ser fácil! Certo, Tara?",
  ui_story_5040_50400302_39_dialog_content = "Hum, provavelmente.",
  ui_story_5040_50400302_40_dialog_content = "Mas nunca fiz um trabalho tão complicado antes.",
  ui_story_5040_50400302_41_dialog_content = "Se trabalharmos juntos, não teremos problemas. Vamos! Vamos começar.",
  ui_story_5040_50400302_42_dialog_content = "Boa sorte!",
  ui_story_5040_50400302_43_dialog_content = "Obrigado, PlayerName. E você também, Jeriah.",
  ui_story_5040_50400302_44_dialog_content = "Mas parece que eles pretendem ir para outras divisões do Courier Union. Posso incomodá-lo para acompanhá-los mais algumas vezes, PlayerName?",
  ui_story_5040_50400302_45_dialog_content = "Claro! Qualquer coisa que eu possa fazer para ajudar.",
  ui_story_5040_50400302_46_dialog_content = "Vá descansar um pouco primeiro, no entanto.",
  ui_story_5040_50400302_47_dialog_content = "Vou acompanhá-los durante os desafios.",
  ui_story_5040_50400302_48_dialog_content = "Se eu pudesse ter uma palavra, Jeriah?",
  ui_story_5040_50400302_49_dialog_content = "...",
  ui_story_5040_50400302_50_dialog_content = "Existe alguma coisa que você quer me dizer?",
  ui_story_5040_50400302_51_dialog_content = "Hehe ... Você está chegando a alguma coisa em particular?",
  ui_story_5040_50400302_52_dialog_content = "Agora, não se faça de bobo comigo. Você sabe o que havia em todos aqueles pacotes enviados para Lumopolis da Rediesel?",
  ui_story_5040_50400302_53_dialog_content = "Hum, eu me pergunto? Eu realmente não verifiquei.",
  ui_story_5040_50400302_54_dialog_content = "Como você poderia simplesmente encaminhá-los sem verificar...? Eho e eu já temos muito em nossos pratos.",
  ui_story_5040_50400302_55_dialog_content = "Mesmo antes do festival, as coisas estavam se acumulando, mas agora o Lumopolis Courier Union está realmente perdendo o juízo.",
  ui_story_5040_50400302_56_dialog_content = "Eu não contei a nenhum superior sobre isso, caso contrário, tenho certeza que você teria que enfrentar uma palestra quando voltasse.",
  ui_story_5040_50400302_57_dialog_content = "Então eu te devo uma. Mas é por isso que tenho percorrido Northland por você.",
  ui_story_5040_50400302_58_dialog_content = "Suspiro, nunca esperei que algo assim acontecesse com Adonis.",
  ui_story_5040_50400302_59_dialog_content = "Faça-me um favor e continue ajudando-os.",
  ui_story_5040_50400302_60_dialog_content = "Que incômodo ... e não tenho ideia de por que eles estão tão determinados a se acorrentar um ao outro quando claramente não são um bom par.",
  ui_story_5040_50400302_61_dialog_content = "Você não costuma dizer que todo indivíduo é complicado?",
  ui_story_5040_50400302_62_dialog_content = "Você vai entender um dia, Jeriah. Ninguém passa pela vida sozinho para sempre.",
  ui_story_5040_50400302_63_dialog_content = "Aqui estão os selos que precisamos distribuir, Tara.",
  ui_story_5040_50400302_64_dialog_content = "Você costumava me enviar o selo Mooncrown Day todos os anos, lembra? Salvei cada um deles.",
  ui_story_5040_50400302_65_dialog_content = "Realmente? Eu não me lembro.",
  ui_story_5040_50400302_66_dialog_content = "Tudo bem. De agora em diante, serei eu quem os darei a você! O design deste ano não é muito legal?",
  ui_story_5040_50400302_67_dialog_content = "Ah...! A embalagem!",
  ui_story_5040_50400302_68_dialog_content = "Cuidado!",
  ui_story_5040_50400302_69_dialog_content = "Graças a Deus não caiu no chão.",
  ui_story_5040_50400302_70_dialog_content = "Eu disse que não era bom nesse tipo de trabalho delicado. Vender armamento e outras coisas, agora é mais o meu beco.",
  ui_story_5040_50400302_71_dialog_content = "É totalmente normal que as pessoas tenham talentos diferentes. Nenhum indivíduo é o mesmo.",
  ui_story_5040_50400302_72_dialog_content = "Não se preocupe em ensacar a mercadoria. Eu cuido disso, você lida com os clientes.",
  ui_story_5040_50400302_73_dialog_content = "Eu deveria ser capaz de fazer isso, pelo menos.",
  ui_story_5040_50400302_74_dialog_content = "<color=#e8d9bb>Um tempo depois...</color>",
  ui_story_5040_50400302_75_dialog_content = "Poderia me passar também alguns selos comemorativos deste ano, por favor?",
  ui_story_5040_50400302_76_dialog_content = "Como é que os meus ainda não estão prontos?",
  ui_story_5040_50400302_77_dialog_content = "Por favor, não se preocupe. Os selos Mooncrown Day são especiais, então temos que garantir que eles sejam perfeitamente apresentados e bem embalados. Você não concorda?",
  ui_story_5040_50400302_78_dialog_content = "Olha Você aqui!",
  ui_story_5040_50400302_79_dialog_content = "Você está bem aí, Tara?",
  ui_story_5040_50400302_80_dialog_content = "Acho que você deveria se preocupar mais com os selos que está manuseando. Eu só estou falando, afinal.",
  ui_story_5040_50400302_81_dialog_content = "Parece que os negócios vão bem por aqui.",
  ui_story_5040_50400302_82_dialog_content = "Sim! Tem sido bem tranquilo até agora.",
  ui_story_5040_50400302_83_dialog_content = "Deixe-me ver... não resta muito! Estão de parabéns.",
  ui_story_5040_50400302_84_dialog_content = "Sim! O último foi vendido, acabou!",
  ui_story_5040_50400302_85_dialog_content = "Ufa, foi um trabalho árduo.",
  ui_story_5040_50400302_86_dialog_content = "Bem feito para vocês dois.",
  ui_story_5040_50400302_87_dialog_content = "Você poderia pelo menos fingir soar um pouco mais sincero.",
  ui_story_5040_50400302_88_dialog_content = "*Bocejo* Com licença, você está vendendo esses selos da Courier Union aqui?",
  ui_story_5040_50400302_89_dialog_content = "Sim, mas infelizmente acabamos de vender.",
  ui_story_5040_50400302_90_dialog_content = "Estão super giros este ano, mas não vim cá comprar selos.",
  ui_story_5040_50400302_91_dialog_content = "Eu queria saber se você tinha algum dos selos do Dia da Coroa da Lua do ano passado em algum lugar. Se o fizer... pagarei um prêmio por eles.",
  ui_story_5040_50400302_92_dialog_content = "Hum...",
  ui_story_5040_50400302_93_dialog_content = "Somos apenas uma ajuda temporária. Jerias, você conhece?",
  ui_story_5040_50400302_94_dialog_content = "Esses selos Courier Union são todos edições limitadas e não mantemos cópias de segurança.",
  ui_story_5040_50400302_95_dialog_content = "Receio que você não consiga obter nenhum dos canais oficiais.",
  ui_story_5040_50400302_96_dialog_content = "Oh, eu vejo. O que eu vou fazer...?",
  ui_story_5040_50400302_97_dialog_content = "O que parece ser o problema?",
  ui_story_5040_50400302_98_dialog_content = "Eh... Honestamente, um amigo me pediu para pegá-los.",
  ui_story_5040_50400302_99_dialog_content = "Ele envia selos do Mooncrown Day para seu parceiro na Illumina todos os anos.",
  ui_story_5040_50400302_100_dialog_content = "No entanto, sua família é um pouco conservadora e se opõe veementemente ao relacionamento deles.",
  ui_story_5040_50400302_101_dialog_content = "É por isso que ele me pediu para comprar os selos e papelaria em segredo.",
  ui_story_5040_50400302_102_dialog_content = "Ha! Muito Lumópolis.",
  ui_story_5040_50400302_103_dialog_content = "Huh? É costume em Lumópolis dar selos?",
  ui_story_5040_50400302_104_dialog_content = "Casais em Lumopolis os enviam um ao outro no Dia da Coroa da Lua, mas acho que os nobres têm práticas mais extravagantes.",
  ui_story_5040_50400302_105_dialog_content = "De fato. Prefiro me aconchegar na cama para dormir do que participar dessa farsa.",
  ui_story_5040_50400302_106_dialog_content = "Mas o problema é que seu companheiro perdeu os selos comemorativos do ano passado...",
  ui_story_5040_50400302_107_dialog_content = "Ela se sentiu tão culpada e triste por isso. Meu amigo não suportou vê-la tão chateada, então ele me pediu para encontrar outra cópia daqueles selos para ele.",
  ui_story_5040_50400302_108_dialog_content = "São apenas selos. Ele não pode simplesmente pegar outra coisa para ela?",
  ui_story_5040_50400302_109_dialog_content = "Não é nada igual! Você não pode simplesmente substituir algo que está cheio de memórias compartilhadas por outra coisa.",
  ui_story_5040_50400302_110_dialog_content = "Uma nobre Lumo e uma garota Illuminana... Interessante.",
  ui_story_5040_50400302_111_dialog_content = "Eles devem encontrar todos os tipos de obstáculos em seu relacionamento.",
  ui_story_5040_50400302_112_dialog_content = "Bem, ainda há luz no fim do túnel para eles. Mas acho que você poderia dizer que eles têm um caminho difícil pela frente.",
  ui_story_5040_50400302_113_dialog_content = "Ele tem trabalhado lentamente para convencer seus pais e outros parentes, tentando trazê-los de volta.",
  ui_story_5040_50400302_114_dialog_content = "Provavelmente ainda levará algum tempo, no entanto.",
  ui_story_5040_50400302_115_dialog_content = "Lumopolis realmente faz jus à sua reputação como um lugar onde as famílias ficam obcecadas em se casar dentro de sua classe.",
  ui_story_5040_50400302_116_dialog_content = "Sim? Se você me perguntar, nem mesmo duas pessoas de famílias nobres têm felicidade automaticamente garantida.",
  ui_story_5040_50400302_117_dialog_content = "O Tribunal de Justiça onde trabalho recebe pedidos de divórcio de nobres o tempo todo.",
  ui_story_5040_50400302_118_dialog_content = "Cada caso tem suas próprias reviravoltas bizarras, e nunca são claras, graças à disputa de interesses entre os nobres.",
  ui_story_5040_50400302_119_dialog_content = "Todo mundo tenta evitar assumir esses casos.",
  ui_story_5040_50400302_120_dialog_content = "Então até os nobres podem ter problemas no paraíso...",
  ui_story_5040_50400302_121_dialog_content = "Ah, com certeza! Portanto, meu conselho é sempre seguir seu coração.",
  ui_story_5040_50400302_122_dialog_content = "Afinal, até mesmo se contentar com alguém de status semelhante não garante a felicidade.",
  ui_story_5040_50400302_123_dialog_content = "Quão raro é ouvir tais palavras da boca do nobre de Lumópolis!",
  ui_story_5040_50400302_124_dialog_content = "Só posso dizer que cada um faz suas próprias escolhas. Os sentimentos não podem ser controlados. Amor é amor.",
  ui_story_5040_50400302_125_dialog_content = "Apaixonar-se por alguém não é algo que alguém possa controlar. Não importa quem são ou de onde são.",
  ui_story_5040_50400302_126_dialog_content = "Eu sei disso muito bem.",
  ui_story_5040_50400302_127_dialog_content = "Bem dito, de fato! Eu concordo totalmente!",
  ui_story_5040_50400302_128_dialog_content = "Oh? Você pode ter alguém em sua mente?",
  ui_story_5040_50400302_129_dialog_content = "Não... É que eu conheci um cara tão engraçado e peludo há um tempo atrás.",
  ui_story_5040_50400302_130_dialog_content = "Também poderia falar Universese! Eu não podia acreditar.",
  ui_story_5040_50400302_131_dialog_content = "Na verdade, enviei uma carta ontem. Não sei quando posso receber uma resposta, no entanto.",
  ui_story_5040_50400302_132_dialog_content = "Não há realmente nada que possamos fazer para ajudar a amiga dela, Jeriah?",
  ui_story_5040_50400302_133_dialog_content = "...",
  ui_story_5040_50400302_134_dialog_content = "Bem, eu realmente não sei, mas...",
  ui_story_5040_50400302_135_dialog_content = "Se ele estiver disposto a pagar, pode ser uma boa ideia convidar Allura em Umbraton. Ela tem uma coleção e tanto.",
  ui_story_5040_50400302_136_dialog_content = "Tenho certeza de que uma coisa tão pequena não seria um problema.",
  ui_story_5040_50400302_137_dialog_content = "Eu vejo! Muito obrigado pela sua ajuda!",
  ui_story_5040_50400302_138_dialog_content = "Eu poderia muito bem ir para Umbraton agora, enquanto ainda não estou com sono.",
  ui_story_5040_50400302_139_dialog_content = "Você é como uma enciclopédia ambulante, Jeriah.",
  ui_story_5040_50400302_140_dialog_content = "Espero que ela encontre o que procura.",
  ui_story_5040_50400302_141_dialog_content = "De qualquer forma, concluímos a tarefa! Vamos buscar esse selo!",
  ui_story_5040_50400302_142_dialog_content = "Claro...",
  ui_story_5040_50400302_143_dialog_content = "O que há de errado, Tara? Está se sentindo bem?",
  ui_story_5040_50400302_144_dialog_content = "Não é nada, estou bem.",
  ui_story_5040_50400302_145_dialog_content = "...",
  ui_story_5040_50400302_146_dialog_content = "<color=#e8d9bb>Enquanto isso...</color>",
  ui_story_5040_50400302_147_dialog_content = "Nada mesmo...?",
  ui_story_5040_50400302_148_dialog_content = "Você ainda não se lembra de nada?",
  ui_story_5040_50400302_149_dialog_content = "Não... Nada... Desculpe...",
  ui_story_5040_50400302_150_dialog_content = "Não precisa se desculpar, você não fez nada de errado.",
  ui_story_5040_50400302_151_dialog_content = "O que mais poderia nos dar uma pista...?",
  ui_story_5040_50400302_152_dialog_content = "Ai... Isso...",
  ui_story_5040_50400302_153_dialog_content = "O quê?",
  ui_story_5040_50400302_154_dialog_content = "Segurando... na... mão...",
  ui_story_5040_50400302_155_dialog_content = "Quem? Segurando o quê?",
  ui_story_5040_50400302_156_dialog_content = "Ele...",
  ui_story_5040_50400302_157_dialog_content = "Selos...",
  ui_story_5040_50400302_158_dialog_content = "Selos?? Aquele cara que acabou de passar? Sim, ele tinha aqueles selos do Mooncrown Day.",
  ui_story_5040_50400302_159_dialog_content = "Eles te lembram de algo?",
  ui_story_5040_50400302_160_dialog_content = "Parece... sim...",
  ui_story_5040_50400302_161_dialog_content = "Huh? De onde você tirou isso? Todos parecem ser velhos selos do Dia da Coroa da Lua!",
  ui_story_5040_50400302_162_dialog_content = "Pense... eu tenho... muitos...",
  ui_story_5040_50400302_163_dialog_content = "Muitos o quê? Selos como este?",
  ui_story_5040_50400302_164_dialog_content = "Sim...",
  ui_story_5040_50400302_165_dialog_content = "Normalmente, quando as pessoas têm muitos selos, significa que enviam muitas correspondências, certo?",
  ui_story_5040_50400302_166_dialog_content = "Isso me dá uma idéia! Por que não levo você para dar uma olhada na correspondência não reclamada do Sindicato? Talvez encontremos algo.",
  ui_story_5040_50400302_167_dialog_content = "Obrigado... Kya...",
  ui_story_5040_50400302_168_dialog_content = "<color=#e8d9bb>Um tempo depois...</color>",
  ui_story_5040_50400302_169_dialog_content = "Nada?",
  ui_story_5040_50400302_170_dialog_content = "Não...",
  ui_story_5040_50400302_171_dialog_content = "Hum. Bem, talvez você estivesse em uma região da União diferente de Lumopolis.",
  ui_story_5040_50400302_172_dialog_content = "Pelo menos temos uma pista agora, no entanto. É melhor do que apenas vagar sem rumo como antes.",
  ui_story_5040_50400302_173_dialog_content = "Vamos marcar junto com PlayerName e os outros e verifique as divisões Illumina e Rediesel Wrench.",
  ui_story_5040_50400302_174_dialog_content = "Não se preocupe. Nós o encontraremos!",
  ui_story_5040_50400302_175_dialog_content = "K... Kya...",
  ui_story_5040_50400302_176_dialog_content = "Obrigada...",
  ui_story_5040_50400302_177_dialog_content = "Por que você... me ajuda...?",
  ui_story_5040_50400302_178_dialog_content = "Eu realmente não me conheço. Talvez eu simplesmente não consiga passar quando alguém precisa de ajuda.",
  ui_story_5040_50400302_179_dialog_content = "(Devo estar louco, ajudando um Eclipsite! O que diabos estou pensando?!)",
  ui_story_5040_50400302_180_dialog_content = "(O que Esmeralda faria?)",
  ui_story_5040_50400401_1_dialog_content = "<color=#e8d9bb>Após Adonis e os outros reportarem a Naroxel...</color>",
  ui_story_5040_50400401_2_dialog_content = "Então este é o selo de penas da Courier Union? Eu nunca vi um antes.",
  ui_story_5040_50400401_3_dialog_content = "Parece tão bem elaborado!",
  ui_story_5040_50400401_4_dialog_content = "Venha olhar, Tara!",
  ui_story_5040_50400401_5_dialog_content = "... Não aja de repente como se fôssemos tão íntimos ou algo assim.",
  ui_story_5040_50400401_6_dialog_content = "Selos de penas são principalmente objetos comemorativos. Eles têm muito pouco valor monetário por conta própria.",
  ui_story_5040_50400401_7_dialog_content = "Mesmo antes da existência da União, os mensageiros eram bem-vindos como portadores de boas novas onde quer que fossem.",
  ui_story_5040_50400401_8_dialog_content = "Os nobres também contratavam mensageiros para casamentos?",
  ui_story_5040_50400401_9_dialog_content = "Sim, mas especialmente os nobres de Lumopolis. Na verdade, muitos gastariam extraordinariamente para contratar mensageiros para servir como testemunhas em seus casamentos.",
  ui_story_5040_50400401_10_dialog_content = "É também por isso que a Courier Union procurou acabar com essa tradição com outra coisa.",
  ui_story_5040_50400401_11_dialog_content = "Especialmente em Lumópolis. O Dia da Coroa da Lua se originou aqui, então as pessoas daqui levam suas tradições a sério.",
  ui_story_5040_50400401_12_dialog_content = "Que bando de esquisitos. Não comemoramos feriados inúteis como estes no deserto.",
  ui_story_5040_50400401_13_dialog_content = "O que há de errado em observar os feriados? Além disso, este é tão romântico.",
  ui_story_5040_50400401_14_dialog_content = "Em Lumopolis, onde toda a sociedade é fortemente estratificada, esses tipos de formalidades são apenas um meio de controlar as classes mais baixas.",
  ui_story_5040_50400401_15_dialog_content = "Esta, por sua vez, é a razão pela qual sua importância é tão enfatizada.",
  ui_story_5040_50400401_16_dialog_content = "É muita coisa para assimilar...",
  ui_story_5040_50400401_17_dialog_content = "Ela está sempre falando sobre coisas que eu não consigo entender.",
  ui_story_5040_50400401_18_dialog_content = "Então, o que devemos saber?",
  ui_story_5040_50400401_19_dialog_content = "Jeriah, vamos dar uma volta. Eu preciso tirar minha mente das coisas.",
  ui_story_5040_50400401_20_dialog_content = "Então eu irei com—",
  ui_story_5040_50400401_21_dialog_content = "PlayerName, que tal você fazer parceria com ele por enquanto? Preciso de um pouco de paz e sossego agora.",
  ui_story_5040_50400401_22_dialog_content = "Claro, isso funciona.",
  ui_story_5040_50400401_23_dialog_content = "...",
  ui_story_5040_50400401_24_dialog_content = "Suspirar...",
  ui_story_5040_50400401_25_dialog_content = "Você está cansado de seu pequeno ato?",
  ui_story_5040_50400401_26_dialog_content = "Eu só... não sei se estou fazendo a coisa certa. Adonis realmente parece acreditar que perdi minhas memórias.",
  ui_story_5040_50400401_27_dialog_content = "Estou tão em conflito. Na época em que vendíamos selos juntos, eu sentia como se ele ainda fosse a mesma pessoa amável e gentil que eu sempre conhecera.",
  ui_story_5040_50400401_28_dialog_content = "Mas isso não resolve todos os problemas entre nós. Eu sei que assim que algo grande acontecer, ele voltará a ser um covarde.",
  ui_story_5040_50400401_29_dialog_content = "Talvez sejamos muito diferentes para ficarmos juntos.",
  ui_story_5040_50400401_30_dialog_content = "Exceto porque eu gosto muito dele, é difícil para mim aceitar esse fato.",
  ui_story_5040_50400401_31_dialog_content = "Podemos escolher ser quem quisermos, mas não podemos forçar os outros a serem quem queremos que sejam.",
  ui_story_5040_50400401_32_dialog_content = "Quando você escolhe estar com alguém, você tem que aceitar tudo o que vem depois.",
  ui_story_5040_50400401_33_dialog_content = "Quanto mais você ama alguém, mais doloroso é deixá-lo ir.",
  ui_story_5040_50400401_34_dialog_content = "... Você está falando por experiência?",
  ui_story_5040_50400401_35_dialog_content = "Claro que não. Por que eu conscientemente me colocaria nesse tipo de dor?",
  ui_story_5040_50400401_36_dialog_content = "Ainda assim, estar com ele me trouxe muita alegria. A maior parte do tempo que passamos juntos foi feliz.",
  ui_story_5040_50400401_37_dialog_content = "Você pode simplesmente estar projetando devido a se sentir inseguro sobre seu relacionamento. No final, relacionamentos são sobre troca de valores.",
  ui_story_5040_50400401_38_dialog_content = "E agora, o que ele está oferecendo não atende às suas expectativas. Não é mesmo?",
  ui_story_5040_50400401_39_dialog_content = "Eu...",
  ui_story_5040_50400401_40_dialog_content = "Não sei... não quero ver nosso relacionamento assim, como se não passasse de uma transação.",
  ui_story_5040_50400401_41_dialog_content = "Qualquer coisa que você diga.",
  ui_story_5040_50400401_42_dialog_content = "Precisamos de experiência para saber o que realmente queremos no fundo. Como as coisas já estão onde estão agora, eu não me preocuparia muito.",
  ui_story_5040_50400401_43_dialog_content = "Este é o seu negócio, afinal. O que as outras pessoas dizem não importa.",
  ui_story_5040_50400401_44_dialog_content = "Leve o tempo que precisar para descobrir e ouça seu coração quando finalmente fizer uma escolha.",
  ui_story_5040_50400401_45_dialog_content = "...",
  ui_story_5040_50400401_46_dialog_content = "Bem-vindo a Umbraton! Parece muito diferente de Lumopolis, hein?",
  ui_story_5040_50400401_47_dialog_content = "Sim...",
  ui_story_5040_50400401_48_dialog_content = "Está vendo aquela ilha flutuando bem acima de nós? Isso é Lumópolis.",
  ui_story_5040_50400401_49_dialog_content = "Para muitas pessoas em Umbraton, este feriado é a oportunidade perfeita para arrecadar lucros.",
  ui_story_5040_50400401_50_dialog_content = "Há muitas pessoas bizarras aqui, mas também há muitas coisas fascinantes e interessantes.",
  ui_story_5040_50400401_51_dialog_content = "Qualquer coisa que você está interessado em verificar?",
  ui_story_5040_50400401_52_dialog_content = "...",
  ui_story_5040_50400401_53_dialog_content = "(Acabou... Ele parece ter perdido toda a sua energia.)",
  ui_story_5040_50400401_54_dialog_content = "Suspiro... Eu simplesmente não sei mais o que fazer.",
  ui_story_5040_50400401_55_dialog_content = "Nada do que eu faço é certo... Se ao menos ela me desse uma dica! Então talvez eu saberia o que fazer...",
  ui_story_5040_50400401_56_dialog_content = "É...",
  ui_story_5040_50400401_57_dialog_content = "Costumávamos conversar sobre tudo, principalmente quando se tratava de coisas que não entendíamos sobre o nosso mundo. Mas agora... como as coisas acabaram assim?",
  ui_story_5040_50400401_58_dialog_content = "PlayerName, você é um celestita, deve ter garotas fazendo fila do lado de fora da sua porta. Você entende o que estou passando?",
  ui_story_5040_50400401_59_dialog_content = "U-Uh, isso é um pouco exagerado.",
  ui_story_5040_50400401_60_dialog_content = "Mas acho que, desde que os sentimentos de duas pessoas uma pela outra sejam fortes o suficiente, elas podem superar qualquer dificuldade.",
  ui_story_5040_50400401_61_dialog_content = "Meus dois bons amigos e eu passamos por muita coisa juntos. Nós até resgatamos uns aos outros da porta da morte algumas vezes!",
  ui_story_5040_50400401_62_dialog_content = "Mas todas essas experiências fortaleceram nossa confiança uns nos outros. Estamos dispostos a fazer qualquer coisa um pelo outro, mesmo que isso signifique nos colocar em perigo.",
  ui_story_5040_50400401_63_dialog_content = "Tenho certeza de que você e Tara são iguais.",
  ui_story_5040_50400401_64_dialog_content = "O-Claro que eu faria qualquer coisa por ela! Eu até arriscaria minha vida, se fosse preciso!",
  ui_story_5040_50400401_65_dialog_content = "É que às vezes sou tão indeciso... Não consigo tomar decisões em frações de segundo como as outras pessoas. Essa pode ser a razão pela qual ela pensa que sou deficiente como homem...",
  ui_story_5040_50400401_66_dialog_content = "Não diga isso, Adônis! Quem disse que um homem tem que ser de um jeito ou de outro? Somos todos diferentes, e tudo bem.",
  ui_story_5040_50400401_67_dialog_content = "Ninguém é perfeito, mas se vocês dois ainda estão juntos... Isso significa que há algo em você que ela acha atraente o suficiente para ficar por perto!",
  ui_story_5040_50400401_68_dialog_content = "*Soluçando* Eu... eu só espero que ela realmente se sinta assim!!",
  ui_story_5040_50400401_69_dialog_content = "Pronto, pronto, não chore...",
  ui_story_5040_50400401_70_dialog_content = "Oooooh!",
  ui_story_5040_50400401_71_dialog_content = "Estamos interrompendo um momento bonito e arrojado?",
  ui_story_5040_50400401_72_dialog_content = "Gin, me sinto tão inspirada!",
  ui_story_5040_50400401_73_dialog_content = "Algemados pelas expectativas da sociedade, dois amantes que não podem ser vistos juntos...",
  ui_story_5040_50400401_74_dialog_content = "Eles estão claramente se abraçando em plena luz do dia.",
  ui_story_5040_50400401_75_dialog_content = "Mesmo sendo o Dia da Coroa da Lua, os dois amantes não têm escolha a não ser se encontrar em um canto isolado de Umbraton, longe de olhares indiscretos...",
  ui_story_5040_50400401_76_dialog_content = "Há pessoas em todos os lugares...",
  ui_story_5040_50400401_77_dialog_content = "Não é a coisa mais linda que você já viu, Gin? Eu quero fazer tudo ao meu alcance para ajudá-los! E talvez ganhar alguma coisa para mim, já que estou nisso!",
  ui_story_5040_50400401_78_dialog_content = "Isso soa como uma ideia maravilhosa.",
  ui_story_5040_50400401_79_dialog_content = "Er, acho que você não entendeu...",
  ui_story_5040_50400401_80_dialog_content = "Admiro sua coragem, cara. Posso perguntar seu nome?",
  ui_story_5040_50400401_81_dialog_content = "M-Eu? Meu nome é Adônis...",
  ui_story_5040_50400401_82_dialog_content = "Você tem um ar de grandeza, Adonis. Aquele que o coloca muito acima de todos os outros, especialmente aquele cara ao seu lado.",
  ui_story_5040_50400401_83_dialog_content = "Por que você está atirando em mim de repente?!",
  ui_story_5040_50400401_84_dialog_content = "Você deve ser do tipo que faria qualquer coisa por amor. Eu posso dizer só de olhar para você.",
  ui_story_5040_50400401_85_dialog_content = "Meu pirulito também sente o mesmo.",
  ui_story_5040_50400401_86_dialog_content = "Mas vamos dispensar a conversa fiada desnecessária. Para o Dia da Coroa da Lua deste ano, temos uma pintura muito rara à venda, que acredito que combina perfeitamente com você.",
  ui_story_5040_50400401_87_dialog_content = "Ele retrata a trágica história de um amor proibido entre dois amantes infelizes...",
  ui_story_5040_50400401_88_dialog_content = "Esta rara e bela pintura pode ser sua por um preço muito razoável, mas apenas por hoje!",
  ui_story_5040_50400401_89_dialog_content = "Uh o quê? EU...",
  ui_story_5040_50400401_90_dialog_content = "Ah-ah-ah! Nem outra palavra! É claro como o dia que você está morrendo de vontade de comprar esta pintura!",
  ui_story_5040_50400401_91_dialog_content = "Eu concordo.",
  ui_story_5040_50400401_92_dialog_content = "Eu...",
  ui_story_5040_50400401_93_dialog_content = "Parem com isso, vocês dois!",
  ui_story_5040_50400401_94_dialog_content = "Não estrague sua primeira vez aqui em Umbraton!",
  ui_story_5040_50400401_95_dialog_content = "Por favor, estamos apenas tentando ganhar a vida aqui. Estávamos apenas conduzindo uma transação razoável com este bom cavalheiro, nada mais.",
  ui_story_5040_50400401_96_dialog_content = "Não havia nada de razoável nisso!",
  ui_story_5040_50400401_97_dialog_content = "Eu adoraria provar que você está errado... mas acho que acabei de ouvir algo.",
  ui_story_5040_50400401_98_dialog_content = "<size=45>Aaaah!!</size>",
  ui_story_5040_50400401_99_dialog_content = "O que há de errado?!",
  ui_story_5040_50400401_100_dialog_content = "EE-Eclipsites!",
  ui_story_5040_50400401_101_dialog_content = "O que os Eclipsites estão fazendo aqui?!",
  ui_story_5040_50400401_102_dialog_content = "<size=45>Graah!</size>",
  ui_story_5040_50400401_103_dialog_content = "Ficar no caminho dos meus negócios, que cansativo.",
  ui_story_5040_50400401_104_dialog_content = "E-Eclipsitos!",
  ui_story_5040_50400401_105_dialog_content = "Proteja-se, Adônis! Nós vamos encontrar uma maneira de lidar com isso!",
  ui_story_5040_50400402_1_dialog_content = "... Cara, esses dois não perderam um segundo, né?",
  ui_story_5040_50400402_2_dialog_content = "Tudo bem, Adônis?",
  ui_story_5040_50400402_3_dialog_content = "S-Sim, estou bem.",
  ui_story_5040_50400402_4_dialog_content = "Desculpe por ser tão inútil... Apenas a visão daqueles Eclipsites fez minhas pernas cederem.",
  ui_story_5040_50400402_5_dialog_content = "Não se preocupe com isso. A maioria das pessoas não está acostumada a lutar contra esses monstros.",
  ui_story_5040_50400402_6_dialog_content = "Pelo menos Hachi e Gin fugiram. Eles são impossíveis.",
  ui_story_5040_50400402_7_dialog_content = "Esses caras tendem a ir para os alvos mais fáceis, então lembre-se de recusá-los sem rodeios na próxima vez que você topar com eles.",
  ui_story_5040_50400402_8_dialog_content = "Suspiro... Por que eu sou sempre assim?",
  ui_story_5040_50400402_9_dialog_content = "Perdoe-me, mas você não estava vendendo selos do Mooncrown Day antes?",
  ui_story_5040_50400402_10_dialog_content = "Hã?",
  ui_story_5040_50400402_11_dialog_content = "Você está falando de Adônis? Ele estava com Tara e Jeriah do Courier Union mais cedo.",
  ui_story_5040_50400402_12_dialog_content = "Ah, então esse é o seu nome.",
  ui_story_5040_50400402_13_dialog_content = "E você é...?",
  ui_story_5040_50400402_14_dialog_content = "Saudações! Meu nome é Tina e sou juíza do Lumo Hall of Justice. Por favor, desculpe-me por esquecer de me apresentar antes.",
  ui_story_5040_50400402_15_dialog_content = "Prazer em conhecê-la, Tina. Eu sou PlayerName.",
  ui_story_5040_50400402_16_dialog_content = "Acabei de perguntar a seus amigos sobre os selos do Dia da Coroa da Lua do ano passado esta manhã.",
  ui_story_5040_50400402_17_dialog_content = "Graças a esse mensageiro, encontrei o que procurava aqui em Umbraton.",
  ui_story_5040_50400402_18_dialog_content = "Realmente? É tudo graças a Jeriah... Fico feliz que ela tenha ajudado, considerando que eu não pude fazer nada.",
  ui_story_5040_50400402_19_dialog_content = "De qualquer forma, tenho certeza de que seu amigo e seu amante estão felizes por você ter encontrado o selo do ano passado.",
  ui_story_5040_50400402_20_dialog_content = "Você está absolutamente correto. Ele estava praticamente pulando de alegria quando eu dei a ele.",
  ui_story_5040_50400402_21_dialog_content = "Ele me agradeceu várias vezes antes de finalmente correr para casa o mais rápido que pôde para escrever sua carta de amor.",
  ui_story_5040_50400402_22_dialog_content = "O comerciante de quem comprei carregava muitos itens interessantes. Eu estava indo ver mais produtos dela quando encontrei vocês dois.",
  ui_story_5040_50400402_23_dialog_content = "... Está se sentindo bem, senhor? Você parece um pouco pálido... Aconteceu alguma coisa?",
  ui_story_5040_50400402_24_dialog_content = "Na verdade eu...",
  ui_story_5040_50400402_25_dialog_content = "Ah... entendi agora! Não é de admirar que eu sentisse que havia algo estranho entre vocês dois!",
  ui_story_5040_50400402_26_dialog_content = "Então você vai para Illumina, sim? Nesse caso, eu poderia perguntar à amante do meu amigo se ela conhece uma cura?",
  ui_story_5040_50400402_27_dialog_content = "H-Huh?",
  ui_story_5040_50400402_28_dialog_content = "Serei franco com você. Ela trabalha para o Black Umbrella Laboratories em Gannon City.",
  ui_story_5040_50400402_29_dialog_content = "Se existe um remédio, o conhecimento dela pode ser útil para você! Apenas mencione meu nome para ela e ela o ajudará como puder.",
  ui_story_5040_50400402_30_dialog_content = "Não posso garantir que ela terá as respostas que você procura, mas encaminhá-lo a ela é o mínimo que posso fazer por você.",
  ui_story_5040_50400402_31_dialog_content = "Isso é mais do que suficiente! Muito obrigado, Dona Tina!",
  ui_story_5040_50400402_32_dialog_content = "Nós vamos visitá-la assim que estivermos lá!",
  ui_story_5040_50400402_33_dialog_content = "Vê, Adônis? Ainda há esperança para vocês!",
  ui_story_5040_50400402_34_dialog_content = "Desejo-lhe viagens seguras e boa sorte em sua jornada.",
  ui_story_5040_50400402_35_dialog_content = "Yaaaaawn... Estou começando a me sentir um pouco cansado. Acho que é hora de ir para casa e descansar um pouco...",
  ui_story_5040_50400402_36_dialog_content = "Parece que sua determinação está finalmente começando a valer a pena, Adonis. Visitaremos aquela senhora assim que chegarmos à cidade de Gannon.",
  ui_story_5040_50400402_37_dialog_content = "Sim! Obrigado novamente, PlayerName.",
  ui_story_5040_50400402_38_dialog_content = "<color=#e8d9bb>Aquela noite...</color>",
  ui_story_5040_50400402_39_dialog_content = "Suspiro ... Este lugar também não funcionou, hein?",
  ui_story_5040_50400402_40_dialog_content = "Estou tentando o meu melhor...",
  ui_story_5040_50400402_41_dialog_content = "Desculpe, não quis te estressar. Sem pressão, leve o tempo que precisar.",
  ui_story_5040_50400402_42_dialog_content = "Devíamos voltar, de qualquer maneira. Acho que já percorremos terreno suficiente em Umbraton por hoje.",
  ui_story_5040_50400402_43_dialog_content = "É mais seguro em Lumopolis à noite.",
  ui_story_5040_50400402_44_dialog_content = "Umbra...ton... Lumo...polis...",
  ui_story_5040_50400402_45_dialog_content = "Lumópolis...",
  ui_story_5040_50400402_46_dialog_content = "Qual é o problema? Por que você está tão preso a Lumopolis?",
  ui_story_5040_50400402_47_dialog_content = "Você se lembrou de algo?",
  ui_story_5040_50400402_48_dialog_content = "Lumópolis... Uma longa viagem...",
  ui_story_5040_50400402_49_dialog_content = "Eu vim aqui... para conhecer alguém...",
  ui_story_5040_50400402_50_dialog_content = "Mas quem...? Quem eu prometi encontrar... em Lumópolis...?",
  ui_story_5040_50400402_51_dialog_content = "Ele... Ele nunca veio...",
  ui_story_5040_50400402_52_dialog_content = "O que? Você quer dizer que uma vez veio para Lumopolis de outro lugar?",
  ui_story_5040_50400402_53_dialog_content = "Sim... eu... sinto...",
  ui_story_5040_50400402_54_dialog_content = "Isso significa que você não é daqui. Você se lembra de onde você veio?",
  ui_story_5040_50400402_55_dialog_content = "Eu acho... muito, muito longe...",
  ui_story_5040_50400402_56_dialog_content = "Um lugar distante, hein? Eu vejo...",
  ui_story_5040_50400402_57_dialog_content = "Tudo bem, não exagere. Como você não é de Lumópolis, teremos que ir a outro lugar e continuar procurando.",
  ui_story_5040_50400402_58_dialog_content = "Eu penso PlayerName e os outros vão para Gannon City amanhã. Vamos marcar junto com eles.",
  ui_story_5040_50400402_59_dialog_content = "Talvez o Courier Union ali nos dê algumas respostas.",
  ui_story_5040_50400402_60_dialog_content = "Tá bom...",
  ui_story_5040_50400402_61_dialog_content = "<color=#e8d9bb>No dia seguinte...</color>",
  ui_story_5040_50400402_62_dialog_content = "Certo, todos estão prontos? Não se esqueça de nada que possa precisar!",
  ui_story_5040_50400402_63_dialog_content = "Heheh... Faz tempo que não vou ao Illumina. Eu me pergunto como esses passarinhos estão fazendo?",
  ui_story_5040_50400402_64_dialog_content = "Por favor, não crie mais problemas para eles, Jeriah.",
  ui_story_5040_50400402_65_dialog_content = "A Federação Illumina deveria ser uma nação altamente militarizada, certo? Tara me contou tudo sobre isso antes... Eu sempre quis ver com meus próprios olhos!",
  ui_story_5040_50400402_66_dialog_content = "Estou muito interessado em ver seus últimos modelos de caminhões.",
  ui_story_5040_50400402_67_dialog_content = "Então vamos em frente!",
  ui_story_5040_50400502_1_dialog_content = "Uau... Então esta é a cidade de Gannon!",
  ui_story_5040_50400502_2_dialog_content = "Eu só estive aqui uma vez.",
  ui_story_5040_50400502_3_dialog_content = "Nunca parece mudar muito, não é?",
  ui_story_5040_50400502_4_dialog_content = "Você vem a Illumina com frequência, PlayerName?",
  ui_story_5040_50400502_5_dialog_content = "Não, realmente não. É que um dos meus amigos mais próximos é daqui, então viemos aqui algumas vezes.",
  ui_story_5040_50400502_6_dialog_content = "Ela está de férias agora, no entanto. Acho que não teremos chance de vê-la hoje.",
  ui_story_5040_50400502_7_dialog_content = "A cidade de Gannon não celebra o Mooncrown Day ou algo assim? Não há uma única decoração para ser vista por aqui...",
  ui_story_5040_50400502_8_dialog_content = "Claro que sim, e é tão importante para eles também.",
  ui_story_5040_50400502_9_dialog_content = "Diferentes lugares têm suas próprias maneiras de observar os feriados. A Federação Illumina não dá tanta importância à pompa, só isso.",
  ui_story_5040_50400502_10_dialog_content = "As pessoas aqui tendem a ser mais pragmáticas e reservadas quando se trata de exibições públicas. Para este feriado em particular, a maioria das senhoras oferece rolos de canela feitos à mão para a pessoa de quem gostam.",
  ui_story_5040_50400502_11_dialog_content = "Os homens, por outro lado, pintam um pequeno coração na parte interna das mangas e escrevem nele o nome da pessoa que amam.",
  ui_story_5040_50400502_12_dialog_content = "Isso soa meio fofo, na verdade.",
  ui_story_5040_50400502_13_dialog_content = "E romântico! Eu também quero fazer!",
  ui_story_5040_50400502_14_dialog_content = "Ei...",
  ui_story_5040_50400502_15_dialog_content = "Você com certeza sabe muito sobre o mundo, Jeriah.",
  ui_story_5040_50400502_16_dialog_content = "Ouvi dizer que Jeriah já viajou para muitos lugares antes, mas ela raramente parece trazer isso à tona.",
  ui_story_5040_50400502_17_dialog_content = "Oh, isso é tudo história antiga. Agora então, se não me engano, aquela pessoa ali...",
  ui_story_5040_50400502_18_dialog_content = "?!?",
  ui_story_5040_50400502_19_dialog_content = "Deve ser o passarinho da Illumina.",
  ui_story_5040_50400502_20_dialog_content = "Pomba? Você não deveria estar entregando cartas agora?",
  ui_story_5040_50400502_21_dialog_content = "Sim, é o que estou fazendo. Eu não brincaria só porque é feriado.",
  ui_story_5040_50400502_22_dialog_content = "Só estou trabalhando no meu próprio ritmo, só isso.",
  ui_story_5040_50400502_23_dialog_content = "Você parece completamente inacreditável...",
  ui_story_5040_50400502_24_dialog_content = "Então você é a famosa Pomba, hein? Eu ouvi sobre você... embora eu não possa dizer que nada disso foi positivo.",
  ui_story_5040_50400502_25_dialog_content = "Como você pôde dizer isso? Eu trabalho muito! Não é minha culpa que haja bilhões de cartas para entregar durante esses feriados.",
  ui_story_5040_50400502_26_dialog_content = "É impossível entregar todos, isso realmente me irrita, coo!",
  ui_story_5040_50400502_27_dialog_content = "Então você decidiu relaxar completamente, então?",
  ui_story_5040_50400502_28_dialog_content = "Não importa isso por enquanto. Você sabe alguma coisa sobre o selo de penas Mooncrown Day?",
  ui_story_5040_50400502_29_dialog_content = "O selo de penas? Eu tenho isso em mim.",
  ui_story_5040_50400502_30_dialog_content = "Hã?!",
  ui_story_5040_50400502_31_dialog_content = "Todos os meus superiores estão tão ocupados fazendo entregas agora, que me deixaram encarregado de cuidar disso.",
  ui_story_5040_50400502_32_dialog_content = "Parece mais que eles não tiveram escolha a não ser trabalhar horas extras porque uma certa pessoa não está fazendo o seu próprio peso...",
  ui_story_5040_50400502_33_dialog_content = "Coo! O que isso deveria significar?!",
  ui_story_5040_50400502_34_dialog_content = "A-De qualquer forma, só queríamos obter um selo Feather Seal da Courier Union of Illumina. Somos um casal, sabe...",
  ui_story_5040_50400502_35_dialog_content = "Ah... Entendi.",
  ui_story_5040_50400502_36_dialog_content = "Isso é fácil, apenas cuide do resto das minhas entregas para mim.",
  ui_story_5040_50400502_37_dialog_content = "... Isso é permitido?!",
  ui_story_5040_50400502_38_dialog_content = "Bem, sou o único aqui, e por acaso também tenho o Selo de Penas... Então, basicamente, posso fazer o que quiser.",
  ui_story_5040_50400502_39_dialog_content = "Eu realmente sinto muito, mas seria ótimo se você estivesse disposto a me ajudar.",
  ui_story_5040_50400502_40_dialog_content = "Nós vamos fazer! Deixe isso conosco!",
  ui_story_5040_50400502_41_dialog_content = "<color=#e8d9bb>Quinze minutos depois—</color>",
  ui_story_5040_50400502_42_dialog_content = "...",
  ui_story_5040_50400502_43_dialog_content = "...",
  ui_story_5040_50400502_44_dialog_content = "...",
  ui_story_5040_50400502_45_dialog_content = "Isso é um monte de coisas para entregar.",
  ui_story_5040_50400502_46_dialog_content = "\"Apenas mais algumas parcelas\", meu pé! Como ela conseguiu colocar tudo isso aqui?!",
  ui_story_5040_50400502_47_dialog_content = "Nós dois não poderíamos entregar tudo isso, mesmo que trabalhássemos sem descanso por três dias seguidos...",
  ui_story_5040_50400502_48_dialog_content = "Desculpa... não pensei que seriam tantos.",
  ui_story_5040_50400502_49_dialog_content = "Acho que não temos escolha, pessoal. Vamos começar...",
  ui_story_5040_50400502_50_dialog_content = "Eu também ajudo e aproveito para trazer Sable pela cidade.",
  ui_story_5040_50400502_51_dialog_content = "Me desculpe... Parece que nós o arrastamos para nossos próprios problemas novamente.",
  ui_story_5040_50400502_52_dialog_content = "Cuidaremos da maior parte das entregas. Eu sou muito bom em trabalho físico.",
  ui_story_5040_50400502_53_dialog_content = "Estarei aqui relaxando com meu livro, torcendo por vocês terem ido embora.",
  ui_story_5040_50400502_54_dialog_content = "Jeriah... Suspiro, acho que provavelmente é para melhor. Não precisamos que as coisas fiquem piores do que já estão...",
  ui_story_5040_50400502_55_dialog_content = "Tudo bem! Vamos começar, pessoal!",
  ui_story_5040_50400502_56_dialog_content = "Ahhhh!",
  ui_story_5040_50400502_57_dialog_content = "Ei, apresse-se, Adônis!",
  ui_story_5040_50400502_58_dialog_content = "Eu... me desculpe! Essas escadas são tão íngremes...",
  ui_story_5040_50400502_59_dialog_content = "Seja um pouco mais cuidadoso, então!",
  ui_story_5040_50400502_60_dialog_content = "Aqui, vamos parar e resolver nossas entregas. Você pega os mais próximos e eu cuido dos mais distantes.",
  ui_story_5040_50400502_61_dialog_content = "De jeito nenhum, há muito para você lidar sozinho.",
  ui_story_5040_50400502_62_dialog_content = "Não se preocupe, estou acostumado a correr assim. Isso fará com que as entregas passem muito mais rápido, acredite.",
  ui_story_5040_50400502_63_dialog_content = "Ah... Tá bom.",
  ui_story_5040_50400502_64_dialog_content = "D-Entrega para você, Vivian!",
  ui_story_5040_50400502_65_dialog_content = "Oh meu, se não é PlayerName! Você não costuma ficar com V—",
  ui_story_5040_50400502_66_dialog_content = "Yeah, yeah. Aqui está o seu pacote, até logo!",
  ui_story_5040_50400502_67_dialog_content = "Mas por que você está entregando correspondência em primeiro lugar?",
  ui_story_5040_50400502_68_dialog_content = "... Dove, sua avaliação de desempenho vai ser um desastre.",
  ui_story_5040_50400502_69_dialog_content = "Olá! Por favor, assine esta carta e tenha um bom dia!",
  ui_story_5040_50400502_70_dialog_content = "Legal. Que cuida das entregas para este andar.",
  ui_story_5040_50400502_71_dialog_content = "Kya...está incrível...",
  ui_story_5040_50400502_72_dialog_content = "Na verdade! Afinal, sou um mensageiro!",
  ui_story_5040_50400502_73_dialog_content = "Apenas lembre-se de me dizer se vir algo que reavive sua memória, ok?",
  ui_story_5040_50400502_74_dialog_content = "<color=#e8d9bb>Algumas horas depois-</color>",
  ui_story_5040_50400502_75_dialog_content = "Eu... estou no meu limite...",
  ui_story_5040_50400502_76_dialog_content = "*Ofegante* PlayerName... Você terminou com suas entregas?",
  ui_story_5040_50400502_77_dialog_content = "Sim... Finalmente...",
  ui_story_5040_50400502_78_dialog_content = "Eu sei que tivemos que cobrir muito terreno, mas vocês realmente têm pouca resistência.",
  ui_story_5040_50400502_79_dialog_content = "Ótimo trabalho, pessoal! Parece que nosso trabalho aqui acabou.",
  ui_story_5040_50400502_80_dialog_content = "Kya ainda não voltou?",
  ui_story_5040_50400502_81_dialog_content = "Ah, não se preocupe com ela. Ela terminou suas entregas há um tempo atrás. Os birdies de Northland são os mais eficientes.",
  ui_story_5040_50400502_82_dialog_content = "Ela deve estar mostrando a sua amiguinha os pontos turísticos de Gannon City agora mesmo.",
  ui_story_5040_50400502_83_dialog_content = "Haha! Eu sabia que você tinha isso em você, PlayerName!",
  ui_story_5040_50400502_84_dialog_content = "D-Dove? Você esteve por aqui esse tempo todo?!",
  ui_story_5040_50400502_85_dialog_content = "\"Saindo\"? Estou trabalhando muito duro agora.",
  ui_story_5040_50400502_86_dialog_content = "Podemos ter um carimbo agora que terminamos o trabalho?",
  ui_story_5040_50400502_87_dialog_content = "Claro, venha. Eis o selo de penas!",
  ui_story_5040_50400502_88_dialog_content = "Aíi está!",
  ui_story_5040_50400502_89_dialog_content = "Hah... Agora temos o selo da Illumina também!",
  ui_story_5040_50400502_90_dialog_content = "Ainda não entendo o sentido de tudo isso...",
  ui_story_5040_50400502_91_dialog_content = "D-Não diga isso! Nossas pequenas aventuras têm nos aproximado, não acham?",
  ui_story_5040_50400502_92_dialog_content = "S-Diz quem?!",
  ui_story_5040_50400502_93_dialog_content = "Agora que temos o Selo de Penas de Illumina, para onde vamos a seguir?",
  ui_story_5040_50400502_94_dialog_content = "Não vamos a Gannon City todos os dias. Vamos experimentar um pouco da comida local e talvez assistir a um filme!",
  ui_story_5040_50400502_95_dialog_content = "Isso deve nos colocar no espírito natalino!",
  ui_story_5040_50400502_96_dialog_content = "Podemos comer a comida de Illumina sempre que quisermos.",
  ui_story_5040_50400502_97_dialog_content = "Enquanto entregava cartas, ouvi dizer que um carregamento de rifles de energia cinética acabou de chegar de uma Cidade Baixa. Quero ir vê-los descarregar essas armas.",
  ui_story_5040_50400502_98_dialog_content = "Você quer ir ver as armas no Mooncrown Day? Isso não é muito romântico...",
  ui_story_5040_50400502_99_dialog_content = "Se você não quiser ir, eu sempre posso ir sozinha.",
  ui_story_5040_50400502_100_dialog_content = "Eu...",
  ui_story_5040_50400502_101_dialog_content = "Acalmem-se vocês dois. Ainda há um assunto muito importante para resolver.",
  ui_story_5040_50400502_102_dialog_content = "Ou vocês dois esqueceram a razão pela qual viemos aqui em primeiro lugar?",
  ui_story_5040_50400502_103_dialog_content = "Oh sim! Ainda temos que perguntar àquela senhora nos Laboratórios Black Umbrella sobre a amnésia de Tara!",
  ui_story_5040_50400502_104_dialog_content = "O-Ah, certo...",
  ui_story_5040_50400502_105_dialog_content = "...",
  ui_story_5040_50400502_106_dialog_content = "Vamos fazer isso antes que escureça. Vamos.",
  ui_story_5040_50400601_1_dialog_content = "(Realmente já faz muito tempo.)",
  ui_story_5040_50400601_2_dialog_content = "... E é por isso que estamos aqui hoje. Desculpe por todos os problemas.",
  ui_story_5040_50400601_3_dialog_content = "Não é nenhum problema! Afinal, devo muito à Dona Tina, assim como a todos vocês!",
  ui_story_5040_50400601_4_dialog_content = "Lumopolis e Illumina sempre tiveram suas diferenças, o que tornou as coisas muito difíceis para nós dois.",
  ui_story_5040_50400601_5_dialog_content = "Mas fomos abençoados por ter a companhia de pessoas como a Dona Tina que nos apoiam!",
  ui_story_5040_50400601_6_dialog_content = "Apesar de ser um membro da classe nobre, ela sempre apoiou nosso amor.",
  ui_story_5040_50400601_7_dialog_content = "Pelo que entendi, seu corpo requer muito sono para funcionar corretamente. Apesar de sua condição, ela ainda se esforçou para encontrar aquele selo para nós.",
  ui_story_5040_50400601_8_dialog_content = "Sim, não há como negar que ela é uma pessoa incrível.",
  ui_story_5040_50400601_9_dialog_content = "Ela é sempre tão gentil e educada.",
  ui_story_5040_50400601_10_dialog_content = "Mas eu sei que ela tem problemas suficientes para lidar. Ouvi dizer que o trabalho dela no Tribunal de Justiça é... interessante, para dizer o mínimo.",
  ui_story_5040_50400601_11_dialog_content = "Não tenho ideia de quando teremos a chance de nos ver novamente. Eu gostaria de saber mais sobre ela.",
  ui_story_5040_50400601_12_dialog_content = "Mas, de acordo com ela, parece que você e sua amada já estão muito difíceis.",
  ui_story_5040_50400601_13_dialog_content = "Sim. Por que vocês dois não fugiram?",
  ui_story_5040_50400601_14_dialog_content = "Porque nós dois temos coisas que precisamos fazer. Podemos ser amantes, mas nossas próprias responsabilidades sempre virão em primeiro lugar.",
  ui_story_5040_50400601_15_dialog_content = "Ele e eu temos um forte senso de dever, e é provavelmente por isso que nos sentimos atraídos um pelo outro em primeiro lugar.",
  ui_story_5040_50400601_16_dialog_content = "Se duas pessoas são completamente sinceras consigo mesmas e uma com a outra, coisas como a distância tornam-se triviais. Afinal, nossos corações estão sempre juntos.",
  ui_story_5040_50400601_17_dialog_content = "Seus corações... estão sempre juntos?",
  ui_story_5040_50400601_18_dialog_content = "Eu me sinto assim também. Nenhum problema é muito difícil de superar, desde que vocês se amem!",
  ui_story_5040_50400601_19_dialog_content = "Hahaha! Agora então, devemos realmente voltar aos negócios. Seu nome é Tara, certo? Acho que entendo seu dilema, mais ou menos.",
  ui_story_5040_50400601_20_dialog_content = "Infelizmente, sou apenas um estagiário no momento, mas deixe-me perguntar aos meus colegas e ver o que eles acham. Um momento por favor.",
  ui_story_5040_50400601_21_dialog_content = "Obrigado novamente!",
  ui_story_5040_50400601_22_dialog_content = "<size=33>Jeriah... Você não acha que eles vão descobrir que estou apenas fingindo, não é?</size>",
  ui_story_5040_50400601_23_dialog_content = "Não seria melhor confessar neste momento?",
  ui_story_5040_50400601_24_dialog_content = "<size=33>Sem chance! Eu nunca poderia mostrar meu rosto para os outros se eu o fizesse!</size>",
  ui_story_5040_50400601_25_dialog_content = "Você não pensou nisso quando teve essa ideia maluca?",
  ui_story_5040_50400601_26_dialog_content = "<size=33>De qualquer forma, se o segredo for revelado, vou precisar muito que você me ajude a apagar o incêndio.</size>",
  ui_story_5040_50400601_27_dialog_content = "...",
  ui_story_5040_50400601_28_dialog_content = "(Eu sabia que ela estava apenas fingindo o tempo todo... Acho que vou fingir que não sei de nada.)",
  ui_story_5040_50400601_29_dialog_content = "Do que vocês dois estão falando?",
  ui_story_5040_50400601_30_dialog_content = "Nada! Estávamos apenas dizendo como esse laboratório é incrível!",
  ui_story_5040_50400601_31_dialog_content = "Bem, sim... Migard está no comando deste lugar, e ela está em um nível totalmente diferente.",
  ui_story_5040_50400601_32_dialog_content = "Tara? Por que você está tremendo?",
  ui_story_5040_50400601_33_dialog_content = "Oh, ela só está com um pouco de frio!",
  ui_story_5040_50400601_34_dialog_content = "Realmente? Não sinto muito frio aqui...",
  ui_story_5040_50400601_35_dialog_content = "Desculpe fazê-lo esperar! Se todos me seguirem, gostaria de apresentar a vocês um dos pesquisadores seniores aqui.",
  ui_story_5040_50400601_36_dialog_content = "Mostre o caminho!",
  ui_story_5040_50400601_37_dialog_content = "Jola? Esta é Tara, a jovem que mencionei antes. Parece que ela está sofrendo de um caso de amnésia.",
  ui_story_5040_50400601_38_dialog_content = "Agradecemos qualquer ajuda que você pode nos dar!",
  ui_story_5040_50400601_39_dialog_content = "Estou mais do que feliz em dar uma mão! É o mínimo que posso fazer, depois de tudo que você fez pelo meu colega aqui.",
  ui_story_5040_50400601_40_dialog_content = "Agora então, Srta. Tara... Você se importaria se eu a examinasse de perto?",
  ui_story_5040_50400601_41_dialog_content = "G-Vá em frente...",
  ui_story_5040_50400601_42_dialog_content = "Que pena que Migard não está aqui hoje. Não sou um especialista nesses assuntos, mas ainda assim farei o meu melhor.",
  ui_story_5040_50400601_43_dialog_content = "(Obrigado Senhor!)",
  ui_story_5040_50400601_44_dialog_content = "Hmm... À primeira vista, nada parece fora do comum. Teremos que fazer uma série de testes para verificar a condição do seu corpo.",
  ui_story_5040_50400601_45_dialog_content = "Que tipo de testes...?",
  ui_story_5040_50400601_46_dialog_content = "(Seu sorriso parece ameaçador...)",
  ui_story_5040_50400601_47_dialog_content = "Não se preocupe! Uma pequena pitada aqui, um pequeno puxão ali, e tudo acabará antes que você perceba!",
  ui_story_5040_50400601_48_dialog_content = "Graaah!",
  ui_story_5040_50400601_49_dialog_content = "Essa não...",
  ui_story_5040_50400602_1_dialog_content = "Ei! Você não disse nada sobre o uso de Eclipsites para executar seus testes!",
  ui_story_5040_50400602_2_dialog_content = "Um pequeno aviso teria sido bom, sabe!!",
  ui_story_5040_50400602_3_dialog_content = "Minhas desculpas, todos. Sinceramente, não esperava que você se opusesse tanto aos meus métodos!",
  ui_story_5040_50400602_4_dialog_content = "Afinal, vocês são um grupo bastante peculiar. Um nortista, um morador do deserto, um mensageiro semi-humano... e, claro, o último celestita do mundo.",
  ui_story_5040_50400602_5_dialog_content = "Isso não é nada relevante. Estamos aqui apenas para ajudar Tara a melhorar!",
  ui_story_5040_50400602_6_dialog_content = "Então, o que exatamente há de errado comigo?",
  ui_story_5040_50400602_7_dialog_content = "Bem, pelo que vi, você parece estar em perfeita saúde física.",
  ui_story_5040_50400602_8_dialog_content = "... É isso? Então, o que mais podemos fazer?",
  ui_story_5040_50400602_9_dialog_content = "O que mais você pode me dizer sobre a doença dela? Você sabe o que pode ter causado isso?",
  ui_story_5040_50400602_10_dialog_content = "Deixe-me ver... Tudo começou com aquela poção mágica. A vidente que me vendeu disse que era feito com um ingrediente muito especial.",
  ui_story_5040_50400602_11_dialog_content = "Algo sobre um gigantesco verme da areia rosa no Deserto de Rediesel... Acho que deveria ser uma criatura extremamente rara?",
  ui_story_5040_50400602_12_dialog_content = "Você disse... um verme da areia rosa?",
  ui_story_5040_50400602_13_dialog_content = "S-Sim?",
  ui_story_5040_50400602_14_dialog_content = "Jola, o que você sabe sobre isso?",
  ui_story_5040_50400602_15_dialog_content = "...",
  ui_story_5040_50400602_16_dialog_content = "Não acredito que o lendário verme da areia rosa voltou a aparecer...",
  ui_story_5040_50400602_17_dialog_content = "<size=33>O que?! Isso é impossível!</size>",
  ui_story_5040_50400602_18_dialog_content = "<size=33>Tara?</size>",
  ui_story_5040_50400602_19_dialog_content = "<size=33>Eu coloquei minhas mãos na escama do verme da areia rosa há muito tempo! Como algum médium conseguiu um também?!</size>",
  ui_story_5040_50400602_20_dialog_content = "<size=33>Se esse verme da areia rosa realmente existe, é realmente tão surpreendente saber que outra pessoa tem uma de suas escamas?</size>",
  ui_story_5040_50400602_21_dialog_content = "<size=33>É porque, até onde eu sei, apenas uma escama de verme da areia rosa já esteve disponível em todo o mercado! Então, como poderia de repente haver outro?</size>",
  ui_story_5040_50400602_22_dialog_content = "Minha especialidade reside no campo da botânica. Certo dia, enquanto eu procurava um esporo em particular, Migard mencionou o verme da areia rosa para mim.",
  ui_story_5040_50400602_23_dialog_content = "Este esporo não foi pesquisado ao longo dos anos e é mencionado apenas em livros. A razão para isso é porque ele só cresce nas escamas do extremamente raro verme da areia rosa.",
  ui_story_5040_50400602_24_dialog_content = "Migard mencionou que havia relatos de testemunhas oculares desta criatura, mas muito poucos foram capazes de provar suas afirmações.",
  ui_story_5040_50400602_25_dialog_content = "É mais agressivo do que o verme da areia comum, tornando difícil para qualquer um se aproximar dele. Suas escamas são um ingrediente extremamente raro e precioso. Na verdade, acho que existe apenas uma única balança disponível em todo o mercado.",
  ui_story_5040_50400602_26_dialog_content = "Se você me trouxesse uma dessas escamas, talvez eu pudesse tentar criar uma cura.",
  ui_story_5040_50400602_27_dialog_content = "Além disso, receio não ter outras soluções para lhe oferecer.",
  ui_story_5040_50400602_28_dialog_content = "...",
  ui_story_5040_50400602_29_dialog_content = "...",
  ui_story_5040_50400602_30_dialog_content = "Então parece que nosso objetivo ficou muito claro para nós.",
  ui_story_5040_50400602_31_dialog_content = "Jerias?",
  ui_story_5040_50400602_32_dialog_content = "Considerando que nosso próximo destino é a Rediesel Wrench, e sou o chefe da Courier Union lá...",
  ui_story_5040_50400602_33_dialog_content = "Ei, você está falando sério?",
  ui_story_5040_50400602_34_dialog_content = "Parece que apenas algumas pessoas já colocaram os olhos nesta coisa... Eu nunca ouvi falar disso, apesar de viver no deserto a minha vida inteira. Você já?",
  ui_story_5040_50400602_35_dialog_content = "Também nunca ouvi falar.",
  ui_story_5040_50400602_36_dialog_content = "Então por que diabos você está fazendo deste nosso teste?!",
  ui_story_5040_50400602_37_dialog_content = "Eu vou fazer isso! Se houver a menor chance de restaurar as memórias de Tara, estou disposto a tentar.",
  ui_story_5040_50400602_38_dialog_content = "Hã?",
  ui_story_5040_50400602_39_dialog_content = "Adônis! Você perdeu a cabeça?!",
  ui_story_5040_50400602_40_dialog_content = "Para ser sincero, não me sinto nem um pouco confiante... porque sei que sou fraco e tímido — não consigo nem matar os insetos da minha própria casa, muito menos um verme da areia gigante...",
  ui_story_5040_50400602_41_dialog_content = "Mas Tara acabou assim por minha causa, então tenho que fazer algo a respeito.",
  ui_story_5040_50400602_42_dialog_content = "Eu sei que minha natureza tímida é o que a frustrou tanto em primeiro lugar... É por isso que eu quero mudar.",
  ui_story_5040_50400602_43_dialog_content = "Eu não posso recuar, não importa o quê.",
  ui_story_5040_50400602_44_dialog_content = "Foi um discurso realmente comovente!",
  ui_story_5040_50400602_45_dialog_content = "Adônis! Eu... Na verdade, eu...",
  ui_story_5040_50400602_46_dialog_content = "Muito comovente o discurso, Adonis. Então você acha que pode derrotar esse verme da areia sozinho agora?",
  ui_story_5040_50400602_47_dialog_content = "Claro que não! Vou precisar de toda a ajuda que conseguir, então, por favor, me ensine a lutar!",
  ui_story_5040_50400602_48_dialog_content = "Comece-me com Eclipsites se for preciso! Farei qualquer coisa para ficar mais forte!",
  ui_story_5040_50400602_49_dialog_content = "Você ao menos sabe lutar?",
  ui_story_5040_50400602_50_dialog_content = "Parece que me lembro de seu pai dizendo que você estudou Luminatics com Novio... É isso mesmo?",
  ui_story_5040_50400602_51_dialog_content = "Sim! Quando menino, eu ia muito à biblioteca, e o Sr. Novio me ensinava muito.",
  ui_story_5040_50400602_52_dialog_content = "Meus Luminatics podem não ser muito fortes, mas tenho uma compreensão bastante sólida de como usá-los.",
  ui_story_5040_50400602_53_dialog_content = "Heheheh... Que bom!",
  ui_story_5040_50400602_54_dialog_content = "Jeriah, sua expressão está me assustando.",
  ui_story_5040_50400602_55_dialog_content = "Relaxa, estamos todos no mesmo time! Não é como se eu fosse torturá-lo ou algo assim.",
  ui_story_5040_50400602_56_dialog_content = "Isso será fácil. Como você mesmo disse, podemos começar com Eclipsites...",
  ui_story_5040_50400602_57_dialog_content = "E-espere... Você vai mesmo me fazer lutar contra uma dessas coisas?",
  ui_story_5040_50400602_58_dialog_content = "Oh céus, não! Isso seria muito cruel! Não... Tenho uma ideia ainda melhor.",
  ui_story_5040_50400602_59_dialog_content = "Ela é uma oponente muito mais adequada para você.",
  ui_story_5040_50400701_1_dialog_content = "Do que você me chamou aqui, Lady Jeriah?",
  ui_story_5040_50400701_2_dialog_content = "Jeriah, você não quer dizer...",
  ui_story_5040_50400701_3_dialog_content = "Graa...?",
  ui_story_5040_50400701_4_dialog_content = "Hehe, sim! O amiguinho da Kya é a combinação perfeita para ele, não acham? Tudo nela praticamente grita \"Eclipsite\".",
  ui_story_5040_50400701_5_dialog_content = "Eu acho que ela seria uma parceira de treino maravilhosa para Adonis!",
  ui_story_5040_50400701_6_dialog_content = "Quer dizer, eu sei que Sable não se parece muito com os outros aurorianos... mas você não acha que chamá-la de Eclipsite é ir longe demais?",
  ui_story_5040_50400701_7_dialog_content = "(Ainda assim, ela definitivamente está conectada aos Eclipsites de alguma forma.)",
  ui_story_5040_50400701_8_dialog_content = "(Mas ela está com Kya e não causou nenhum problema até agora. Teremos que esperar para ver, eu acho.)",
  ui_story_5040_50400701_9_dialog_content = "Sparring... parceiro...?",
  ui_story_5040_50400701_10_dialog_content = "Ela não sabe lutar! E se ela se machucar?",
  ui_story_5040_50400701_11_dialog_content = "Relaxe, eles não vão brigar de verdade. Isso é apenas para ajudar Adonis a encontrar sua coragem, só isso.",
  ui_story_5040_50400701_12_dialog_content = "Adônis, o que você acha?",
  ui_story_5040_50400701_13_dialog_content = "I-Parece um pouco rude... mas se Sable estiver disposto a ajudar, eu ficaria muito grato.",
  ui_story_5040_50400701_14_dialog_content = "Se eu fosse enfrentar um Eclipsite agora, estaria praticamente me servindo em uma bandeja de prata.",
  ui_story_5040_50400701_15_dialog_content = "Também não sou bom com Luminatics, pois raramente os uso. Normalmente, eu apenas confio em Tara para me proteger.",
  ui_story_5040_50400701_16_dialog_content = "Você não precisa fazer isso, Adônis. Todo mundo tem pontos fortes e fracos diferentes.",
  ui_story_5040_50400701_17_dialog_content = "E nem penso em precisar protegê-lo como um fardo.",
  ui_story_5040_50400701_18_dialog_content = "Tara?",
  ui_story_5040_50400701_19_dialog_content = "Não... não importa o que aconteça, eu tenho que fazer isso! Tenho que me esforçar para sair da minha zona de conforto.",
  ui_story_5040_50400701_20_dialog_content = "Kya, Sable, por favor me ajudem!",
  ui_story_5040_50400701_21_dialog_content = "Hm... Sable, você está bem com isso?",
  ui_story_5040_50400701_22_dialog_content = "Se isso significar... eu posso ajudar...",
  ui_story_5040_50400701_23_dialog_content = "Então... eu faço!",
  ui_story_5040_50400701_24_dialog_content = "Não se pressione, ok? É apenas uma luta fingida, nada mais.",
  ui_story_5040_50400701_25_dialog_content = "eu não vou...",
  ui_story_5040_50400701_26_dialog_content = "Estou... feliz em ajudar...",
  ui_story_5040_50400701_27_dialog_content = "Você é o melhor, Sable!",
  ui_story_5040_50400701_28_dialog_content = "Grrr! Grrrrr!",
  ui_story_5040_50400701_29_dialog_content = "Sou só eu, ou ouvi um Eclipsite real...?",
  ui_story_5040_50400701_30_dialog_content = "Hã?!",
  ui_story_5040_50400701_31_dialog_content = "<size=45>Graaahh-!</size>",
  ui_story_5040_50400701_32_dialog_content = "Atenção! Há Eclipsites aqui!",
  ui_story_5040_50400701_33_dialog_content = "M-Mas como?! De onde eles vieram?!",
  ui_story_5040_50400701_34_dialog_content = "Onde, de fato? Você e seu passarinho preto sempre parecem atrair uma multidão onde quer que vá...",
  ui_story_5040_50400701_35_dialog_content = "Poderia realmente ser apenas uma coincidência?",
  ui_story_5040_50400701_36_dialog_content = "Hmm...",
  ui_story_5040_50400701_37_dialog_content = "(Sable realmente desenhou esses monstros aqui...?)",
  ui_story_5040_50400701_38_dialog_content = "Eclips... locais...?",
  ui_story_5040_50400701_39_dialog_content = "Foco. Vamos nos livrar dessas pragas em primeiro lugar.",
  ui_story_5040_50400701_40_dialog_content = "Fique atrás de mim, Adônis!",
  ui_story_5040_50400701_41_dialog_content = "Eu sei.",
  ui_story_5040_50400702_1_dialog_content = "Parece que temos todos eles. Estão todos bem?",
  ui_story_5040_50400702_2_dialog_content = "Claro. Afinal, eram apenas alguns eclipsitos.",
  ui_story_5040_50400702_3_dialog_content = "Eu também estou bem.",
  ui_story_5040_50400702_4_dialog_content = "Isso é ótimo para vocês, meninas, mas parece uma história diferente para aquelas duas ali.",
  ui_story_5040_50400702_5_dialog_content = "Ah!",
  ui_story_5040_50400702_6_dialog_content = "S...Tão assustador...",
  ui_story_5040_50400702_7_dialog_content = "(Eu me pergunto o quão produtivo é ter esses dois treinando um ao outro...)",
  ui_story_5040_50400702_8_dialog_content = "Devemos continuar com nosso treinamento, ou vocês dois precisam de uma pausa?",
  ui_story_5040_50400702_9_dialog_content = "Eu posso continuar!",
  ui_story_5040_50400702_10_dialog_content = "M... Eu também...!",
  ui_story_5040_50400702_11_dialog_content = "Não se force, Sable.",
  ui_story_5040_50400702_12_dialog_content = "Já que vocês dois estão se sentindo corajosos, vamos continuar.",
  ui_story_5040_50400702_13_dialog_content = "<color=#e8d9bb>15 minutos mais tarde-</color>",
  ui_story_5040_50400702_14_dialog_content = "...",
  ui_story_5040_50400702_15_dialog_content = "...",
  ui_story_5040_50400702_16_dialog_content = "Uh... vocês vão começar logo? Você está parado há algum tempo...",
  ui_story_5040_50400702_17_dialog_content = "Eu vou atacar agora!",
  ui_story_5040_50400702_18_dialog_content = "...!!",
  ui_story_5040_50400702_19_dialog_content = "Você não parece estar prestes a entrar em batalha.",
  ui_story_5040_50400702_20_dialog_content = "Eu realmente vou fazer isso! É melhor você estar pronto!",
  ui_story_5040_50400702_21_dialog_content = "O-ok...!",
  ui_story_5040_50400702_22_dialog_content = "<color=#e8d9bb>Uma hora depois...</color>",
  ui_story_5040_50400702_23_dialog_content = "Dessa vez, juro que vou atacar!",
  ui_story_5040_50400702_24_dialog_content = "Apenas observe!",
  ui_story_5040_50400702_25_dialog_content = "(Estou com tanto sono que sinto que poderia tirar uma soneca agora.)",
  ui_story_5040_50400702_26_dialog_content = "Como eu disse, Adonis, você realmente não precisa fazer isso.",
  ui_story_5040_50400702_27_dialog_content = "Vai Sable!!!",
  ui_story_5040_50400702_28_dialog_content = "...",
  ui_story_5040_50400702_29_dialog_content = "Você honestamente acha que um Eclipsite vai ficar parado por uma hora e esperar que você ataque?",
  ui_story_5040_50400702_30_dialog_content = "Lembre-se, você está fazendo isso pelo bem de Tara.",
  ui_story_5040_50400702_31_dialog_content = "Se ela caísse em batalha e um Eclipsite a tivesse em vista, você hesitaria assim?",
  ui_story_5040_50400702_32_dialog_content = "Você não precisa que eu lhe diga qual seria o resultado disso.",
  ui_story_5040_50400702_33_dialog_content = "Eu... Eu...",
  ui_story_5040_50400702_34_dialog_content = "Ou você está me dizendo que não se importa se ela se machucar, já que você não está disposto a superar sua hesitação covarde?",
  ui_story_5040_50400702_35_dialog_content = "Th-Isso não é verdade!",
  ui_story_5040_50400702_36_dialog_content = "Mesmo um momento de hesitação pode significar a diferença entre a vida e a morte. Quem gostaria de estar com alguém tão pouco confiável?",
  ui_story_5040_50400702_37_dialog_content = "<size=33>Ei! Você está sendo muito duro com ele!</size>",
  ui_story_5040_50400702_38_dialog_content = "<size=33>Eu me sinto muito mal por ele... Sable, por que você não o ajuda?</size>",
  ui_story_5040_50400702_39_dialog_content = "<size=45>Grah! Graaaaah!</size>",
  ui_story_5040_50400702_40_dialog_content = "<size=55>Aaaahhhh!!!</size>",
  ui_story_5040_50400702_41_dialog_content = "<color=#e8d9bb>Bonk...!</color>",
  ui_story_5040_50400702_42_dialog_content = "Haaah... Haaah...",
  ui_story_5040_50400702_43_dialog_content = "Ai...",
  ui_story_5040_50400702_44_dialog_content = "S-Sable! Você está bem?!",
  ui_story_5040_50400702_45_dialog_content = "Eu estou... estou bem...",
  ui_story_5040_50400702_46_dialog_content = "Ele realmente a atacou?",
  ui_story_5040_50400702_47_dialog_content = "Você está progredindo, Adônis! Pelo menos você não se escondeu atrás desta vez!",
  ui_story_5040_50400702_48_dialog_content = "Certamente foi o ataque menos prejudicial que já vi na minha vida, mas o celestita está certo.",
  ui_story_5040_50400702_49_dialog_content = "Ainda assim, você não conseguirá acertar um Eclipsite real tão cedo.",
  ui_story_5040_50400702_50_dialog_content = "O mais importante é que ele está progredindo! Superar a si mesmo é sempre o passo mais difícil!",
  ui_story_5040_50400702_51_dialog_content = "Tara... Obrigado!",
  ui_story_5040_50400702_52_dialog_content = "*Sniff* Muito obrigado a todos! Especialmente você, Sable!",
  ui_story_5040_50400702_53_dialog_content = "Está bem...",
  ui_story_5040_50400702_54_dialog_content = "Bom. Agora que resolvemos isso, o verdadeiro treinamento pode começar.",
  ui_story_5040_50400702_55_dialog_content = "Acho que chega por hoje, Jeriah. Está ficando muito tarde, e tenho certeza que todos estão cansados.",
  ui_story_5040_50400702_56_dialog_content = "Podemos dar um passo de cada vez. Vamos voltar para a cidade por enquanto.",
  ui_story_5040_50400702_57_dialog_content = "Se você diz, pequena celestita.",
  ui_story_5040_50400702_58_dialog_content = "Ugh...",
  ui_story_5040_50400702_59_dialog_content = "Huh? O que é, Sable? Você está machucado?",
  ui_story_5040_50400702_60_dialog_content = "N... Não...",
  ui_story_5040_50400702_61_dialog_content = "Eu lembro...",
  ui_story_5040_50400702_62_dialog_content = "Hã?!",
  ui_story_5040_50400702_63_dialog_content = "Deserto... deserto...",
  ui_story_5040_50400702_64_dialog_content = "Como no Deserto de Rediesel?",
  ui_story_5040_50400702_65_dialog_content = "Não sei... Mas...",
  ui_story_5040_50400702_66_dialog_content = "Só me lembro... do deserto...",
  ui_story_5040_50400702_67_dialog_content = "Acho que Adonis batendo na sua cabeça despertou sua memória?",
  ui_story_5040_50400702_68_dialog_content = "Bem, o Rediesel Desert é convenientemente nossa próxima parada.",
  ui_story_5040_50400702_69_dialog_content = "...",
  ui_story_5040_50400702_70_dialog_content = "Vocês todos parecem bem exaustos, então vamos encerrar o dia e descansar um pouco.",
  ui_story_5040_50400702_71_dialog_content = "Tudo por minha causa. Não sei como agradecer a todos.",
  ui_story_5040_50400702_72_dialog_content = "Este era o nosso problema para começar, mas você tem nos apoiado todo esse tempo... Obrigado.",
  ui_story_5040_50400702_73_dialog_content = "Por que não vamos comprar alguns petiscos especiais dos Illuminanos para que todos mostrem nosso apreço, Tara? Não há muito mais que possamos fazer.",
  ui_story_5040_50400702_74_dialog_content = "Haha, vocês realmente não precisam fazer isso!",
  ui_story_5040_50400702_75_dialog_content = "(Não tenho certeza se as especialidades do Illumina são adequadas como lanches...)",
  ui_story_5040_50400702_76_dialog_content = "Essa é uma ótima ideia. Vamos indo antes que seja tarde demais.",
  ui_story_5040_50400702_77_dialog_content = "Eu quero ir...",
  ui_story_5040_50400702_78_dialog_content = "Kya, gostaria de falar com você em particular. Você tem um momento?",
  ui_story_5040_50400702_79_dialog_content = "Huh? Por que de repente... sim, Lady Jeriah.",
  ui_story_5040_50400702_80_dialog_content = "Mas e o Sable...?",
  ui_story_5040_50400702_81_dialog_content = "Não se preocupe com ela. Ela pode voltar com PlayerName.",
  ui_story_5040_50400702_82_dialog_content = "A menos que haja algo sobre ela que devamos saber...?",
  ui_story_5040_50400702_83_dialog_content = "N...De jeito nenhum!",
  ui_story_5040_50400702_84_dialog_content = "Você se importaria de levá-la de volta, PlayerName?",
  ui_story_5040_50400702_85_dialog_content = "Claro que não! Vamos, Sable.",
  ui_story_5040_50400702_86_dialog_content = "Hã...",
  ui_story_5040_50400702_87_dialog_content = "O que houve?",
  ui_story_5040_50400702_88_dialog_content = "Eu... preciso ir a algum lugar...",
  ui_story_5040_50400702_89_dialog_content = "\"Ir a algum lugar\"?",
  ui_story_5040_50400702_90_dialog_content = "Ainda há algum lugar que você queira ir?",
  ui_story_5040_50400702_91_dialog_content = "Mais cedo... eu peguei... uma carta...",
  ui_story_5040_50400702_92_dialog_content = "Eu quero... devolver...",
  ui_story_5040_50400702_93_dialog_content = "Quando você encontrou uma carta? Não devíamos deixá-lo no Courier Union?",
  ui_story_5040_50400702_94_dialog_content = "Foi... depois... do nosso treinamento...",
  ui_story_5040_50400702_95_dialog_content = "Oh, então em algum lugar fora da cidade? Um mensageiro deve tê-lo deixado cair por acidente.",
  ui_story_5040_50400702_96_dialog_content = "Podemos levá-lo ao Courier Union, ok?",
  ui_story_5040_50400702_97_dialog_content = "Tem... um endereço.",
  ui_story_5040_50400702_98_dialog_content = "Eles devem estar... esperando... muito tempo...",
  ui_story_5040_50400702_99_dialog_content = "Verdadeiro. Afinal, é o Dia da Coroa da Lua. Você quer que chegue ao destinatário mais rápido, não é?",
  ui_story_5040_50400702_100_dialog_content = "Se ao menos Dove tivesse metade da responsabilidade que você...",
  ui_story_5040_50400702_101_dialog_content = "Aqui, deixe-me dar uma olhada no endereço. Vou ajudá-lo a entregá-lo.",
  ui_story_5040_50400702_102_dialog_content = "(Este envelope parece bem antigo... Algo me diz que não foi enviado recentemente.)",
  ui_story_5040_50400702_103_dialog_content = "<color=#e8d9bb>Toc toc toc..</color>",
  ui_story_5040_50400702_104_dialog_content = "Deveria ser aqui.",
  ui_story_5040_50400702_105_dialog_content = "Sim, o endereço está certo.",
  ui_story_5040_50400702_106_dialog_content = "Olá? Posso te ajudar?",
  ui_story_5040_50400702_107_dialog_content = "Desculpe incomodá-lo, mas encontramos esta carta no chão mais cedo. Está endereçado a esta casa.",
  ui_story_5040_50400702_108_dialog_content = "É assim mesmo? Posso dar uma olhada?",
  ui_story_5040_50400702_109_dialog_content = "...I-Isto não pode ser...!",
  ui_story_5040_50400702_110_dialog_content = "Este é o endereço correto, certo?",
  ui_story_5040_50400702_111_dialog_content = "Onde exatamente vocês dois encontraram esta carta?!",
  ui_story_5040_50400702_112_dialog_content = "Meu amigo aqui o encontrou fora da cidade. Ela insistiu em entregá-lo a você.",
  ui_story_5040_50400702_113_dialog_content = "Eu fui... útil...?",
  ui_story_5040_50400702_114_dialog_content = "Eu não sei o que dizer...",
  ui_story_5040_50400702_115_dialog_content = "Esta é uma carta para minha avó.",
  ui_story_5040_50400702_116_dialog_content = "Sua avó?",
  ui_story_5040_50400702_117_dialog_content = "Ela esperou por esta carta por muito tempo, até o momento em que ela passou.",
  ui_story_5040_50400702_118_dialog_content = "É do primeiro amor dela. Pelo que ela me contou, ele morava em Lumópolis. Mas por causa da distância entre lá e Illumina, eles nunca acabaram juntos.",
  ui_story_5040_50400702_119_dialog_content = "Meu avô faleceu há muito tempo, então minha avó se reconectou com seu primeiro amor.",
  ui_story_5040_50400702_120_dialog_content = "Eles se tornaram amigos íntimos e sempre trocavam cartas. Eles prometeram que continuariam enviando-os até o fim.",
  ui_story_5040_50400702_121_dialog_content = "Mas um dia suas cartas pararam de chegar e, pouco tempo depois, minha avó adoeceu e faleceu.",
  ui_story_5040_50400702_122_dialog_content = "Nunca pensei que ele...",
  ui_story_5040_50400702_123_dialog_content = "Suspiro, o destino realmente faz os mortais de tolos.",
  ui_story_5040_50400702_124_dialog_content = "E pensar que havia tal história por trás desta carta...",
  ui_story_5040_50400702_125_dialog_content = "Sable, você realmente fez algo incrível!",
  ui_story_5040_50400702_126_dialog_content = "Estou muito grato! Não vou abrir esta carta. Era para a minha avó, por isso vou deixá-lo junto à campa dela para que possa acompanhá-la.",
  ui_story_5040_50400702_127_dialog_content = "...",
  ui_story_5040_50400702_128_dialog_content = "Isso deve ser um milagre do Mooncrown Day... Só espero que as palavras dele ainda consigam alcançá-la.",
  ui_story_5040_50400702_129_dialog_content = "Isso é amor?",
  ui_story_5040_50400702_130_dialog_content = "Esta é uma boa pergunta. Às vezes nem eu mesmo me entendo. Como o amor é tão poderoso?",
  ui_story_5040_50400702_131_dialog_content = "Às vezes machuca as pessoas, às vezes salva as pessoas.",
  ui_story_5040_50400702_132_dialog_content = "De qualquer forma, como eu poderia retribuir a vocês dois por essa gentileza?",
  ui_story_5040_50400702_133_dialog_content = "Você não tem que me agradecer de jeito nenhum. Agradeça a Sable aqui.",
  ui_story_5040_50400702_134_dialog_content = "Tudo bem...",
  ui_story_5040_50400702_135_dialog_content = "Parece que terminamos aqui. Pronto para voltar agora?",
  ui_story_5040_50400702_136_dialog_content = "Sim...",
  ui_story_5040_50400702_137_dialog_content = "<color=#e8d9bb>Enquanto isso, do outro lado da cidade...</color>",
  ui_story_5040_50400702_138_dialog_content = "O que você precisa discutir comigo, Lady Jeriah?",
  ui_story_5040_50400702_139_dialog_content = "...",
  ui_story_5040_50400702_140_dialog_content = "Northland birdie, entretenha minha curiosidade por um momento. Onde você conseguiu esse seu parente?",
  ui_story_5040_50400702_141_dialog_content = "!!",
  ui_story_5040_50400702_142_dialog_content = "V-Você quer dizer... S-Sable?",
  ui_story_5040_50400702_143_dialog_content = "De quem mais eu estaria falando?",
  ui_story_5040_50400702_144_dialog_content = "Hã...",
  ui_story_5040_50400702_145_dialog_content = "(A atmosfera parece tão sufocante!)",
  ui_story_5040_50400702_146_dialog_content = "Eu nunca fui de rodeios, então vou perguntar diretamente a você.",
  ui_story_5040_50400702_147_dialog_content = "Ela não é auroriana, é?",
  ui_story_5040_50400702_148_dialog_content = "...!",
  ui_story_5040_50400702_149_dialog_content = "Deixe-me ser ainda mais direto: ela parece ser uma eclipsita capaz de falar o universose.",
  ui_story_5040_50400702_150_dialog_content = "Senhora Jeriah...",
  ui_story_5040_50400702_151_dialog_content = "Heehee! Mesmo que você não seja mensageiro há muito tempo, devo dizer que estou bastante surpreso com sua bravura, pequenino.",
  ui_story_5040_50400702_152_dialog_content = "Parece que subestimei você.",
  ui_story_5040_50400702_153_dialog_content = "Eu sei que é completamente fora de linha da minha parte perguntar, mas... você poderia, por favor, manter isso em segredo?",
  ui_story_5040_50400702_154_dialog_content = "E por que eu deveria fazer isso? Que razão tenho para ajudá-lo a manter sua pequena fachada?",
  ui_story_5040_50400702_155_dialog_content = "Nenhum, não há razão para você me ajudar. Também não tenho o direito de pedir esse favor.",
  ui_story_5040_50400702_156_dialog_content = "Eu estou te implorando, é tudo.",
  ui_story_5040_50400702_157_dialog_content = "...",
  ui_story_5040_50400702_158_dialog_content = "Ela perdeu a memória e me pediu para ajudá-la.",
  ui_story_5040_50400702_159_dialog_content = "Ajudá-la não me serve de nada. Se alguma coisa, isso coloca todos nós em perigo. Aurorianos e Eclipsitas sempre estiveram em desacordo; Nós todos sabemos isso.",
  ui_story_5040_50400702_160_dialog_content = "Mas a razão pela qual me tornei um mensageiro foi para poder ajudar as pessoas a transmitir seus pensamentos e sentimentos umas às outras. É isso. E eu quero fazer o mesmo por ela.",
  ui_story_5040_50400702_161_dialog_content = "Eu disse que a ajudaria sem nem pensar nisso. Foi imprudente da minha parte fazer isso, mas fiz mesmo assim.",
  ui_story_5040_50400702_162_dialog_content = "É por isso que estou preparado para assumir total responsabilidade por tudo o que acontecer como resultado de minhas ações. Não importa o que... eu juro que vou pagar o preço.",
  ui_story_5040_50400702_163_dialog_content = "Se eu dissesse que queria machucar Sable, você ficaria na frente dela?",
  ui_story_5040_50400702_164_dialog_content = "Eu poderia.",
  ui_story_5040_50400702_165_dialog_content = "Bem, Kya, você é sempre sincero e termina o que começa. Da mesma forma, vou lidar com este assunto de forma adequada.",
  ui_story_5040_50400702_166_dialog_content = "...",
  ui_story_5040_50400702_167_dialog_content = "Você é muito mais interessante do que eu imaginava. Um pouco ingênuo, mas não desgosto da seriedade.",
  ui_story_5040_50400702_168_dialog_content = "Farei o que você pedir agora. Boa sorte, Kya.",
  ui_story_5040_50400702_169_dialog_content = "Então isso significa... que você está me ajudando?",
  ui_story_5040_50400702_170_dialog_content = "Obrigado! Muito obrigado, Lady Jeriah.",
  ui_story_5040_50400702_171_dialog_content = "E não se preocupe! Não importa o que aconteça, assumirei total responsabilidade até o fim.",
  ui_story_5040_50400801_1_dialog_content = "Sable, graças a você, conseguimos fazer algo realmente significativo em Gannon City. Vamos, vamos voltar e descansar um pouco agora.",
  ui_story_5040_50400801_2_dialog_content = "Tá bom...",
  ui_story_5040_50400801_3_dialog_content = "Você está bem? Sua tez parece um pouco estranha.",
  ui_story_5040_50400801_4_dialog_content = "Meu rosto?",
  ui_story_5040_50400801_5_dialog_content = "Sim. Não quero ser rude, mas você parece meio esgotado, só isso.",
  ui_story_5040_50400801_6_dialog_content = "Você tem ingerido vitaminas suficientes ultimamente? Ou talvez você esteja se sentindo um pouco indisposto?",
  ui_story_5040_50400801_7_dialog_content = "Eu... eu não... acho que não...",
  ui_story_5040_50400801_8_dialog_content = "Graaah!",
  ui_story_5040_50400801_9_dialog_content = "Graaooh!!",
  ui_story_5040_50400801_10_dialog_content = "O que? Mais Eclipsites?!",
  ui_story_5040_50400801_11_dialog_content = "Esta é a primeira vez que os vejo em Gannon City!",
  ui_story_5040_50400801_12_dialog_content = "Aaaaaaahhh! Alguém me salve!!",
  ui_story_5040_50400801_13_dialog_content = "H... Segure-se em... mim!",
  ui_story_5040_50400801_14_dialog_content = "D-Não tenha... medo...",
  ui_story_5040_50400801_15_dialog_content = "Sable! Pegue o menino e volte!",
  ui_story_5040_50400802_1_dialog_content = "Ufa... Vocês dois estão bem?",
  ui_story_5040_50400802_2_dialog_content = "S-Sim...",
  ui_story_5040_50400802_3_dialog_content = "Waaaah! V-você tem uma aparência tão assustadora!",
  ui_story_5040_50400802_4_dialog_content = "Eu...",
  ui_story_5040_50400802_5_dialog_content = "Não se preocupe com ele, Sable. O pobre garoto provavelmente ainda está em choque.",
  ui_story_5040_50400802_6_dialog_content = "Ainda assim, o que os Eclipsites estão fazendo no meio da cidade de Gannon?",
  ui_story_5040_50400802_7_dialog_content = "Ufa! Vocês dois me fizeram um grande favor!",
  ui_story_5040_50400802_8_dialog_content = "J-Jola?",
  ui_story_5040_50400802_9_dialog_content = "Este é um dos Eclipsites que Migard usa para teste. Por alguma razão, ele enlouqueceu e saiu do laboratório.",
  ui_story_5040_50400802_10_dialog_content = "Graças a Deus ninguém se machucou... graças a vocês dois, claro.",
  ui_story_5040_50400802_11_dialog_content = "Um Eclipsite usado para testes? Você quer dizer como os de hoje cedo?",
  ui_story_5040_50400802_12_dialog_content = "Precisamente. Migard capturou todos os tipos de Eclipsites. Eu não sei a natureza precisa de seus experimentos...",
  ui_story_5040_50400802_13_dialog_content = "mas parece que ela passa pelos Eclipsites capturados rapidamente.",
  ui_story_5040_50400802_14_dialog_content = "!!!",
  ui_story_5040_50400802_15_dialog_content = "Vocês precisam ter mais cuidado com suas cobaias! E se este conseguisse ferir alguém?",
  ui_story_5040_50400802_16_dialog_content = "Bem, esse tipo de coisa nunca aconteceu antes. Talvez haja algo em vocês que o atraiu.",
  ui_story_5040_50400802_17_dialog_content = "Falando nisso, Sable, podemos pedir a Migard para dar uma olhada em você. Ela tem todos os tipos de remédios em seu laboratório.",
  ui_story_5040_50400802_18_dialog_content = "Se você não estiver se sentindo bem, tenho certeza que ela poderá ajudar!",
  ui_story_5040_50400802_19_dialog_content = "Não... Não, obrigado!",
  ui_story_5040_50400802_20_dialog_content = "Eu... acabei de lembrar... algo importante!",
  ui_story_5040_50400802_21_dialog_content = "Eu preciso... ir... encontrar Kya!",
  ui_story_5040_50400802_22_dialog_content = "Hã?!",
  ui_story_5040_50400802_23_dialog_content = "Heheheh... Que amigo interessante você tem aí.",
  ui_story_5040_50400802_24_dialog_content = "(Está ficando tarde... Sable e os outros provavelmente estão esperando por mim. Eu deveria ir.)",
  ui_story_5040_50400802_25_dialog_content = "K... Kya!!!",
  ui_story_5040_50400802_26_dialog_content = "Sabre? O que você está fazendo aqui? Você não deveria estar com PlayerName agora mesmo?",
  ui_story_5040_50400802_27_dialog_content = "Eu quero... estar com você... Kya.",
  ui_story_5040_50400802_28_dialog_content = "Entendo... então vamos voltar juntos.",
  ui_story_5040_50400802_29_dialog_content = "<color=#e8d9bb>Growl...</color>",
  ui_story_5040_50400802_30_dialog_content = "O que é que foi isso...?",
  ui_story_5040_50400802_31_dialog_content = "Oh aquilo? Desculpe, isso foi apenas o meu estômago.",
  ui_story_5040_50400802_32_dialog_content = "Eu não comi nada o dia todo. Estou morrendo de fome!",
  ui_story_5040_50400802_33_dialog_content = "M... Eu também...",
  ui_story_5040_50400802_34_dialog_content = "Você também? Vamos, podemos encontrar um bom lugar para comer antes de dormir.",
  ui_story_5040_50400802_35_dialog_content = "Não! Eu... eu olho... As pessoas estão... assustadas...",
  ui_story_5040_50400802_36_dialog_content = "Sabre...?",
  ui_story_5040_50400802_37_dialog_content = "Não diga isso. Você pode não se parecer com a maioria dos aurorianos, mas é gentil do mesmo jeito.",
  ui_story_5040_50400802_38_dialog_content = "Podemos apenas comprar um pouco de pão para viagem. isso parece bom para você?",
  ui_story_5040_50400802_39_dialog_content = "Sim...",
  ui_story_5040_50400802_40_dialog_content = "Então a Federação Illumina te lembrou de mais alguma coisa, Sable?",
  ui_story_5040_50400802_41_dialog_content = "Não...",
  ui_story_5040_50400802_42_dialog_content = "Tudo bem! Pelo menos você se lembrou do deserto, certo? Aposto que teremos mais sorte quando chegarmos lá.",
  ui_story_5040_50400802_43_dialog_content = "Não se preocupe.",
  ui_story_5040_50400802_44_dialog_content = "Obrigada...",
  ui_story_5040_50400802_45_dialog_content = "Hmm, acho que vi um comerciante vendendo pão de laranja feito em casa na estação. Espere aqui por mim.",
  ui_story_5040_50400802_46_dialog_content = "Eu volto em breve, não vá a lugar nenhum!",
  ui_story_5040_50400802_47_dialog_content = "...!",
  ui_story_5040_50400802_48_dialog_content = "Isso soou... familiar...",
  ui_story_5040_50400802_49_dialog_content = "Eu volto em breve, é só me esperar aqui!",
  ui_story_5040_50400802_50_dialog_content = "Não vá a lugar nenhum, voltarei assim que comprar.",
  ui_story_5040_50400802_51_dialog_content = "Edward, por que você está falando tanto? Por que você ainda não voltou?",
  ui_story_5040_50400802_52_dialog_content = "Por que você não volta?",
  ui_story_5040_50400802_53_dialog_content = "É porque eu não sou bom o suficiente? Porque porque?!",
  ui_story_5040_50400802_54_dialog_content = "<size=45>Voltar!!!</size>",
  ui_story_5040_50400802_55_dialog_content = "Sentindo-se sem esperança? Como se não houvesse nada de que depender no mundo? Aceite esta semente e nunca mais terá medo de nada.",
  ui_story_5040_50400802_56_dialog_content = "Liberte-se do sofrimento dos fracos, pois você se tornará mais forte do que jamais imaginou!",
  ui_story_5040_50400802_57_dialog_content = "Aaaaaaahhh!!!",
  ui_story_5040_50400802_58_dialog_content = "Olha, Sable! É o Dia da Coroa da Lua, então consegui pãezinhos de canela. Aposto que você vai adorar.",
  ui_story_5040_50400802_59_dialog_content = "Sabre...?",
  ui_story_5040_50400802_60_dialog_content = "Aaaah! Olha mana, um Eclipsite!",
  ui_story_5040_50400802_61_dialog_content = "Tem um Eclipsite na cidade!",
  ui_story_5040_50400802_62_dialog_content = "Espera... tem certeza? Talvez seja outra coisa...",
  ui_story_5040_50400802_63_dialog_content = "Devemos chamar a Legião?",
  ui_story_5040_50400802_64_dialog_content = "!!!",
  ui_story_5040_50400802_65_dialog_content = "Fora do caminho!",
  ui_story_5040_50400802_66_dialog_content = "Sabre? Sable! Você está bem?!",
  ui_story_5040_50400802_67_dialog_content = "Ah...",
  ui_story_5040_50400802_68_dialog_content = "Vamos, Sable! Temos que sair daqui!",
  ui_story_5040_50400802_69_dialog_content = "Espere, vocês dois! Nomeie-se!",
  ui_story_5040_50400802_70_dialog_content = "Suspiro... Suspiro...",
  ui_story_5040_50400802_71_dialog_content = "Tranquilo!",
  ui_story_5040_50400802_72_dialog_content = "Argh...",
  ui_story_5040_50400802_73_dialog_content = "Estaremos em apuros se eles nos encontrarem!",
  ui_story_5040_50400802_74_dialog_content = "Por acaso você viu um Eclipsite de aparência estranha por aqui? Ela estava com uma garota.",
  ui_story_5040_50400802_75_dialog_content = "Oh meu, isso soa problemático. Acredito que eles estavam tentando escapar para a superfície... Devo chamar mais soldados?",
  ui_story_5040_50400802_76_dialog_content = "O que? Como eles chegaram lá tão rápido?! Depois deles!",
  ui_story_5040_50400802_77_dialog_content = "Jeriah... Obrigado.",
  ui_story_5040_50400802_78_dialog_content = "Parece que a barra está limpa. Você está ferido, Sable? Deixe-me ver!",
  ui_story_5040_50400802_79_dialog_content = "Estou bem.",
  ui_story_5040_50400802_80_dialog_content = "Desculpe por... fazer você se preocupar...",
  ui_story_5040_50400802_81_dialog_content = "O que você está dizendo? Eu nunca poderia me perdoar se você se machucasse enquanto eu estava comprando lanches.",
  ui_story_5040_50400802_82_dialog_content = "... Kya.",
  ui_story_5040_50400802_83_dialog_content = "Eu... eu me lembrei de algo.",
  ui_story_5040_50400802_84_dialog_content = "Realmente? O que você lembrou?",
  ui_story_5040_50400802_85_dialog_content = "Uma pessoa... Alguém que... disse as mesmas coisas... que você.",
  ui_story_5040_50400802_86_dialog_content = "Mas... ele nunca... voltou.",
  ui_story_5040_50400802_87_dialog_content = "Fui a algum lugar... a algum lugar distante... para procurá-lo.",
  ui_story_5040_50400802_88_dialog_content = "Ele me disse... que gostava de mim...",
  ui_story_5040_50400802_89_dialog_content = "Mas... no final... ele me deixou.",
  ui_story_5040_50400802_90_dialog_content = "Eu corri... corri de casa... fiquei com medo...",
  ui_story_5040_50400802_91_dialog_content = "Mas então... alguém me deu... uma semente.",
  ui_story_5040_50400802_92_dialog_content = "Disse-me... para ficar mais forte.",
  ui_story_5040_50400802_93_dialog_content = "Afinal, você é um auroriano!",
  ui_story_5040_50400802_94_dialog_content = "Mas como algo assim pode acontecer?!",
  ui_story_5040_50400802_95_dialog_content = "Essa poção... me acordou...",
  ui_story_5040_50400802_96_dialog_content = "Mas eu... esqueci de tudo... não confio em nada...",
  ui_story_5040_50400802_97_dialog_content = "Eu só quero ir para casa.",
  ui_story_5040_50400802_98_dialog_content = "Sabre...",
  ui_story_5040_50400802_99_dialog_content = "Não se preocupe, Sable. Eu prometo que vou levá-lo de volta para sua casa.",
  ui_story_5040_50400802_100_dialog_content = "Vamos partir para o Deserto de Rediesel amanhã cedo. Pode ser onde fica a sua casa.",
  ui_story_5040_50400802_101_dialog_content = "Obrigado... Kya.",
  ui_story_5040_50400802_102_dialog_content = "Minha mente... ultimamente, eu... posso senti-la... se esvaindo de novo.",
  ui_story_5040_50400802_103_dialog_content = "Não sei... quanto tempo... posso aguentar.",
  ui_story_5040_50400802_104_dialog_content = "Se eu... perder... Você vai ter que...",
  ui_story_5040_50400802_105_dialog_content = "Não diga mais nada! Vou garantir que você veja sua casa antes que isso aconteça. Podemos até encontrar uma maneira de evitar que sua consciência desapareça!",
  ui_story_5040_50400802_106_dialog_content = "Lembra do verme da areia rosa? Tenho certeza que encontraremos uma solução.",
  ui_story_5040_50400802_107_dialog_content = "Kya...",
  ui_story_5040_50400802_108_dialog_content = "Partimos amanhã, não há tempo a perder.",
  ui_story_5040_50400802_109_dialog_content = "Você está indo para casa, Sable.",
  ui_story_5040_50400901_1_dialog_content = "Aqui estamos. Fique à vontade.",
  ui_story_5040_50400901_2_dialog_content = "Então esta é a divisão Rediesel Wrench da Courier Union, hein?",
  ui_story_5040_50400901_3_dialog_content = "O exterior pode estar um pouco dilapidado, mas é lindo aqui! Totalmente não o que eu estava esperando.",
  ui_story_5040_50400901_X3_dialog_content = "Certo, sem falar que a localização é tão difícil de encontrar!",
  ui_story_5040_50400901_X4_dialog_content = "Os edifícios da base Rediesel Wrench são todos construídos de forma tão aleatória que é difícil até encontrar a estrada...",
  ui_story_5040_50400901_X5_dialog_content = "Você tem que girar e virar em becos por uns bons dez minutos antes mesmo de chegar a este lugar!",
  ui_story_5040_50400901_X6_dialog_content = "Levei séculos para encontrá-lo quando cheguei aqui.",
  ui_story_5040_50400901_X7_dialog_content = "Isso significa que você tem um bom senso de direção!",
  ui_story_5040_50400901_X8_dialog_content = "Quando cheguei aqui, demorei tanto para encontrá-lo que quase desisti.",
  ui_story_5040_50400901_4_dialog_content = "Mesmo que esta seja a segunda vez que vejo essas decorações, elas ainda são tão surpreendentes.",
  ui_story_5040_50400901_5_dialog_content = "Não é apenas a decoração, também. Há tantos ornamentos finos dentro que é ofuscante.",
  ui_story_5040_50400901_6_dialog_content = "Realmente não parece o estilo Rediesel Wrench!",
  ui_story_5040_50400901_7_dialog_content = "Que tipo de cretino vulgar você acha que eu sou?",
  ui_story_5040_50400901_8_dialog_content = "Não foi o que eu quis dizer...",
  ui_story_5040_50400901_9_dialog_content = "Está tudo bem, eu estava brincando.",
  ui_story_5040_50400901_10_dialog_content = "Jerias, eu esperava dar uma olhada com Sable...",
  ui_story_5040_50400901_11_dialog_content = "Sem problemas. Vá bisbilhotar onde quiser.",
  ui_story_5040_50400901_12_dialog_content = "Sério?",
  ui_story_5040_50400901_13_dialog_content = "Apenas lembre-se de colocar tudo de volta onde você o encontrou.",
  ui_story_5040_50400901_14_dialog_content = "Claro que não!",
  ui_story_5040_50400901_15_dialog_content = "Vamos, Sable!",
  ui_story_5040_50400901_16_dialog_content = "Eu deveria ir preparar o carro e as armas também.",
  ui_story_5040_50400901_17_dialog_content = "Em breve será noite. Vocês deveriam apenas descansar aqui esta noite.",
  ui_story_5040_50400901_18_dialog_content = "O carro? Não seria mais rápido usar o Colossus?",
  ui_story_5040_50400901_X18_dialog_content = "E o Colosso é tão grande. Parece muito mais seguro do que um carro.",
  ui_story_5040_50400901_19_dialog_content = "Os vermes da areia sabem se movimentar acima e abaixo do solo.",
  ui_story_5040_50400901_20_dialog_content = "Eles são diabinhos astutos, peritos em navegar em cavernas subterrâneas.",
  ui_story_5040_50400901_21_dialog_content = "Se você não agarrá-los no primeiro segundo que puder, eles desaparecerão.",
  ui_story_5040_50400901_X21_dialog_content = "O quê?!",
  ui_story_5040_50400901_X22_dialog_content = "Jeriah está certo.",
  ui_story_5040_50400901_22_dialog_content = "O Colossus pode ser rápido, mas como passageiro, não há como enfrentá-los à primeira vista.",
  ui_story_5040_50400901_X23_dialog_content = "Eu experimentei isso em primeira mão, confie em mim.",
  ui_story_5040_50400901_23_dialog_content = "Entendo...",
  ui_story_5040_50400901_24_dialog_content = "Você tem muito mais a aprender sobre o deserto.",
  ui_story_5040_50400901_25_dialog_content = "Eu deveria estar indo. Vamos sair amanhã cedo para caçar vermes da areia.",
  ui_story_5040_50400901_26_dialog_content = "<color=#e8d9bb>*Rumble*</color>",
  ui_story_5040_50400901_27_dialog_content = "Foi mal!",
  ui_story_5040_50400901_28_dialog_content = "Estivemos tão ocupados que me esqueci completamente de comer.",
  ui_story_5040_50400901_29_dialog_content = "<color=#e8d9bb>*Rrrumble*</color>",
  ui_story_5040_50400901_30_dialog_content = "Estou com muita fome também.",
  ui_story_5040_50400901_31_dialog_content = "Bem, já que estamos no deserto, deixe-me preparar algumas especialidades Rediesel Wrench para você!",
  ui_story_5040_50400901_32_dialog_content = "Deixe-me acender o fogo lá fora e faremos um churrasco!",
  ui_story_5040_50400901_33_dialog_content = "Eu ajudo!",
  ui_story_5040_50400901_34_dialog_content = "E então houve um.",
  ui_story_5040_50400901_35_dialog_content = "Eu provavelmente não deveria terceira roda Tara e Adonis, mas não acho que Kya e Sable precisem de ajuda também.",
  ui_story_5040_50400901_36_dialog_content = "De qualquer forma, só estou me perguntando se muitos de nós conseguiríamos lidar com um verme da areia tão grande quanto dizem.",
  ui_story_5040_50400901_37_dialog_content = "Jeriah parece muito forte, e Tara é uma boa lutadora... mas ainda estou um pouco preocupado.",
  ui_story_5040_50400901_38_dialog_content = "Eu deveria encontrar Jeriah, ver se ela acha que precisamos de reforços.",
  ui_story_5040_50400901_39_dialog_content = "Você veio me procurar porque estava preocupado, pequeno celestita?",
  ui_story_5040_50400901_40_dialog_content = "P-Por favor, não me chame assim.",
  ui_story_5040_50400901_41_dialog_content = "Não há necessidade de se preocupar. Conheço este deserto como a palma da minha mão.",
  ui_story_5040_50400901_42_dialog_content = "Já inspecionei o carro e preparei os suprimentos. Apenas cuidem-se e tudo ficará bem.",
  ui_story_5040_50400901_43_dialog_content = "Mas os vermes da areia são feras formidáveis. Eu me preocupo que não seremos capazes de lidar com isso sozinhos.",
  ui_story_5040_50400901_44_dialog_content = "Devemos recrutar alguns outros para ajudar? E Sinsa, Azure e tudo isso?",
  ui_story_5040_50400901_45_dialog_content = "Não há necessidade.",
  ui_story_5040_50400901_46_dialog_content = "Mas...",
  ui_story_5040_50400901_47_dialog_content = "Eu não preciso da ajuda de ninguém.",
  ui_story_5040_50400901_48_dialog_content = "Só eu vou fazer. É apenas um verme da areia, alguns golpes irão derrubá-lo.",
  ui_story_5040_50400901_49_dialog_content = "Agora, se não precisar de mais nada, pode voltar.",
  ui_story_5040_50400901_50_dialog_content = "Tenho outras coisas para fazer e não preciso me incomodar com as preocupações das crianças.",
  ui_story_5040_50400901_51_dialog_content = "...",
  ui_story_5040_50400901_52_dialog_content = "Tá bom.",
  ui_story_5040_50400901_S52_dialog_content = "É melhor eu voltar para Soroz.",
  ui_story_5040_50400901_53_dialog_content = "Uau... Eu realmente acabei de ser perseguido por Jeriah.",
  ui_story_5040_50400901_54_dialog_content = "Esqueça. Se ela quer que eu cuide da minha vida, é isso que vou fazer!",
  ui_story_5040_50400901_55_dialog_content = "...",
  ui_story_5040_50400901_X55_dialog_content = "(Todo esse tempo, Jerias sempre apareceu como alguém que se diverte vendo as coisas acontecerem.)",
  ui_story_5040_50400901_X56_dialog_content = "(Mesmo que ela seja um membro sênior do Courier Union, ainda não posso confiar nela.)",
  ui_story_5040_50400901_X57_dialog_content = "(Só vou enviar uma mensagem de terminal para o pessoal da Rediesel Wrench para ficar seguro.)",
  ui_story_5040_50400901_X58_dialog_content = "(Espero que alguém esteja por perto e responda...)",
  ui_story_5040_50400901_56_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_5040_50400901_57_dialog_content = "Olá PlayerName, este é Odi. Esta ouvindo?",
  ui_story_5040_50400901_58_dialog_content = "Odi!",
  ui_story_5040_50400901_59_dialog_content = "Cópia de! Isso é ótimo, eu realmente não esperava que alguém respondesse!",
  ui_story_5040_50400901_60_dialog_content = "Em que posso ajudar?",
  ui_story_5040_50400901_61_dialog_content = "Por acaso você sabe alguma coisa sobre um verme da areia rosa?",
  ui_story_5040_50400901_62_dialog_content = "Um... verme da areia rosa? Hmm, isso soa um sino.",
  ui_story_5040_50400901_63_dialog_content = "Acho que Sinsa encontrou um há cerca de um mês.",
  ui_story_5040_50400901_64_dialog_content = "Ninguém nunca tinha visto um verme da areia como aquele antes, então todos correram para tentar capturá-lo, mas ele fugiu.",
  ui_story_5040_50400901_65_dialog_content = "Não tenho os detalhes precisos. Deixe-me chamar o chefe, e você mesmo pode perguntar a ele.",
  ui_story_5040_50400901_66_dialog_content = "Claro. Desculpe pelo incômodo!",
  ui_story_5040_50400901_67_dialog_content = "Ei, PlayerName! E aí?",
  ui_story_5040_50400901_68_dialog_content = "Odi disse que você estava perguntando sobre o verme da areia rosa?",
  ui_story_5040_50400901_69_dialog_content = "Sim. O que você pode me contar?",
  ui_story_5040_50400901_70_dialog_content = "O que você quer saber? Aquele bruto é um dos poucos vermes da areia que podem escapar de mim.",
  ui_story_5040_50400901_71_dialog_content = "Mais ou menos um mês atrás, eu estava decidido a caçá-lo, mas no final do dia ele fugiu e só consegui voltar para casa com uma balança.",
  ui_story_5040_50400901_72_dialog_content = "Tsk... Que pena. Só aquela balança foi vendida por um bom dinheiro. Imagine o que você poderia fazer se pegasse um inteiro!",
  ui_story_5040_50400901_73_dialog_content = "Afinal, ninguém nunca tinha visto um verme da areia rosa antes. Quem pode dizer se não foi o único em todo o mundo? E você sabe que quanto mais raro algo é, mais caro!",
  ui_story_5040_50400901_74_dialog_content = "Por que você está atrás de um verme da areia rosa? Deixe-me adivinhar, você está com Jeriah?",
  ui_story_5040_50400901_75_dialog_content = "Como você sabia?!",
  ui_story_5040_50400901_76_dialog_content = "Porque aquele Orador de Jeriah está por toda parte, voando de um lado para o outro entre todos os terrenos habituais dos vermes da areia.",
  ui_story_5040_50400901_77_dialog_content = "E se você está procurando por um verme da areia agora, acho que há boas chances de você estar procurando por aquele cara grande e rosa.",
  ui_story_5040_50400901_78_dialog_content = "É uma loucura usar tanto Luminatics.",
  ui_story_5040_50400901_79_dialog_content = "Você sabe onde é??",
  ui_story_5040_50400901_80_dialog_content = "Claro que sim. Mas essa informação vai te custar, garoto. O que você tem em troca?",
  ui_story_5040_50400901_81_dialog_content = "Hum... eu...",
  ui_story_5040_50400901_82_dialog_content = "Hahaha... Olha você, tremendo assim! O que, você acha que estou tentando enganá-lo ou algo assim?",
  ui_story_5040_50400901_83_dialog_content = "Apenas lembre-se de trazer um pouco de chocolate para Eve na próxima vez que vier aqui, e estamos bem.",
  ui_story_5040_50400901_84_dialog_content = "Ela ouviu dizer que a Umbraton tem um chocolate especial de edição limitada para este festival Crown-qualquer coisa e ela está pedindo por isso.",
  ui_story_5040_50400901_85_dialog_content = "Você está sempre naquele seu colosso voando por toda parte, então apenas ajude-a a pegar alguns no caminho.",
  ui_story_5040_50400901_86_dialog_content = "De nada.",
  ui_story_5040_50400901_87_dialog_content = "Bem, então temos um acordo.",
  ui_story_5040_50400901_88_dialog_content = "A última vez que lutei com aquela maldita coisa, estava escorregadia como o inferno, sempre encontrando um lugar para se esconder.",
  ui_story_5040_50400901_89_dialog_content = "Mas levei uma boa pancada com minha chave inglesa antes que ela escapasse, o que arrancou aquela escama do lado esquerdo.",
  ui_story_5040_50400901_90_dialog_content = "Eu o persegui por dias, mas acabei perdendo a trilha. O último lugar que vi foi no meio do deserto, perto do Oasis.",
  ui_story_5040_50400901_91_dialog_content = "Não posso lhe dizer sua localização precisa, no entanto.",
  ui_story_5040_50400901_92_dialog_content = "Se você deseja aceitá-lo, é melhor começar sua pesquisa a partir daí.",
  ui_story_5040_50400901_93_dialog_content = "Entendi! Muito obrigado Sinsa.",
  ui_story_5040_50400901_94_dialog_content = "Se você está com Jeriah, duvido que isso vá causar muitos problemas. Mas seja cauteloso, é um trapaceiro infernal.",
  ui_story_5040_50400901_95_dialog_content = "O que te faz dizer isso? Você conhece Jeriah bem?",
  ui_story_5040_50400901_96_dialog_content = "Eu não diria isso. Ela guarda para si mesma e não fala muito com o resto de nós.",
  ui_story_5040_50400901_97_dialog_content = "Mas ser capaz de sobreviver sozinha no Deserto de Rediesel é uma prova de sua força.",
  ui_story_5040_50400901_98_dialog_content = "Além disso, ela é uma das poucas mensageiras no deserto, então nós realmente confiamos nela.",
  ui_story_5040_50400901_99_dialog_content = "Só não se preocupe, faça o que ela diz e você ficará bem!",
  ui_story_5040_50400901_100_dialog_content = "Tá bom...",
  ui_story_5040_50400901_101_dialog_content = "Sim!",
  ui_story_5040_50400901_102_dialog_content = "De qualquer forma, eu provavelmente deveria ir, ou Eve vai estar me importunando para ir descansar.",
  ui_story_5040_50400901_103_dialog_content = "Tudo bem, até mais!",
  ui_story_5040_50400901_104_dialog_content = "Eu provavelmente não deveria ir direto para Jeriah agora. Primeiro, vou preencher os outros.",
  ui_story_5040_50400901_105_dialog_content = "Sem contar que também estou morrendo de fome! Vamos ver o que tem no cardápio hoje!",
  ui_story_5040_50400901_106_dialog_content = "<color=#e8d9bb>Enquanto isso, na divisão Courier Union Rediesel Wrench...</color>",
  ui_story_5040_50400901_107_dialog_content = "Todas as cartas atrasadas devem estar aqui.",
  ui_story_5040_50400901_108_dialog_content = "Com o vasto deserto e todos os caras da Rediesel Wrench correndo por todo o lugar, não é surpresa que haja muitas correspondências não reclamadas.",
  ui_story_5040_50400901_109_dialog_content = "Provavelmente vai demorar um pouco para encontrar o que estamos procurando.",
  ui_story_5040_50400901_110_dialog_content = "Sable... vai... ajudar...",
  ui_story_5040_50400901_111_dialog_content = "Vamos trabalhar juntos! Primeiro precisamos ver quantas letras existem.",
  ui_story_5040_50400901_112_dialog_content = "Muitos!",
  ui_story_5040_50400901_113_dialog_content = "Espere, estes têm notas sobre eles.",
  ui_story_5040_50400901_114_dialog_content = "\"Destinatário ausente\", \"Destinatário desconhecido\", \"Rejeitado\"...",
  ui_story_5040_50400901_115_dialog_content = "Eles realmente foram arquivados em diferentes categorias?!",
  ui_story_5040_50400901_116_dialog_content = "Kya... olha... ali.",
  ui_story_5040_50400901_117_dialog_content = "Este diz \"mesmo carimbo\"?!",
  ui_story_5040_50400901_118_dialog_content = "Há algumas palavras rabiscadas abaixo, que dizem: \"Suspeite que o remetente seja a mesma pessoa.\"",
  ui_story_5040_50400901_119_dialog_content = "O selo aqui é igual ao seu, Sable.",
  ui_story_5040_50400901_120_dialog_content = "Estes são meus...",
  ui_story_5040_50400901_121_dialog_content = "Não acredito que encontramos o que procurávamos tão rapidamente. Obrigado Senhor!",
  ui_story_5040_50400901_122_dialog_content = "Vamos dar uma olhada nas letras.",
  ui_story_5040_50400901_123_dialog_content = "Sim...",
  ui_story_5040_50400901_124_dialog_content = "\"Obrigado por concordar em ser meu amigo por correspondência! Prazer em conhecê-lo.\"",
  ui_story_5040_50400901_125_dialog_content = "\"O deserto é muito quente para a maioria das pessoas, então todos parecem morar muito longe. Temos que contar com mensageiros para nos comunicarmos.\"",
  ui_story_5040_50400901_126_dialog_content = "\"Se pudéssemos viajar juntos, ficaria feliz em deixar o deserto.\"",
  ui_story_5040_50400901_127_dialog_content = "Essas cartas parecem ter sido escritas quando você conheceu o destinatário.",
  ui_story_5040_50400901_128_dialog_content = "O endereço do destinatário é sempre diferente e não há endereço do remetente.",
  ui_story_5040_50400901_129_dialog_content = "Sua casa poderia estar no deserto?",
  ui_story_5040_50400901_130_dialog_content = "Milímetros...",
  ui_story_5040_50400901_131_dialog_content = "Ah!!",
  ui_story_5040_50400901_132_dialog_content = "Sabre?!",
  ui_story_5040_50400901_133_dialog_content = "Eu lembro...",
  ui_story_5040_50400901_134_dialog_content = "Minha casa... deserto profundo...",
  ui_story_5040_50400901_135_dialog_content = "Mas... onde... não me lembro...",
  ui_story_5040_50400901_136_dialog_content = "Isso não importa, isso já é um lead realmente útil. Em seguida, só temos que perguntar às pessoas que vivem no deserto!",
  ui_story_5040_50400901_137_dialog_content = "Não se esforce demais para lembrar. Faça uma pausa primeiro.",
  ui_story_5040_50400901_138_dialog_content = "Aceitei seu pedido, então o mensageiro em mim fará o possível para ajudá-lo.",
  ui_story_5040_50400901_139_dialog_content = "Tá bom...",
  ui_story_5040_50400901_140_dialog_content = "O que há de errado, Sable? Você parece um pouco apático.",
  ui_story_5040_50400901_141_dialog_content = "Tara, Adonis... Bom relacionamento...",
  ui_story_5040_50400901_142_dialog_content = "Valorizem... uns aos outros... ajudem... uns aos outros...",
  ui_story_5040_50400901_143_dialog_content = "Eu quero...",
  ui_story_5040_50400901_144_dialog_content = "(Sable não foi bem tratada pela pessoa que amava, nem seu amor foi correspondido.)",
  ui_story_5040_50400901_145_dialog_content = "(Ver aqueles dois tão felizes deve deixá-la triste...)",
  ui_story_5040_50400901_146_dialog_content = "Não se sinta mal. Aquele cara que te tratou tão mal agora está no passado!",
  ui_story_5040_50400901_147_dialog_content = "Meus mais velhos sempre me dizem que, em sua experiência, o carma sempre atinge aqueles que não tratam bem os outros.",
  ui_story_5040_50400901_148_dialog_content = "Quanto a Tara e Adonis, se estar perto deles te incomoda, podemos simplesmente sair daqui e continuar por nós mesmos.",
  ui_story_5040_50400901_149_dialog_content = "Tudo bem...",
  ui_story_5040_50400901_150_dialog_content = "Eles... me lembram... tempos mais felizes...",
  ui_story_5040_50400901_151_dialog_content = "Família... Amigos... Amor...",
  ui_story_5040_50400901_152_dialog_content = "Esse sentimento caloroso... É tudo que eu sempre quis...",
  ui_story_5040_50400901_153_dialog_content = "Esse calor... é precioso, então eu... desejo-lhes felicidades...",
  ui_story_5040_50400901_154_dialog_content = "Tá bom...",
  ui_story_5040_50400901_155_dialog_content = "<color=#e8d9bb>*Rrrumble*</color>",
  ui_story_5040_50400901_156_dialog_content = "Com fome...",
  ui_story_5040_50400901_157_dialog_content = "Eu também. Vamos comer alguma coisa!",
  ui_story_5040_50400901_158_dialog_content = "(Não sabia que tinha ficado tão tarde, e não sei como Tara e os outros estão jantando.)",
  ui_story_5040_50400901_159_dialog_content = "Atchim!",
  ui_story_5040_50400901_160_dialog_content = "(T-Este sabor pungente e picante só pode ser ... Churrasco Rediesel!)",
  ui_story_5040_50400901_161_dialog_content = "Hum? Kya, Sable, vocês dois não estavam apenas explorando?",
  ui_story_5040_50400901_162_dialog_content = "Já terminamos, e como estamos morrendo de fome, resolvemos voltar e ver como estava o jantar!",
  ui_story_5040_50400901_163_dialog_content = "Sim...",
  ui_story_5040_50400901_164_dialog_content = "(Eu não fazia ideia de que o acúmulo de correspondências já havia sido separado e categorizado.)",
  ui_story_5040_50400901_165_dialog_content = "(Eles foram organizados juntos pelo remetente com base em pequenas semelhanças!)",
  ui_story_5040_50400901_166_dialog_content = "(Foi apenas graças a isso que conseguimos encontrar a correspondência de Sable tão rapidamente.)",
  ui_story_5040_50400901_167_dialog_content = "(Suponho que foi tudo Jeriah.)",
  ui_story_5040_50400901_168_dialog_content = "Com certeza está animado por aqui.",
  ui_story_5040_50400901_169_dialog_content = "Aquele cheiro... ha. Vocês da Rediesel Wrench só sabem fazer churrasco de fogo, hein?",
  ui_story_5040_50400901_170_dialog_content = "Quando você está no deserto, você come como um morador do deserto.",
  ui_story_5040_50400901_171_dialog_content = "Você fez tudo, Jeriah?",
  ui_story_5040_50400901_172_dialog_content = "Sim. O carro e os suprimentos estão prontos, e também identifiquei o alcance ativo do verme da areia.",
  ui_story_5040_50400901_173_dialog_content = "Ele está ferido em um ataque anterior, então está se dirigindo para o deserto.",
  ui_story_5040_50400901_174_dialog_content = "(Isso está de acordo com o que Sinsa me disse.)",
  ui_story_5040_50400901_175_dialog_content = "(Melhor não dizer nada, caso Jeriah fique chateado de novo...)",
  ui_story_5040_50400901_176_dialog_content = "No momento ideal! A carne seca de lagarto está pronta, vem comer!",
  ui_story_5040_50400901_177_dialog_content = "Isso é realmente um espeto? Você nem consegue ver nada sob todo o chili.",
  ui_story_5040_50400901_178_dialog_content = "Isso é conhecido como espasmódico de lagarto ultra-picante. Apenas os mais corajosos aventureiros culinários se atrevem a provar este pináculo da cozinha Rediesel.",
  ui_story_5040_50400901_179_dialog_content = "Er, eu tenho que?",
  ui_story_5040_50400901_180_dialog_content = "Tem tanto chili nele, só de olhar faz meus olhos arderem.",
  ui_story_5040_50400901_181_dialog_content = "Você vai ter algum ou não?",
  ui_story_5040_50400901_182_dialog_content = "Sim! Claro que sou.",
  ui_story_5040_50400901_183_dialog_content = "Não se force, Adônis.",
  ui_story_5040_50400901_184_dialog_content = "*mastigar*",
  ui_story_5040_50400901_185_dialog_content = "...",
  ui_story_5040_50400901_186_dialog_content = "Ele- Ele comeu tudo de uma vez?",
  ui_story_5040_50400901_187_dialog_content = "...!",
  ui_story_5040_50400901_188_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5040_50400901_189_dialog_content = "A-Adônis?!",
  ui_story_5040_50400901_190_dialog_content = "Hahaha, você olharia para isso! Ele ficou totalmente roxo!",
  ui_story_5040_50400901_191_dialog_content = "Apimentado...",
  ui_story_5040_50400901_192_dialog_content = "<size=45>TÃO PICANTE!!</size>",
  ui_story_5040_50400901_193_dialog_content = "Nossa, parece que ele vai desmaiar!",
  ui_story_5040_50400901_194_dialog_content = "Rápido, alguém traga um pouco de leite para ele! Ouvi dizer que o leite é bom para neutralizar a comida picante!",
  ui_story_5040_50400901_195_dialog_content = "Eu vou olhar!",
  ui_story_5040_50400901_196_dialog_content = "...",
  ui_story_5040_50400901_197_dialog_content = "(Por que ela foi? Vou ver o que está acontecendo.)",
  ui_story_5040_50400901_198_dialog_content = "Eu encontrei um pouco de leite!",
  ui_story_5040_50400901_199_dialog_content = "Adônis, beba isso!",
  ui_story_5040_50400901_200_dialog_content = "*glu glu glu glu*",
  ui_story_5040_50400901_201_dialog_content = "Ah... Ahhh... Ainda estou respirando...?",
  ui_story_5040_50400901_202_dialog_content = "Você acabou de comer um espeto inteiro de carne seca de lagarto ultrapicante e caiu.",
  ui_story_5040_50400901_203_dialog_content = "Sério?",
  ui_story_5040_50400901_204_dialog_content = "Urgh... Meu estômago dói, como se eu tivesse engolido um pedaço de carvão em brasa...",
  ui_story_5040_50400901_205_dialog_content = "<size=45><anim type=Shake>Ugh!</anim></size>",
  ui_story_5040_50400901_206_dialog_content = "Adônis?!!",
  ui_story_5040_50400901_207_dialog_content = "<color=#e8d9bb>Enquanto isso...</color>",
  ui_story_5040_50400901_208_dialog_content = "Seu namorado está vomitando os miolos ali. Você não vai ver se ele está bem?",
  ui_story_5040_50400901_209_dialog_content = "Ou você tem outra ideia brilhante?",
  ui_story_5040_50400901_210_dialog_content = "Vou levar Adonis de volta para Northland assim que ele se recuperar.",
  ui_story_5040_50400901_211_dialog_content = "Estou exausta. Eu não quero mais fazer isso.",
  ui_story_5040_50400901_212_dialog_content = "Não fomos feitos para ficar juntos. Não somos compatíveis.",
  ui_story_5040_50400901_213_dialog_content = "Ah?",
  ui_story_5040_50400901_214_dialog_content = "Eu costumava pensar que enquanto estivéssemos juntos, poderíamos superar qualquer coisa.",
  ui_story_5040_50400901_215_dialog_content = "Sempre quis dar a ele um gostinho da vida no Deserto de Rediesel, como o churrasco de agora...",
  ui_story_5040_50400901_216_dialog_content = "mas nunca pensei que as coisas de que gostava realmente lhe causassem mal.",
  ui_story_5040_50400901_217_dialog_content = "Ele continua se machucando, tudo porque está se forçando a ceder a mim.",
  ui_story_5040_50400901_218_dialog_content = "Não acho que isso seja amor.",
  ui_story_5040_50400901_X218_dialog_content = "Suspiro ... passarinhos apaixonados certamente tiram todo tipo de conclusões sobre assuntos triviais.",
  ui_story_5040_50400901_X219_dialog_content = "Por que acha isso?",
  ui_story_5040_50400901_219_dialog_content = "Existe um abismo entre nós, seja no estilo de vida ou na personalidade. Talvez seus pais estivessem certos.",
  ui_story_5040_50400901_220_dialog_content = "Os pássaros do norte não têm penas finas e não sabem cavar em busca de água, então é claro que não podem sobreviver no deserto.",
  ui_story_5040_50400901_221_dialog_content = "...",
  ui_story_5040_50400901_222_dialog_content = "Isso não é algo que qualquer quantidade de bravura pode superar. É uma questão de diferenças inatas.",
  ui_story_5040_50400901_223_dialog_content = "O que é comum para os pássaros do deserto é perigoso para os do norte.",
  ui_story_5040_50400901_224_dialog_content = "Mas...",
  ui_story_5040_50400901_225_dialog_content = "Mas o quê?",
  ui_story_5040_50400901_226_dialog_content = "Aquele seu passarinho não aguenta nada picante, mas mesmo assim comeu um espeto e acabou no chão.",
  ui_story_5040_50400901_227_dialog_content = "Certamente ele queria mostrar a você, mesmo que apenas por um momento, sua disposição de intensificar e ser corajoso?",
  ui_story_5040_50400901_228_dialog_content = "Vocês podem encontrar um estilo de vida que funcione para vocês dois gradualmente.",
  ui_story_5040_50400901_229_dialog_content = "Ao invés de limitar-se a viver apenas o estilo de vida Rediesel.",
  ui_story_5040_50400901_230_dialog_content = "...!",
  ui_story_5040_50400901_231_dialog_content = "Isso é tudo que eu queria dizer.",
  ui_story_5040_50400901_232_dialog_content = "Quer vocês dois acabem juntos ou não, vocês estão aqui agora, então é melhor aproveitar.",
  ui_story_5040_50400901_233_dialog_content = "Relaxe, divirta-se e não diminua a atmosfera.",
  ui_story_5040_50400901_234_dialog_content = "...",
  ui_story_5040_50400901_235_dialog_content = "Hmm...",
  ui_story_5040_50400901_236_dialog_content = "Vou voltar.",
  ui_story_5040_50400901_237_dialog_content = "Que passarinho interessante.",
  ui_story_5040_50400901_238_dialog_content = "Estou curioso para saber o que o próximo capítulo de seu relacionamento trará.",
  ui_story_5040_50400901_239_dialog_content = "... Ha, o que aconteceu comigo?",
  ui_story_5040_50400901_240_dialog_content = "Nem acredito que me importo.",
  ui_story_5040_50401001_1_dialog_content = "Ah, você já veio?",
  ui_story_5040_50401001_2_dialog_content = "Combinamos de procurar o verme da areia hoje, então acordei especialmente cedo.",
  ui_story_5040_50401001_3_dialog_content = "Além disso, ninguém teve coragem de comer aqueles espetos, então eventualmente tivemos que procurar algo para comer em Soroz...",
  ui_story_5040_50401001_4_dialog_content = "Vocês simplesmente não apreciam boa comida. Mas não se preocupe, eu comi o resto do churrasco.",
  ui_story_5040_50401001_5_dialog_content = "Nenhuma mordida foi desperdiçada!",
  ui_story_5040_50401001_6_dialog_content = "Eu definitivamente aprovo não desperdiçar comida.",
  ui_story_5040_50401001_7_dialog_content = "Então, como todos dormiram ontem à noite?",
  ui_story_5040_50401001_8_dialog_content = "Eu pessoalmente dormi incrivelmente.",
  ui_story_5040_50401001_9_dialog_content = "Está frio no deserto à noite, mas felizmente você preparou cobertores grossos, então Sable e eu estávamos bem.",
  ui_story_5040_50401001_10_dialog_content = "Obrigado... Jerias.",
  ui_story_5040_50401001_11_dialog_content = "Oh, sem problemas, Sable.",
  ui_story_5040_50401001_12_dialog_content = "eu, eh...",
  ui_story_5040_50401001_13_dialog_content = "Minha barriga doeu a noite toda...",
  ui_story_5040_50401001_14_dialog_content = "(Deve ter sido Adonis que ouvi correndo para o banheiro várias vezes ontem à noite, então.)",
  ui_story_5040_50401001_15_dialog_content = "Quer descansar um pouco antes de sair?",
  ui_story_5040_50401001_16_dialog_content = "Eu estou bem!",
  ui_story_5040_50401001_17_dialog_content = "Estou totalmente bem, sério!",
  ui_story_5040_50401001_18_dialog_content = "...",
  ui_story_5040_50401001_19_dialog_content = "(Tara está com uma cara engraçada desde o jantar de ontem à noite. Tem algo em mente?)",
  ui_story_5040_50401001_20_dialog_content = "Tudo bem. Nesse caso, vamos em frente. Tara pode ficar no banco do passageiro e o resto de vocês no banco de trás.",
  ui_story_5040_50401001_21_dialog_content = "<color=#e8d9bb>Algum tempo depois...</color>",
  ui_story_5040_50401001_22_dialog_content = "Isso fica perto da área do deserto profundo habitado pelos vermes da areia.",
  ui_story_5040_50401001_23_dialog_content = "Vamos fazer nosso descanso final aqui.",
  ui_story_5040_50401001_24_dialog_content = "Tirei a barraca, utensílios de cozinha e toda a comida do carro com Sable.",
  ui_story_5040_50401001_25_dialog_content = "Podemos começar a cozinhar a qualquer momento!",
  ui_story_5040_50401001_26_dialog_content = "Bom trabalho.",
  ui_story_5040_50401001_27_dialog_content = "Agora que toda a bagagem foi descarregada, vamos voltar para o carro.",
  ui_story_5040_50401001_28_dialog_content = "Huh? Por que? Não vamos descansar?",
  ui_story_5040_50401001_29_dialog_content = "Ainda temos mais uma coisa a fazer antes disso.",
  ui_story_5040_50401001_30_dialog_content = "As dunas de areia à frente são íngremes e inclinadas. Pegar essas ondas de areia é a maneira perfeita de se soltar e relaxar.",
  ui_story_5040_50401001_31_dialog_content = "O que as dunas de areia têm a ver com relaxar?",
  ui_story_5040_50401001_32_dialog_content = "Você descobrirá em um momento, passarinho de Northland.",
  ui_story_5040_50401001_X32_dialog_content = "Tudo bem, entre no carro.",
  ui_story_5040_50401001_X33_dialog_content = "Mas é...",
  ui_story_5040_50401001_X34_dialog_content = "Pare de gaguejar e entre no carro!",
  ui_story_5040_50401001_X35_dialog_content = "Você também pode vir, pequena celestita.",
  ui_story_5040_50401001_X36_dialog_content = "<color=#e8d9bb>No carro</color>",
  ui_story_5040_50401001_X37_dialog_content = "Todos estão prontos para ir?",
  ui_story_5040_50401001_X38_dialog_content = "Jeriah, o-o que você está planejando fazer?",
  ui_story_5040_50401001_X39_dialog_content = "Ora, vou fazer algo para deixar Tara feliz, é claro.",
  ui_story_5040_50401001_X40_dialog_content = "Eu tenho um mau pressentimento sobre isso... Você pode me deixar sair daqui!?",
  ui_story_5040_50401001_X41_dialog_content = "Eu vou fazer o seu almoço—",
  ui_story_5040_50401001_X42_dialog_content = "Sem chance. Você é uma parte indispensável desta experiência.",
  ui_story_5040_50401001_33_option_content = "Indispensável!?",
  ui_story_5040_50401001_34_dialog_content = "Claro. Você é nosso navegador vital.",
  ui_story_5040_50401001_35_option_content = "Acho que vou passar!",
  ui_story_5040_50401001_36_dialog_content = "Agora não fique com os pés frios.",
  ui_story_5040_50401001_37_dialog_content = "Lembre-se de apertar o cinto de segurança.",
  ui_story_5040_50401001_38_dialog_content = "<color=#e8d9bb>Estrondo!</color>",
  ui_story_5040_50401001_39_dialog_content = "Ahhh!",
  ui_story_5040_50401001_40_dialog_content = "I-Isso é muito rápido!",
  ui_story_5040_50401001_41_dialog_content = "UAU! Isso é incrível!",
  ui_story_5040_50401001_42_dialog_content = "Mais rápido, Jeriah, mais rápido!",
  ui_story_5040_50401001_43_dialog_content = "Ajuda! Este carro está prestes a decolar!",
  ui_story_5040_50401001_44_dialog_content = "É assim... como é voar?",
  ui_story_5040_50401001_X44_dialog_content = "Parar! Não vá tão rápido... É perigoso!",
  ui_story_5040_50401001_X45_dialog_content = "Meu estômago... não está tão bom...",
  ui_story_5040_50401001_45_dialog_content = "Você tem que continuar voando mais rápido até que você esteja olhando uma tempestade nos olhos para realmente entender o êxtase do vôo!",
  ui_story_5040_50401001_46_dialog_content = "Ahhh!!!",
  ui_story_5040_50401001_47_dialog_content = "Atenção! O barulho do motor atraiu os Eclipsites!",
  ui_story_5040_50401001_48_dialog_content = "Pequena Caelestita, é hora do show!",
  ui_story_5040_50401001_49_dialog_content = "Hã?!",
  ui_story_5040_50401001_50_dialog_content = "Eu não me importo se você usar seus olhos ou suas habilidades psíquicas, diga-me exatamente de onde os Eclipsitas irão atacar.",
  ui_story_5040_50401001_51_dialog_content = "Quando estamos indo tão rápido? Você está dificultando as coisas de propósito!",
  ui_story_5040_50401001_52_dialog_content = "Aaarrgh!",
  ui_story_5040_50401001_53_dialog_content = "Oh! Por trás, lado esquerdo!",
  ui_story_5040_50401001_54_dialog_content = "Ótimo.",
  ui_story_5040_50401001_55_dialog_content = "<color=#e8d9bb>*Screeeee—!*</color>",
  ui_story_5040_50401001_56_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_5040_50401001_57_dialog_content = "Acabamos de enviar um Eclipsite voando!",
  ui_story_5040_50401001_58_dialog_content = "Eu preciso... Oh, não... *Retch*!",
  ui_story_5040_50401001_59_dialog_content = "Não vomite no meu carro, passarinho do Norte.",
  ui_story_5040_50401001_60_dialog_content = "Veja como Tara parece feliz pela primeira vez.",
  ui_story_5040_50401001_61_dialog_content = "R-Sério? Então eu preciso... esperar... por Tara...",
  ui_story_5040_50401001_62_dialog_content = "...",
  ui_story_5040_50401001_63_dialog_content = "Grah!!",
  ui_story_5040_50401001_64_dialog_content = "Mais Eclipsites, bem à frente!",
  ui_story_5040_50401001_65_dialog_content = "Vamos mostrar a eles nossa paixão e dar-lhes um pouco de velocidade.",
  ui_story_5040_50401001_66_dialog_content = "Velocidade máxima!",
  ui_story_5040_50401001_67_dialog_content = "Hahaha, isso é ótimo!",
  ui_story_5040_50401001_68_dialog_content = "Oh não, não, eu vou... *Retch*!",
  ui_story_5040_50401001_69_dialog_content = "Enjoado de uma viagem tão curta? Acho que um pássaro do norte precisa de tempo para se acostumar com o deserto.",
  ui_story_5040_50401001_70_dialog_content = "Considerando que os pássaros do deserto só voam livremente quando levados pelos ventos do deserto.",
  ui_story_5040_50401001_71_dialog_content = "Sim...",
  ui_story_5040_50401001_72_dialog_content = "Eu decidi.",
  ui_story_5040_50401001_73_dialog_content = "Você tem agora? Finalmente.",
  ui_story_5040_50401001_74_dialog_content = "Sim. Na verdade, Adônis, eu...",
  ui_story_5040_50401001_75_dialog_content = "Hã?",
  ui_story_5040_50401001_76_dialog_content = "<color=#e8d9bb>Rumbling—</color>",
  ui_story_5040_50401001_77_dialog_content = "Senhora Jeriah! Eclipsos!",
  ui_story_5040_50401001_78_dialog_content = "Há um monte deles vindo direto para nós!",
  ui_story_5040_50401001_79_dialog_content = "Esses caras com certeza sabem como estragar o clima.",
  ui_story_5040_50401001_80_dialog_content = "Foi você quem ligou o motor antes, Jeriah! O barulho deve tê-los atraído!",
  ui_story_5040_50401001_81_dialog_content = "Vamos continuar nossa conversa depois, passarinhos.",
  ui_story_5040_50401001_82_dialog_content = "Agora precisamos lidar com esses caras, então vamos ter um bom almoço.",
  ui_story_5040_50401001_83_dialog_content = "Suspirar...",
  ui_story_5040_50401001_84_dialog_content = "Vou ajudar!",
  ui_story_5040_50401002_1_dialog_content = "Eles são mais fofos quando estão no chão.",
  ui_story_5040_50401002_2_dialog_content = "Graaahh—",
  ui_story_5040_50401002_3_dialog_content = "Assustado...",
  ui_story_5040_50401002_4_dialog_content = "Não se assuste, ela não vai... Quer dizer, nós já lidamos com os Eclipsites.",
  ui_story_5040_50401002_5_dialog_content = "Jeriah... não é assustador...",
  ui_story_5040_50401002_6_dialog_content = "Jeriah... boa pessoa... Proteja a todos...",
  ui_story_5040_50401002_7_dialog_content = "Mas os Eclipsites destruíram tudo, incluindo todos os nossos suprimentos de comida!",
  ui_story_5040_50401002_8_dialog_content = "Eu estava planejando fazer alguns lanches estilo Umbraton, mas agora tudo virou de cabeça para baixo. Totalmente inutilizável!",
  ui_story_5040_50401002_9_dialog_content = "Oh não, o que devemos fazer?",
  ui_story_5040_50401002_10_dialog_content = "(Jeriah acabou de olhar para Adônis?)",
  ui_story_5040_50401002_11_dialog_content = "Eu tive uma ideia.",
  ui_story_5040_50401002_12_dialog_content = "Claro?",
  ui_story_5040_50401002_13_dialog_content = "Acho que ainda podemos usar isso se apenas limparmos.",
  ui_story_5040_50401002_14_dialog_content = "Não tenho certeza se podemos usá-lo para o que você estava planejando, mas com certeza poderíamos preparar um ensopado.",
  ui_story_5040_50401002_15_dialog_content = "Deixe para mim!",
  ui_story_5040_50401002_16_dialog_content = "(Adonis realmente foi direto ao assunto!)",
  ui_story_5040_50401002_17_dialog_content = "Primeiro, corte os pedaços machucados ou danificados, guardando o que ainda pode ser usado.",
  ui_story_5040_50401002_18_dialog_content = "Em seguida, corte-os em pedaços pequenos e coloque-os em água fervente.",
  ui_story_5040_50401002_19_dialog_content = "Tara, você poderia me passar isso, por favor?",
  ui_story_5040_50401002_20_dialog_content = "Aqui.",
  ui_story_5040_50401002_21_dialog_content = "Obrigado. Agora adicionamos um pouco de sal...",
  ui_story_5040_50401002_22_dialog_content = "O cheiro é bom!",
  ui_story_5040_50401002_23_dialog_content = "Aqui está uma tigela para você, Tara. Sei que você não gosta de rabanete, então já escolhi todos.",
  ui_story_5040_50401002_24_dialog_content = "Valeu...",
  ui_story_5040_50401002_25_dialog_content = "Uma tigela para mim também, por favor! E um para Sable!",
  ui_story_5040_50401002_26_dialog_content = "Tudo bem, tudo bem, espere... Vou preparar o seu.",
  ui_story_5040_50401002_27_dialog_content = "Aqui, eu trouxe as tigelas.",
  ui_story_5040_50401002_28_dialog_content = "Hummm que delícia de almoço!",
  ui_story_5040_50401002_29_dialog_content = "É meio estranho comer ensopado quente no meio do deserto, mas é tão gostoso que nem me importo!",
  ui_story_5040_50401002_30_dialog_content = "Essa é a única coisa que importa!",
  ui_story_5040_50401002_31_dialog_content = "Deixe-me cuidar da lavagem.",
  ui_story_5040_50401002_32_dialog_content = "OK. Vou dar uma olhada rápida na área e me certificar de que não haja mais Eclipsites.",
  ui_story_5040_50401002_33_dialog_content = "Espere, você não estava dizendo algo antes?",
  ui_story_5040_50401002_34_dialog_content = "Quase esqueci, com todo o fiasco do Eclipsite.",
  ui_story_5040_50401002_35_dialog_content = "... Não, não foi nada. Vou patrulhar.",
  ui_story_5040_50401002_36_dialog_content = "Vou dar uma volta com Sable, ver a paisagem.",
  ui_story_5040_50401002_37_dialog_content = "(Estranho... Tara parece estar escondendo algo de mim.)",
  ui_story_5040_50401002_38_dialog_content = "(E mais cedo, Tara me entregou o sal antes mesmo de eu pedir.)",
  ui_story_5040_50401002_39_dialog_content = "(A memória dela está começando a voltar?)",
  ui_story_5040_50401002_40_dialog_content = "(Dito isto, ela tem estado um pouco estranha durante toda a viagem.)",
  ui_story_5040_50401002_41_dialog_content = "(O jeito que ela hesitou agora era muito parecido com o que costumava ser, quando estava prestes a se desculpar por alguma coisa.)",
  ui_story_5040_50401002_42_dialog_content = "(É muito estranho. Será que ela nunca teve amnésia?)",
  ui_story_5040_50401002_43_dialog_content = "(Mas por que ela faria isso? Preciso pensar...)",
  ui_story_5040_50401002_44_dialog_content = "(Ela finge ter perdido a memória, o que me obriga a deixar Northland... será que tudo isso foi um estratagema para me deixar mais corajosa?)",
  ui_story_5040_50401002_45_dialog_content = "(Tara, vou me provar para você. Eu prometo!)",
  ui_story_5040_50401002_46_dialog_content = "Penny por seus pensamentos, Adonis?",
  ui_story_5040_50401002_47_dialog_content = "Não é nada. E aí?",
  ui_story_5040_50401002_48_dialog_content = "Posso ajudar em alguma coisa?",
  ui_story_5040_50401002_49_dialog_content = "Não, está tudo bem. Eu posso me arrumar.",
  ui_story_5040_50401002_50_dialog_content = "Você pode ir fazer outra coisa.",
  ui_story_5040_50401002_51_dialog_content = "Tá bom.",
  ui_story_5040_50401002_52_dialog_content = "(Estou tão entediado comigo mesmo. Queria que Vice e Carleen estivessem aqui agora, sinto falta de conversar com eles.)",
  ui_story_5040_50401002_53_dialog_content = "(Jeriah é um pouco solitária. Ela nunca fica entediada?)",
  ui_story_5040_50401002_54_dialog_content = "(Espero que ela não esteja mais brava. Talvez eu deva ir ver como ela está.)",
  ui_story_5040_50401002_55_dialog_content = "Suspiro, tem sido cansativo, mas...",
  ui_story_5040_50401002_56_dialog_content = "Tara, Adonis... Heheh, são dois passarinhos interessantes.",
  ui_story_5040_50401002_57_dialog_content = "Jerias!",
  ui_story_5040_50401002_58_dialog_content = "Huh? Oh, se não é o jovem celestita! O que te traz aqui?",
  ui_story_5040_50401002_59_dialog_content = "Será que você está sozinho sem seus outros jovens amigos?",
  ui_story_5040_50401002_60_dialog_content = "N-Não! Claro que não!",
  ui_story_5040_50401002_61_dialog_content = "Ou talvez você tenha me achado lamentável, aqui sozinho, e pensou que a companhia seria apreciada?",
  ui_story_5040_50401002_62_dialog_content = "Isso também não...",
  ui_story_5040_50401002_63_dialog_content = "Há algo que eu queria te perguntar.",
  ui_story_5040_50401002_64_dialog_content = "Ah?",
  ui_story_5040_50401002_65_option_content = "Você está sendo completamente honesto?",
  ui_story_5040_50401002_66_dialog_content = "O que te faz dizer isso?",
  ui_story_5040_50401002_67_dialog_content = "Você disse esta manhã que dormiu bem.",
  ui_story_5040_50401002_68_dialog_content = "Mas isso não combina com o que ouvi!",
  ui_story_5040_50401002_69_option_content = "Você está fazendo cara de bravo?",
  ui_story_5040_50401002_70_dialog_content = "Cara corajosa? E o que te levou a essa conclusão?",
  ui_story_5040_50401002_71_dialog_content = "Ouvi dizer que ontem você enviou seu Orador para vasculhar todo o deserto em busca de vermes da areia.",
  ui_story_5040_50401002_72_dialog_content = "...",
  ui_story_5040_50401002_73_dialog_content = "Mesmo se eu fizesse, e daí?",
  ui_story_5040_50401002_74_dialog_content = "Foi imprudente!",
  ui_story_5040_50401002_75_dialog_content = "Usando Luminatics tão intensos por tanto tempo, então levantando tão cedo esta manhã – aposto que você não descansou bem, não é? E agora você ainda vai.",
  ui_story_5040_50401002_76_dialog_content = "Você está exagerando!",
  ui_story_5040_50401002_77_dialog_content = "Mais uma vez... supondo que você esteja certo, e daí?",
  ui_story_5040_50401002_78_dialog_content = "Só estou dizendo que você não precisa se esforçar tanto. Não há problema em se apoiar nos outros de vez em quando.",
  ui_story_5040_50401002_79_dialog_content = "Sou capaz de me virar muito bem no deserto sozinho.",
  ui_story_5040_50401002_80_dialog_content = "Sou perfeitamente capaz de rastrear o verme da areia sozinho, ao mesmo tempo em que concluo as tarefas do Courier Union e entrego correspondências por todo o deserto.",
  ui_story_5040_50401002_81_dialog_content = "Que direito você tem de duvidar de mim?",
  ui_story_5040_50401002_82_dialog_content = "Não estou duvidando de você!",
  ui_story_5040_50401002_83_dialog_content = "Estou bem ciente de que, como celestita, não tenho Luminatics particularmente fortes. Eu também sei que sou bastante inútil lutando contra os Eclipsites.",
  ui_story_5040_50401002_84_dialog_content = "É por isso que conto com a força dos meus companheiros o tempo todo.",
  ui_story_5040_50401002_85_dialog_content = "É porque sou fraco que percebi que ninguém pode sobreviver neste mundo completamente sozinho.",
  ui_story_5040_50401002_86_dialog_content = "É isso que você acha?",
  ui_story_5040_50401002_87_dialog_content = "Por mais forte que você seja, inevitavelmente encontrará problemas além do que pode lidar.",
  ui_story_5040_50401002_88_dialog_content = "Algumas pessoas podem sobreviver, contando com seu próprio crescimento ou trabalho duro...",
  ui_story_5040_50401002_89_dialog_content = "mas alguns problemas não esperam você crescer, ou são demais, mesmo que você trabalhe duro.",
  ui_story_5040_50401002_90_dialog_content = "Minha vida está cheia desses tipos de problemas porque sou um frágil celestita.",
  ui_story_5040_50401002_91_dialog_content = "Você quer dizer que não há vergonha em se apoiar nos outros?",
  ui_story_5040_50401002_92_dialog_content = "Hehe, você realmente é ingênuo.",
  ui_story_5040_50401002_93_dialog_content = "Uma ou duas vezes talvez esteja bem, mas muitas vezes e o número de favores devidos se torna um fardo.",
  ui_story_5040_50401002_94_dialog_content = "Como uma gaiola, esse fardo prende um pássaro, impedindo-o de voar livremente.",
  ui_story_5040_50401002_95_dialog_content = "Imagino que você deva saber como é estar tão sobrecarregado com as coisas que deve aos outros.",
  ui_story_5040_50401002_96_option_content = "Sim.",
  ui_story_5040_50401002_97_dialog_content = "Você está certo, é difícil estar na posição de dever favores às pessoas.",
  ui_story_5040_50401002_98_dialog_content = "Exatamente. Eu odeio a sensação e não tenho desejo de me envolver muito com os outros.",
  ui_story_5040_50401002_99_dialog_content = "Você pode realmente dizer que morar sozinho, mas livre, é uma coisa ruim?",
  ui_story_5040_50401002_100_dialog_content = "É ótimo ter a liberdade de fazer o que quiser sem precisar pensar muito.",
  ui_story_5040_50401002_101_dialog_content = "Mas as interações com os outros não são transacionais.",
  ui_story_5040_50401002_102_option_content = "Não.",
  ui_story_5040_50401002_103_dialog_content = "É verdade que muitas pessoas me ajudaram, mas não sinto que seja um fardo.",
  ui_story_5040_50401002_104_dialog_content = "...!",
  ui_story_5040_50401002_105_dialog_content = "Todo mundo tem seus próprios pontos fortes e fracos, e as pessoas se complementam.",
  ui_story_5040_50401002_106_dialog_content = "Meus companheiros podem ser talentosos em Luminatics, mas posso ver Light Trails. Somos capazes de enfrentar os Eclipsites juntos, lado a lado.",
  ui_story_5040_50401002_107_dialog_content = "Não sei o que você experimentou que o tornou tão avesso a se conectar com as pessoas.",
  ui_story_5040_50401002_108_dialog_content = "Mas os relacionamentos são uma via de mão dupla. Sim, posso aceitar a ajuda de outras pessoas, mas também farei o possível para ajudar os outros.",
  ui_story_5040_50401002_109_dialog_content = "...",
  ui_story_5040_50401002_110_dialog_content = "É assim que você vê, né?",
  ui_story_5040_50401002_111_dialog_content = "Parece que a relação que você tem com seus companheiros é a mesma daqueles dois passarinhos ali.",
  ui_story_5040_50401002_112_dialog_content = "O quê?!",
  ui_story_5040_50401002_113_dialog_content = "Nós somos apenas amigos! Nós não somos tão—",
  ui_story_5040_50401002_114_dialog_content = "Meu, meu, olhe para onde sua mente foi! Eu não disse nada.",
  ui_story_5040_50401002_115_dialog_content = "Você...",
  ui_story_5040_50401002_116_dialog_content = "Olhe para aqueles dois. Eles se complementam muito bem, não é?",
  ui_story_5040_50401002_117_dialog_content = "Voltei. Não há vestígios de Eclipsites na área até agora.",
  ui_story_5040_50401002_118_dialog_content = "Bom trabalho! Aqui, tome um pouco de água e descanse um pouco.",
  ui_story_5040_50401002_119_dialog_content = "Sim...",
  ui_story_5040_50401002_120_dialog_content = "Tara é extrovertida e alegre, com muita experiência vivendo na selva e lidando com Eclipsites.",
  ui_story_5040_50401002_121_dialog_content = "Adonis é mais logístico e paciente o suficiente para lidar com todo o trabalho que Tara acha tedioso e no qual não é muito bom.",
  ui_story_5040_50401002_122_dialog_content = "Isso mesmo. Eu nunca teria pensado que haveria uma pessoa que pudesse se dar bem com um membro da Rediesel Wrench assim.",
  ui_story_5040_50401002_123_dialog_content = "Você não gosta das Chaves Rediesel?",
  ui_story_5040_50401002_124_dialog_content = "Não gostou? Ha. Talvez.",
  ui_story_5040_50401002_125_dialog_content = "No que me diz respeito, eles não passam de um bando de bandidos míopes e sem cérebro.",
  ui_story_5040_50401002_126_dialog_content = "Eles vivem uma existência tão hedonista, não se importando com nada além de se divertir.",
  ui_story_5040_50401002_127_dialog_content = "Mas sabe, foi Sinsa quem me contou sobre você usar seu Orador para vasculhar todo o deserto em busca de vermes da areia.",
  ui_story_5040_50401002_128_dialog_content = "O quê?",
  ui_story_5040_50401002_129_dialog_content = "Ontem, depois que você me fez sair, entrei em contato com Sinsa para perguntar sobre o verme da areia rosa.",
  ui_story_5040_50401002_130_dialog_content = "Ele me disse que alguém na Rediesel Wrench viu você usando seu alto-falante para procurar minhocas.",
  ui_story_5040_50401002_131_dialog_content = "Todos estavam preocupados com você.",
  ui_story_5040_50401002_132_dialog_content = "Isso porque sou um dos poucos mensageiros no deserto que pode entregar as informações de que precisam.",
  ui_story_5040_50401002_133_dialog_content = "Não é desse jeito!",
  ui_story_5040_50401002_134_dialog_content = "Tudo bem, acho que já descansei o suficiente.",
  ui_story_5040_50401002_135_dialog_content = "Ei, Jeriah!",
  ui_story_5040_50401002_136_dialog_content = "Junte suas coisas. É hora de sair.",
  ui_story_5040_50401002_137_dialog_content = "Sério, Jeriah. Apenas vá embora e me deixe esperando, por que você não...",
  ui_story_5040_50401002_138_dialog_content = "Ela tem o hábito de viver em negação e finge que está tudo bem?",
  ui_story_5040_50401101_1_dialog_content = "Como vão os preparativos, passarinhos?",
  ui_story_5040_50401101_2_dialog_content = "Estou com tudo embalado e pronto para ir a qualquer hora.",
  ui_story_5040_50401101_3_dialog_content = "Estou pronto também.",
  ui_story_5040_50401101_4_dialog_content = "O fogo foi apagado e temos todos os nossos pertences.",
  ui_story_5040_50401101_5_dialog_content = "Você é tão prudente, Kya!",
  ui_story_5040_50401101_6_dialog_content = "Obrigado! Esmeralda me ensinou bem.",
  ui_story_5040_50401101_7_dialog_content = "Quem é Esmeralda?",
  ui_story_5040_50401101_8_dialog_content = "Ela foi minha veterana no Courier Union, embora esteja aposentada agora.",
  ui_story_5040_50401101_9_dialog_content = "Antes de me tornar um mensageiro, era Emerald quem entregava cartas para minha cidade natal, Faar, e outras aldeias próximas.",
  ui_story_5040_50401101_10_dialog_content = "Minha cidade natal é muito remota, então quase nunca tivemos contato com o mundo exterior.",
  ui_story_5040_50401101_11_dialog_content = "Nossa única maneira de saber o que estava acontecendo era através das cartas que Emerald trouxe.",
  ui_story_5040_50401101_12_dialog_content = "Ela deve ter sido uma pessoa muito responsável.",
  ui_story_5040_50401101_13_dialog_content = "Oh sim! Foi por causa dela que me inspirei a ser entregadora!",
  ui_story_5040_50401101_14_dialog_content = "Eu sei em primeira mão como é difícil para as pessoas que vivem em lugares remotos se conectarem com o mundo exterior, então eu queria me tornar uma ponte para os outros.",
  ui_story_5040_50401101_15_dialog_content = "Isso é incrível!",
  ui_story_5040_50401101_16_dialog_content = "Hehe, ainda tenho espaço para melhorias.",
  ui_story_5040_50401101_17_dialog_content = "Mesmo com todas as notas que Emerald me deu, eu ainda estrago as coisas...",
  ui_story_5040_50401101_18_dialog_content = "Mesmo que eu siga todos os conselhos de suas anotações com precisão, as coisas de alguma forma sempre saem de forma diferente das minhas expectativas.",
  ui_story_5040_50401101_19_dialog_content = "Você não precisa sempre seguir instruções como essa para um tee. Às vezes, é preciso improvisar e se adaptar à situação.",
  ui_story_5040_50401101_20_dialog_content = "Eh, eu não sou muito bom nisso.",
  ui_story_5040_50401101_21_dialog_content = "Graaoooooohhh!!",
  ui_story_5040_50401101_22_dialog_content = "Você ouviu isso? Algo distante?",
  ui_story_5040_50401101_23_dialog_content = "Isso...",
  ui_story_5040_50401101_24_dialog_content = "Graah! Rugido!",
  ui_story_5040_50401101_25_dialog_content = "Eclipsitos! Todos, cuidado!",
  ui_story_5040_50401101_26_dialog_content = "Tantos deles!",
  ui_story_5040_50401101_27_dialog_content = "De onde eles vieram desta vez?!",
  ui_story_5040_50401101_28_dialog_content = "Outro grupo? Que estranho...",
  ui_story_5040_50401101_29_dialog_content = "Vamos apenas lidar com eles primeiro. Boa sorte e seja cauteloso.",
  ui_story_5040_50401102_1_dialog_content = "Graaahh—",
  ui_story_5040_50401102_2_dialog_content = "Estranho, eles não costumam desistir tão facilmente. No entanto, eles simplesmente fugiram...",
  ui_story_5040_50401102_3_dialog_content = "Esta não é uma área onde os Eclipsites costumam aparecer.",
  ui_story_5040_50401102_4_dialog_content = "Mas este foi o segundo grupo que encontramos nos últimos dias. Isso não é normal.",
  ui_story_5040_50401102_5_dialog_content = "Eles estão... correndo...",
  ui_story_5040_50401102_6_dialog_content = "O que você disse?",
  ui_story_5040_50401102_7_dialog_content = "Sable disse que eles pareciam estar fugindo, se escondendo de alguma coisa?",
  ui_story_5040_50401102_8_dialog_content = "<color=#e8d9bb>Estrondo...</color>",
  ui_story_5040_50401102_9_dialog_content = "O chão está tremendo?",
  ui_story_5040_50401102_10_dialog_content = "Fora do caminho, todos. Algo está vindo!",
  ui_story_5040_50401102_11_dialog_content = "Cuidado, Tara!",
  ui_story_5040_50401102_12_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5040_50401102_13_dialog_content = "<size=50>Roooooar!</size>",
  ui_story_5040_50401102_14_dialog_content = "Uau!! I-Isso é mesmo um verme da areia rosa?!",
  ui_story_5040_50401102_15_dialog_content = "Eu pensei que deveria estar indo para a parte mais profunda do deserto! Isso é, uh, bem longe daqui!",
  ui_story_5040_50401102_16_dialog_content = "Há uma outra explicação para sua aparência... Pode ser a hora da alimentação.",
  ui_story_5040_50401102_17_dialog_content = "Você está dizendo que estava tentando se alimentar daqueles Eclipsites?",
  ui_story_5040_50401102_18_dialog_content = "Sim... e parece que agora estamos no cardápio.",
  ui_story_5040_50401102_19_dialog_content = "<size=50>Rooaaaar!</size>",
  ui_story_5040_50401102_20_dialog_content = "Por que a pressa, garotão?",
  ui_story_5040_50401102_21_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5040_50401102_22_dialog_content = "Isso é alguma armadura!",
  ui_story_5040_50401102_23_dialog_content = "Heheh... Acho que essas escamas rosas são bem mais fortes do que parecem.",
  ui_story_5040_50401102_24_dialog_content = "Mas não importa o que aconteça, ainda é apenas um verme da areia.",
  ui_story_5040_50401102_25_dialog_content = "Vamos, alto-falantes!",
  ui_story_5040_50401102_26_dialog_content = "Roaaaar—",
  ui_story_5040_50401102_27_dialog_content = "Olha, está funcionando!",
  ui_story_5040_50401102_28_dialog_content = "Eu também ajudo!",
  ui_story_5040_50401102_29_dialog_content = "Espera, Tara! Não se aproxime muito dele!",
  ui_story_5040_50401102_30_dialog_content = "Minhas balas não vão perfurar as escamas desse verme da areia se eu estiver muito longe.",
  ui_story_5040_50401102_31_dialog_content = "Além disso, não há nada a temer. Rosa ou não, é só um verme da areia!",
  ui_story_5040_50401102_32_dialog_content = "Rrr... Rugido...!",
  ui_story_5040_50401102_33_dialog_content = "Em seguida... um tiro na cabeça!",
  ui_story_5040_50401102_34_dialog_content = "*Rugido*",
  ui_story_5040_50401102_35_dialog_content = "Hã?!",
  ui_story_5040_50401102_36_dialog_content = "I-Ele pegou a arma de Tara! Ele fez isso intencionalmente?!",
  ui_story_5040_50401102_37_dialog_content = "Solte!",
  ui_story_5040_50401102_38_dialog_content = "Como um verme da areia pode ter esse tipo de consciência? Algo está errado...",
  ui_story_5040_50401102_39_dialog_content = "Não seremos capazes de derrotá-lo rapidamente. Não com nossa força atual.",
  ui_story_5040_50401102_40_dialog_content = "É tentar nos desgastar arrastando a luta!",
  ui_story_5040_50401102_41_dialog_content = "Não podemos deixar isso acontecer. Grimório, libere seu poder!",
  ui_story_5040_50401102_42_dialog_content = "Rugido-!",
  ui_story_5040_50401102_43_dialog_content = "O-Onde foi?!",
  ui_story_5040_50401102_44_dialog_content = "Está se enterrando na areia! Cuidado onde pisa!",
  ui_story_5040_50401102_45_dialog_content = "<size=50>Roooorrr!!!</size>",
  ui_story_5040_50401102_46_dialog_content = "<color=#e8d9bb>Whoosh - Slam!</color>",
  ui_story_5040_50401102_47_dialog_content = "Agh-!",
  ui_story_5040_50401102_48_dialog_content = "Ele arremessou Tara nas dunas ali!",
  ui_story_5040_50401102_49_dialog_content = "Tara!!!",
  ui_story_5040_50401102_50_dialog_content = "Estou bem!",
  ui_story_5040_50401102_51_dialog_content = "A areia aqui é solta; está usando isso para nos enterrar e nos emboscar.",
  ui_story_5040_50401102_52_dialog_content = "Todos no carro!",
  ui_story_5040_50401102_53_dialog_content = "Há uma parte do deserto onde o solo é principalmente de pedra. Se conseguirmos chegar lá, o verme da areia não conseguirá nos emboscar!",
  ui_story_5040_50401102_54_dialog_content = "Entendi! Vamos Sable, vamos para o carro!",
  ui_story_5040_50401102_55_dialog_content = "Estamos recuando, Adonis!",
  ui_story_5040_50401102_56_dialog_content = "Got—Cuidado, Tara!",
  ui_story_5040_50401102_57_dialog_content = "Roaaaar—",
  ui_story_5040_50401102_58_dialog_content = "Urg-!",
  ui_story_5040_50401102_59_dialog_content = "Tara!!",
  ui_story_5040_50401102_60_dialog_content = "Ai...",
  ui_story_5040_50401102_61_dialog_content = "Oh não, a perna de Tara está machucada!",
  ui_story_5040_50401102_62_dialog_content = "*Rugido*",
  ui_story_5040_50401102_63_dialog_content = "(Droga, não vamos conseguir. Como posso impedir...)",
  ui_story_5040_50401102_64_dialog_content = "Deixe Tara em paz, sua lagarta gorda e feia!",
  ui_story_5040_50401102_65_dialog_content = "Roaaaar—",
  ui_story_5040_50401102_66_dialog_content = "Aqui, seu verme crescido demais! Venha me pegar!",
  ui_story_5040_50401102_67_dialog_content = "Adonis chamou a atenção do verme da areia!",
  ui_story_5040_50401102_68_dialog_content = "Não acredito que aquele ataque fraco dele funcionou!",
  ui_story_5040_50401102_69_dialog_content = "Olhe atentamente para o local onde Adonis atingiu o verme da areia... Acho que é uma ferida que não se recuperou totalmente.",
  ui_story_5040_50401102_70_dialog_content = "Isso deve ser de sua luta com Sinsa e os outros!",
  ui_story_5040_50401102_71_dialog_content = "*Rugido*",
  ui_story_5040_50401102_72_dialog_content = "Caramba!!!",
  ui_story_5040_50401102_73_dialog_content = "O verme da areia está atrás de Adonis agora, está se afastando de Tara!",
  ui_story_5040_50401102_74_dialog_content = "Agora é sua chance, Jeriah!",
  ui_story_5040_50401102_75_dialog_content = "Hehe... eu sei.",
  ui_story_5040_50401102_76_dialog_content = "Voe, Falcão! Mire nessa ferida!",
  ui_story_5040_50401102_77_dialog_content = "Rugido? Roaaarrr!",
  ui_story_5040_50401102_78_dialog_content = "Agora!",
  ui_story_5040_50401102_79_dialog_content = "Você está bem, Tara?",
  ui_story_5040_50401102_80_dialog_content = "Estou bem! Vá ajudar Adônis!",
  ui_story_5040_50401102_81_dialog_content = "Entendido!",
  ui_story_5040_50401102_82_dialog_content = "Eu... ajudarei... também!",
  ui_story_5040_50401102_83_dialog_content = "<color=#e8d9bb>Whizz—!</color>",
  ui_story_5040_50401102_84_dialog_content = "Roooorrr!!!",
  ui_story_5040_50401102_85_dialog_content = "Eu... estou salvo!",
  ui_story_5040_50401102_86_dialog_content = "Fique atrás de nós e não perca o equilíbrio!",
  ui_story_5040_50401102_87_dialog_content = "*Rugido*",
  ui_story_5040_50401102_88_dialog_content = "<color=#e8d9bb>Fwooosh!!!</color>",
  ui_story_5040_50401102_89_dialog_content = "Uau! De onde veio essa tempestade de areia?!",
  ui_story_5040_50401102_90_dialog_content = "Não é uma tempestade de areia. O verme da areia está jogando areia no ar.",
  ui_story_5040_50401102_91_dialog_content = "Ele está tentando proteger seus pontos fracos obscurecendo nossa visão!",
  ui_story_5040_50401102_92_dialog_content = "Oh não... Perdi Kya e os outros de vista!",
  ui_story_5040_50401102_93_dialog_content = "Tara! Onde você está?!",
  ui_story_5040_50401102_94_dialog_content = "Aqui!",
  ui_story_5040_50401102_95_dialog_content = "Estamos a caminho!",
  ui_story_5040_50401102_96_dialog_content = "<color=#e8d9bb>Estrondo...</color>",
  ui_story_5040_50401102_97_dialog_content = "Ahhh!!!",
  ui_story_5040_50401102_98_dialog_content = "A-Adônis?!",
  ui_story_5040_50401102_99_dialog_content = "Eu vou trazê-los de volta!",
  ui_story_5040_50401102_100_dialog_content = "<size=50>Roooaaar!!!</size>",
  ui_story_5040_50401102_101_dialog_content = "Hã?!",
  ui_story_5040_50401102_102_dialog_content = "Jeriah, está fugindo!",
  ui_story_5040_50401102_103_dialog_content = "Não no meu turno!",
  ui_story_5040_50401102_104_dialog_content = "<size=50>Roooorrr!!!</size>",
  ui_story_5040_50401102_105_dialog_content = "Eca!!!",
  ui_story_5040_50401102_106_dialog_content = "PlayerName!",
  ui_story_5040_50401102_107_dialog_content = "Ai...",
  ui_story_5040_50401201_1_dialog_content = "Sair dessa, PlayerName!",
  ui_story_5040_50401201_2_dialog_content = "Nossa... minha cabeça...",
  ui_story_5040_50401201_3_dialog_content = "*Cuspindo* Ugh, minha boca está cheia de areia!",
  ui_story_5040_50401201_4_dialog_content = "Ufa... Graças a Deus você está bem. Você está ferido em algum lugar?",
  ui_story_5040_50401201_5_dialog_content = "*Tosse* Não, acho que estou bem. Minha cabeça dói, só isso...",
  ui_story_5040_50401201_6_dialog_content = "O verme da areia fez você voar de cabeça para dentro de uma duna... Quando vi seu corpo meio enterrado saindo da areia, pensei que você tivesse se ferido gravemente.",
  ui_story_5040_50401201_7_dialog_content = "Não foi fácil para Tara e eu tirá-lo de lá, pequeno Caelestita... você realmente deveria nos agradecer.",
  ui_story_5040_50401201_8_dialog_content = "Th-Obrigado...",
  ui_story_5040_50401201_9_dialog_content = "Espere, onde estão os outros? Eles estão bem?",
  ui_story_5040_50401201_10_dialog_content = "Corremos para ajudá-lo assim que vimos suas pernas saindo da areia.",
  ui_story_5040_50401201_11_dialog_content = "Graças àquela terrível tempestade de areia, perdemos o verme da areia e nos separamos de Adonis e dos outros.",
  ui_story_5040_50401201_12_dialog_content = "Vou tentar localizá-los com meus poderes!",
  ui_story_5040_50401201_13_option_content = "Mindlink!",
  ui_story_5040_50401201_14_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5040_50401201_15_dialog_content = "Não sinto nenhum vestígio deles por perto...",
  ui_story_5040_50401201_16_dialog_content = "Está bem. Meus Oradores estão procurando por eles enquanto falamos. A menos que eles tenham problemas, devemos ter notícias deles em breve.",
  ui_story_5040_50401201_17_dialog_content = "Mesmo que estivessem enterrados no subsolo, Hawk pode detectar até os menores movimentos na superfície da areia e encontrá-los.",
  ui_story_5040_50401201_18_dialog_content = "Adônis... Por favor, fique bem...",
  ui_story_5040_50401201_19_dialog_content = "Shreee—!",
  ui_story_5040_50401201_20_dialog_content = "Meu pássaro tem novidades para nós.",
  ui_story_5040_50401201_21_dialog_content = "Bem? Você os encontrou?",
  ui_story_5040_50401201_22_dialog_content = "Shreee—",
  ui_story_5040_50401201_23_dialog_content = "... Nenhum sinal deles?",
  ui_story_5040_50401201_24_dialog_content = "Tente novamente e expanda seu raio de pesquisa desta vez. Não se preocupe com a quantidade de Lumina que vai gastar.",
  ui_story_5040_50401201_25_dialog_content = "Vai!",
  ui_story_5040_50401201_26_dialog_content = "Shreee—!",
  ui_story_5040_50401201_27_dialog_content = "Vou dar uma olhada também.",
  ui_story_5040_50401201_28_dialog_content = "Mas sua perna ainda está machucada!",
  ui_story_5040_50401201_29_dialog_content = "Eu não posso simplesmente sentar aqui e não fazer nada!",
  ui_story_5040_50401201_30_dialog_content = "Você só estaria desperdiçando sua energia. Se os olhos de um falcão não conseguem ver algo do ar, o que faz você pensar que seus olhos podem fazer melhor?",
  ui_story_5040_50401201_31_dialog_content = "Sua melhor opção é descansar aqui, para não agravar seus ferimentos.",
  ui_story_5040_50401201_32_dialog_content = "...",
  ui_story_5040_50401201_33_dialog_content = "Se não fosse por eu fingir perda de memória, Adonis nem estaria nessa confusão, estaria?",
  ui_story_5040_50401201_34_dialog_content = "... Para ser sincero, descobri há muito tempo, por meio de minha habilidade, que você estava fingindo.",
  ui_story_5040_50401201_35_dialog_content = "É que pensei que você tinha seus motivos, então não quis intervir.",
  ui_story_5040_50401201_36_dialog_content = "Sim...",
  ui_story_5040_50401201_37_dialog_content = "Mas, pensando bem, deixar você fazer o que quiser acabou colocando todos nós em perigo!",
  ui_story_5040_50401201_38_dialog_content = "O que diabos você estava pensando? Como você pôde fazer isso com todo mundo?!",
  ui_story_5040_50401201_39_dialog_content = "Achei... Achei que ajudaria Adonis a superar o medo do mundo exterior.",
  ui_story_5040_50401201_40_dialog_content = "Ele sempre relutou em deixar para trás sua vida em Northland... Então, eu esperava que essas provações lhe dessem o empurrão de que precisava.",
  ui_story_5040_50401201_41_option_content = "Isso é completamente insano!",
  ui_story_5040_50401201_42_dialog_content = "Não importa o resto de nós. Adonis não é a pessoa mais importante para você?",
  ui_story_5040_50401201_43_dialog_content = "Qual é o sentido de completar todas essas provações, se isso significa colocar o homem que você ama em perigo?!",
  ui_story_5040_50401201_44_dialog_content = "Agora ele está longe de ser encontrado, junto com Kya e Sable! Isso não é uma piada, Tara!",
  ui_story_5040_50401201_45_dialog_content = "Sinto muito...",
  ui_story_5040_50401201_46_option_content = "... Eu sei de onde você vem.",
  ui_story_5040_50401201_47_dialog_content = "Às vezes, quando não sou corajoso o suficiente para fazer algo, preciso que os outros me empurrem para frente.",
  ui_story_5040_50401201_48_dialog_content = "Seu coração estava no lugar certo, mas não posso dizer que concordo com seus métodos.",
  ui_story_5040_50401201_49_dialog_content = "Se a pessoa de quem você gosta não é corajosa o suficiente para enfrentar um desafio, você deve apoiá-la.",
  ui_story_5040_50401201_50_dialog_content = "Você deve usar suas palavras e ações para ajudá-los a encontrar coragem e enfrentar esses desafios juntos.",
  ui_story_5040_50401201_51_dialog_content = "Eu estava errado... me desculpe. Eu não deveria ter sido tão imprudente...",
  ui_story_5040_50401201_52_dialog_content = "Eu pensei que o verme da areia rosa seria como qualquer outro verme da areia, apenas uma cor diferente.",
  ui_story_5040_50401201_53_dialog_content = "Já lidei com muitos vermes da areia comuns sem problemas. Achei que poderia proteger Adonis sozinha.",
  ui_story_5040_50401201_54_dialog_content = "Eu não tinha ideia de que aquela coisa seria tão astuta e poderosa...",
  ui_story_5040_50401201_55_dialog_content = "Eu sou parcialmente culpado por isso.",
  ui_story_5040_50401201_56_dialog_content = "Eu deveria ter percebido que, para um verme da areia tão especial sobreviver às duras realidades do deserto por tanto tempo, ele deve ser muito mais tenaz do que o resto.",
  ui_story_5040_50401201_57_dialog_content = "No final das contas, fui eu quem apresentou este julgamento, colocando todos em perigo. Vou assumir a responsabilidade por isso e fazer tudo o que puder para resgatá-los.",
  ui_story_5040_50401201_58_dialog_content = "Suspiro, vamos tentar encontrar os outros primeiro.",
  ui_story_5040_50401201_59_dialog_content = "Espero que estejam bem...",
  ui_story_5040_50401201_60_dialog_content = "(Isso é preocupante...)",
  ui_story_5040_50401201_61_dialog_content = "(O que devemos fazer se nem mesmo o Orador de Jeriah pode encontrá-los...?)",
  ui_story_5040_50401201_62_dialog_content = "Meu pássaro está de volta.",
  ui_story_5040_50401201_63_dialog_content = "Huh? Onde?",
  ui_story_5040_50401201_64_dialog_content = "Falcão, aqui!",
  ui_story_5040_50401201_65_dialog_content = "Kree—!",
  ui_story_5040_50401201_66_dialog_content = "Graaah...",
  ui_story_5040_50401201_67_dialog_content = "E parece ter trazido algo extra...",
  ui_story_5040_50401201_68_dialog_content = "Vamos cuidar desses Eclipsitos primeiro!",
  ui_story_5040_50401201_69_dialog_content = "Deixa-me ajudar. Um arranhão desses... não é nada para quem cresceu no Deserto de Rediesel!",
  ui_story_5040_50401202_1_dialog_content = "*COF cof*",
  ui_story_5040_50401202_2_dialog_content = "Nossa, eu não esperava me sentir tão cansada.",
  ui_story_5040_50401202_3_dialog_content = "Você acha que aqueles Eclipsites estão fugindo do verme da areia?",
  ui_story_5040_50401202_4_dialog_content = "Não, eles não parecem estar em pânico ou procurando abrigo...",
  ui_story_5040_50401202_5_dialog_content = "Talvez eles tenham notado quanto Lumina Hawk estava gastando para procurar os outros e viram uma oportunidade perfeita para nos emboscar?",
  ui_story_5040_50401202_6_dialog_content = "Agora, meu passarinho... Encontrou alguma coisa?",
  ui_story_5040_50401202_7_dialog_content = "Shree!",
  ui_story_5040_50401202_8_dialog_content = "Nada ainda...?",
  ui_story_5040_50401202_9_dialog_content = "Não há sinal do verme da areia por perto. Provavelmente está se movendo usando túneis subterrâneos que criou anteriormente.",
  ui_story_5040_50401202_10_dialog_content = "Se for esse o caso, também é muito provável que tenha carregado Adonis, Kya e Sable junto com ele...",
  ui_story_5040_50401202_11_dialog_content = "Isso significa que eles estão em sério perigo!",
  ui_story_5040_50401202_12_dialog_content = "Não há como aqueles três lidarem com aquele verme da areia sozinhos! Sem falar que eles podem se perder nesses túneis!",
  ui_story_5040_50401202_13_dialog_content = "Precisamos encontrá-los imediatamente!",
  ui_story_5040_50401202_14_dialog_content = "Não se preocupe. Posso capacitar Hawk para procurar em todo o deserto.",
  ui_story_5040_50401202_15_dialog_content = "Haw—*Tosse*—Hawk!",
  ui_story_5040_50401202_16_dialog_content = "Pare com isso, Jeriah!",
  ui_story_5040_50401202_17_dialog_content = "Você parece tão pálido, você está claramente no seu limite!",
  ui_story_5040_50401202_18_dialog_content = "Heheh... Não me subestime, pequena Celestita. Não sou tão delicada.",
  ui_story_5040_50401202_19_dialog_content = "Depois de todos esses anos, consegui superar todos os problemas sozinho.",
  ui_story_5040_50401202_20_dialog_content = "Desta vez não haverá dif—",
  ui_story_5040_50401202_21_dialog_content = "Devemos pedir ajuda à Rediesel Wrench.",
  ui_story_5040_50401202_22_dialog_content = "O quê?",
  ui_story_5040_50401202_23_dialog_content = "Voltemos a Soroz. Vou usar os comunicadores para entrar em contato com Sinsa e o resto da Rediesel Wrench, para que eles possam nos ajudar na busca.",
  ui_story_5040_50401202_24_dialog_content = "Se não conseguirmos encontrá-los apenas nós três, teremos que mobilizar todos em todo o deserto!",
  ui_story_5040_50401202_25_dialog_content = "Você é um membro sênior do Courier Union! Tenho certeza que todos estariam dispostos a ajudar se alguém do seu status pedisse!",
  ui_story_5040_50401202_26_dialog_content = "\"Alguém do meu status\"? Quanta ingenuidade sua, hehe...",
  ui_story_5040_50401202_27_dialog_content = "Sempre fui um profissional. Não ajudo os outros e não espero ajuda dos outros.",
  ui_story_5040_50401202_28_dialog_content = "Além disso, tenho certeza de que ficariam muito mais felizes com outro mensageiro muito mais responsável.",
  ui_story_5040_50401202_29_dialog_content = "Você não é alguém que pode ser substituído!",
  ui_story_5040_50401202_30_dialog_content = "Todos no Deserto Rediesel sabem que os correios são as pontes que nos conectam!",
  ui_story_5040_50401202_31_dialog_content = "A Courier Union foi a única razão pela qual Adonis e eu conseguimos manter contato durante todo esse tempo!",
  ui_story_5040_50401202_32_dialog_content = "Isso mesmo. As relações entre as pessoas nunca são tão simples, Jeriah.",
  ui_story_5040_50401202_33_dialog_content = "Ao entregar as cartas de todos, tenho certeza de que você fez conexões com pessoas mais profundas do que você imagina.",
  ui_story_5040_50401202_34_dialog_content = "...",
  ui_story_5040_50401202_35_dialog_content = "O que devo fazer com vocês dois...",
  ui_story_5040_50401202_36_dialog_content = "Multar. Faremos do seu jeito, e pedimos ajuda.",
  ui_story_5040_50401202_37_dialog_content = "Mas não tenha muitas esperanças. A Rediesel Wrench pode não querer ajudar alguém que só pensa nela quando está com problemas.",
  ui_story_5040_50401202_38_dialog_content = "Nunca saberemos a menos que tentemos, certo?",
  ui_story_5040_50401202_39_dialog_content = "Vamos voltar para Soroz!",
  ui_story_5040_50401202_40_dialog_content = "Não seja tão apressado. Posso alcançá-los mais rápido do que seus comunicadores.",
  ui_story_5040_50401202_41_dialog_content = "Hã?",
  ui_story_5040_50401202_42_dialog_content = "É um talento meu, que vai queimar quase todo o meu Lumina. Depois de usá-lo, não poderei fazê-lo novamente por muito tempo ...",
  ui_story_5040_50401202_43_dialog_content = "mas acredito que agora é o momento perfeito para usá-lo.",
  ui_story_5040_50401202_44_dialog_content = "Espere, você está me dizendo que tem algum tipo de ataque final na manga?",
  ui_story_5040_50401202_45_dialog_content = "Não é um ataque, não.",
  ui_story_5040_50401202_46_dialog_content = "Tudo o que ele faz é permitir que eu estabeleça rapidamente uma conexão com meus pequenos passarinhos da Courier Union, portanto, destina-se apenas a emergências.",
  ui_story_5040_50401202_47_dialog_content = "Ao ativar essa habilidade, posso usar Hawk para pedir ajuda. Desta forma, podemos alcançar todos os membros da Rediesel Wrench na área.",
  ui_story_5040_50401202_48_dialog_content = "Você já fez isso antes?",
  ui_story_5040_50401202_49_dialog_content = "Não! Esta é a minha primeira tentativa.",
  ui_story_5040_50401202_50_dialog_content = "Venha, meu doce passarinho! Leve minha mensagem a todos que quiserem ouvir!",
  ui_story_5040_50401202_51_dialog_content = "Shree!",
  ui_story_5040_50401202_52_dialog_content = "Vai!",
  ui_story_5040_50401202_53_dialog_content = "Shreee-!",
  ui_story_5040_50401202_54_dialog_content = "Volte para casa com boas notícias, meu lindo passarinho...",
  ui_story_5040_50401202_55_dialog_content = "<color=#e8d9bb>Alguns minutos depois...</color>",
  ui_story_5040_50401202_56_dialog_content = "Ainda sem resposta...",
  ui_story_5040_50401202_57_dialog_content = "Hawk pode ser rápido, mas ainda precisa de tempo para entregar minha mensagem. Apenas seja paciente.",
  ui_story_5040_50401202_58_dialog_content = "... Olhar! Aí está!",
  ui_story_5040_50401202_59_dialog_content = "Sim! É o Falcão de Jeriah...",
  ui_story_5040_50401202_60_dialog_content = "Shreee—!",
  ui_story_5040_50401202_61_dialog_content = "Parece que está carregando algo em suas garras... L-Cuidado! Está jogando coisas em nós!",
  ui_story_5040_50401202_62_dialog_content = "São estas... cartas?",
  ui_story_5040_50401202_63_dialog_content = "Eles são! Olhe para todas essas letras, caindo do céu como neve...",
  ui_story_5040_50401202_64_dialog_content = "Existem muitos deles. Acho que há notas dentro deles.",
  ui_story_5040_50401202_65_dialog_content = "Uau, o que isso significa? Eu não posso fazer cara ou coroa disso!",
  ui_story_5040_50401202_66_dialog_content = "Deixe-me ver.",
  ui_story_5040_50401202_67_dialog_content = "Oh, é apenas uma mensagem codificada da Rediesel Wrench. Diz que ninguém viu nossos amigos ou aquele verme da areia nas partes noroeste do deserto.",
  ui_story_5040_50401202_68_dialog_content = "Nem todos no Rediesel Wrench sabem ler ou escrever, então usamos mensagens como essas para nos comunicarmos na maioria das vezes.",
  ui_story_5040_50401202_69_dialog_content = "Realmente funcionou...",
  ui_story_5040_50401202_70_dialog_content = "Shree!",
  ui_story_5040_50401202_71_dialog_content = "Você está me dizendo que essas cartas incluem todos os locais onde a Chave Inglesa Rediesel avistou o verme da areia rosa?!",
  ui_story_5040_50401202_72_dialog_content = "Então, se seguirmos suas anotações, poderemos encontrar o verme da areia e nossos amigos, certo?",
  ui_story_5040_50401202_73_dialog_content = "Certo...",
  ui_story_5040_50401202_74_dialog_content = "Então, o que estamos esperando? Vamos começar a ler essas cartas!",
  ui_story_5040_50401202_75_dialog_content = "Nada perto de Tail Street ou Red-Eye Gorge.",
  ui_story_5040_50401202_76_dialog_content = "Nada na direção da Federação Illumina também... Hmm?",
  ui_story_5040_50401202_77_dialog_content = "Ah! Encontrei você!",
  ui_story_5040_50401202_78_dialog_content = "Onde?!",
  ui_story_5040_50401202_79_dialog_content = "Bem ao sul, perto de um oásis no meio do deserto.",
  ui_story_5040_50401202_80_dialog_content = "O lugar está repleto de vermes da areia, e o Rediesel Wrench ocasionalmente vai lá para caçá-los.",
  ui_story_5040_50401202_81_dialog_content = "Aparentemente, um de seus membros viu um verme da areia rosa emergir do chão não muito tempo atrás!",
  ui_story_5040_50401202_82_dialog_content = "Então vamos em frente! Se nos apressarmos, talvez consigamos rastrear Adonis!",
  ui_story_5040_50401202_83_dialog_content = "Entre!",
  ui_story_5040_50401202_84_dialog_content = "<color=#e8d9bb>Vroom—</color>",
  ui_story_5040_50401202_85_dialog_content = "Bwaaaa!!!",
  ui_story_5040_50401202_86_dialog_content = "JJ-Jeriah! Desacelere um pouco!!",
  ui_story_5040_50401202_87_dialog_content = "<size=45>O que é que foi isso?</size>",
  ui_story_5040_50401202_88_dialog_content = "<size=45>Não consigo te ouvir!!</size>",
  ui_story_5040_50401202_89_option_content = "Calma, Jeriaaaaah!!!",
  ui_story_5040_50401202_90_dialog_content = "Desacelerar? Não temos tempo para desacelerar! Vidas estão em jogo!",
  ui_story_5040_50401202_91_option_content = "Não ultrapasse o limite de velocidade!!!!",
  ui_story_5040_50401202_92_dialog_content = "Hahaha! Você tem muito senso de humor, sabia?",
  ui_story_5040_50401202_93_dialog_content = "Limites de velocidade? No deserto?",
  ui_story_5040_50401202_94_dialog_content = "Graaaah-!",
  ui_story_5040_50401202_95_dialog_content = "Estamos sendo perseguidos por Eclipsites!",
  ui_story_5040_50401202_96_dialog_content = "Então teremos que perdê-los!",
  ui_story_5040_50401202_97_dialog_content = "Aguente firme, pequena Celestita! Vamos ainda mais rápido agora!",
  ui_story_5040_50401202_98_dialog_content = "<color=#e8d9bb>Vroooom—!!!</color>",
  ui_story_5040_50401301_1_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5040_50401301_2_dialog_content = "Ahhhhhh—!",
  ui_story_5040_50401301_3_dialog_content = "Isso foi lindo!",
  ui_story_5040_50401301_4_dialog_content = "Você provavelmente poderia dar aos melhores pilotos do Rediesel Wrench uma corrida pelo seu dinheiro!",
  ui_story_5040_50401301_5_dialog_content = "Oh sério? Eu vou aceitar isso como um elogio.",
  ui_story_5040_50401301_6_dialog_content = "Não vejo mais nenhum sinal desses Eclipsites... Acho que os perdemos.",
  ui_story_5040_50401301_7_dialog_content = "Suponho que isso significa que posso diminuir um pouco o acelerador agora.",
  ui_story_5040_50401301_8_dialog_content = "Ufa... finalmente acabou...",
  ui_story_5040_50401301_9_dialog_content = "Estamos quase lá?",
  ui_story_5040_50401301_10_dialog_content = "Não, ainda estamos a alguma distância.",
  ui_story_5040_50401301_11_dialog_content = "As dunas inconstantes do Deserto de Rediesel tornam difícil para a maioria das pessoas manter seu senso de direção.",
  ui_story_5040_50401301_12_dialog_content = "Mas com você liderando o caminho, tenho certeza de que ficaremos bem.",
  ui_story_5040_50401301_13_dialog_content = "Por que sinto que já ouvi algo assim antes...?",
  ui_story_5040_50401301_14_dialog_content = "Só não se preocupe, faça o que ela diz e você ficará bem!",
  ui_story_5040_50401301_15_dialog_content = "Eu tinha minhas reservas sobre você ontem, mas acho que posso confiar em você agora.",
  ui_story_5040_50401301_16_dialog_content = "Quando conversei com Sinsa, ele disse que eu deveria confiar em você de todo o coração.",
  ui_story_5040_50401301_17_dialog_content = "Foi isso que ele disse?",
  ui_story_5040_50401301_18_dialog_content = "Claro, todos os outros na Rediesel Wrench também confiam em você e são gratos por tudo que você faz.",
  ui_story_5040_50401301_19_dialog_content = "É por isso que me incomoda tanto quando você fala tão mal deles às vezes.",
  ui_story_5040_50401301_20_dialog_content = "É assim mesmo? Hehe, obrigado.",
  ui_story_5040_50401301_21_dialog_content = "Isto me lembra, PlayerName... Eu deveria me desculpar por ontem.",
  ui_story_5040_50401301_22_dialog_content = "Huh? Por que agora, de repente?",
  ui_story_5040_50401301_23_dialog_content = "Quando você me perguntou se deveríamos pedir ajuda para procurar os outros, eu meio que o excluí.",
  ui_story_5040_50401301_24_dialog_content = "Oh aquilo? Eu não estava tão chateado, para ser honesto...",
  ui_story_5040_50401301_25_dialog_content = "Eu não entendo, no entanto. Por que você se ressente tanto da Chave Rediesel?",
  ui_story_5040_50401301_26_dialog_content = "Sim, imaginei que você os conhecesse bem, considerando que você nasceu aqui.",
  ui_story_5040_50401301_27_dialog_content = "Um daqueles caras imprestáveis que ignorou as ordens de Sinsa saqueou sua aldeia?",
  ui_story_5040_50401301_28_dialog_content = "Não, nada disso... Pelo contrário, meus pais já foram membros da Rediesel Wrench, assim como eu.",
  ui_story_5040_50401301_29_dialog_content = "Mas cortei os laços com meus pais e com a Rediesel Wrench há muito, muito tempo.",
  ui_story_5040_50401301_30_dialog_content = "Mas por quê?",
  ui_story_5040_50401301_31_dialog_content = "Você geralmente fica curioso sobre a vida privada de outras pessoas ou sou só eu?",
  ui_story_5040_50401301_32_dialog_content = "Me desculpe, eu não queria me intrometer! Tudo bem se você não quiser falar sobre isso...",
  ui_story_5040_50401301_33_dialog_content = "Heheh... Você realmente não consegue aceitar uma piada, não é?",
  ui_story_5040_50401301_34_dialog_content = "Não é um segredo profundo e obscuro ou algo assim. Eu simplesmente não conseguia concordar com sua maneira de fazer as coisas.",
  ui_story_5040_50401301_35_dialog_content = "Meus pais, assim como o resto da Rediesel Wrench, valorizavam a liberdade acima de tudo.",
  ui_story_5040_50401301_36_dialog_content = "Desde que me lembro, eles nunca cuidaram de mim como pais normais. Tudo o que eles fizeram foi me ensinar algumas habilidades básicas de sobrevivência no deserto.",
  ui_story_5040_50401301_37_dialog_content = "No resto do tempo, eles simplesmente me deixavam por conta própria.",
  ui_story_5040_50401301_38_dialog_content = "Sozinho?!",
  ui_story_5040_50401301_39_dialog_content = "É tão difícil de imaginar?",
  ui_story_5040_50401301_40_option_content = "Isso é!",
  ui_story_5040_50401301_41_dialog_content = "Sim... quer dizer, embora eu tenha ficado preso no subsolo a maior parte da minha vida, pelo menos eu tinha Soroz para me fazer companhia.",
  ui_story_5040_50401301_42_dialog_content = "Os dias eram longos e monótonos, mas eu nunca estava sozinho.",
  ui_story_5040_50401301_43_dialog_content = "É por isso que é meio difícil para mim imaginar uma vida assim...",
  ui_story_5040_50401301_44_dialog_content = "Devo dizer que não posso deixar de sentir uma pontada de ciúme, pequena celestita.",
  ui_story_5040_50401301_45_dialog_content = "Soroz deve ter cuidado bem de você, imagino?",
  ui_story_5040_50401301_46_dialog_content = "Sim... Soroz sempre foi como uma família para mim.",
  ui_story_5040_50401301_47_option_content = "Na verdade não...",
  ui_story_5040_50401301_48_dialog_content = "Bem, eu passei dezessete anos preso no subsolo, apenas com Soroz para me fazer companhia...",
  ui_story_5040_50401301_49_dialog_content = "Soroz era meu mentor e a única família que eu tinha.",
  ui_story_5040_50401301_50_dialog_content = "Sem Soroz, acho que não teria me tornado a pessoa que sou hoje.",
  ui_story_5040_50401301_51_dialog_content = "Entendo... Soroz deve ter sido um professor maravilhoso.",
  ui_story_5040_50401301_52_dialog_content = "Com certeza!",
  ui_story_5040_50401301_53_dialog_content = "Você teve sorte, mas nem todos podem ter a mesma sorte que você.",
  ui_story_5040_50401301_54_dialog_content = "Este deserto é tão vasto e vazio, tornando até mesmo a distância entre aqueles que nele habitam a de um mar de dunas sem fim.",
  ui_story_5040_50401301_55_dialog_content = "Talvez porque meus pais estivessem tão acostumados com seus modos de deserto, eles esperavam que eu fosse capaz de crescer independente de seus cuidados, sozinha.",
  ui_story_5040_50401301_56_dialog_content = "Mesmo quando eu era apenas uma garotinha, eles estavam mais preocupados em viver rápido e livre do que em cuidar da própria filha.",
  ui_story_5040_50401301_57_dialog_content = "Certamente existem mais do que algumas pessoas assim na Rediesel Wrench...",
  ui_story_5040_50401301_58_dialog_content = "Eles eram excessivamente zelosos quando se tratava de seus desejos. Foi só graças à caridade de outras pessoas que consegui crescer são e salvo.",
  ui_story_5040_50401301_59_dialog_content = "Todos na Rediesel Wrench sempre foram gentis, mas eu sempre tive ciúmes de outras crianças cujos pais realmente cuidavam delas.",
  ui_story_5040_50401301_60_dialog_content = "Eu invejava que eles tivessem pais em quem podiam confiar, que pudessem chorar e rir desinibidamente.",
  ui_story_5040_50401301_61_dialog_content = "E enquanto a vida na Rediesel Wrench sempre foi cheia de barulho e ação, nunca tive nenhum espaço pessoal, constantemente cercado de pessoas.",
  ui_story_5040_50401301_62_dialog_content = "A vivacidade, o ambiente indisciplinado; foi demais para mim. Tudo o que eu queria era estar em algum lugar tranquilo e sossegado.",
  ui_story_5040_50401301_63_dialog_content = "Então, um dia, decidi que era hora de deixar tudo para trás. A Chave Rediesel, meus pais... Não queria mais ser um deles.",
  ui_story_5040_50401301_64_dialog_content = "Vivo livre como um pássaro, sem lealdade a nenhuma facção, sem me comprometer com ninguém.",
  ui_story_5040_50401301_65_dialog_content = "Quanto ao Courier Union, trabalhar para eles é apenas um meio para um fim. É um trabalho para mim e nada mais.",
  ui_story_5040_50401301_66_dialog_content = "É assim que você se sente...?",
  ui_story_5040_50401301_67_dialog_content = "A primeira vez que pisei em seu escritório, fiquei tão chocado ao ver todas aquelas decorações.",
  ui_story_5040_50401301_68_dialog_content = "Eles estavam espalhados por todo o lugar e cobertos de poeira por não serem espanados há anos.",
  ui_story_5040_50401301_69_dialog_content = "Só para você saber, você não pode ter nenhum deles. Essas coisas são preciosas para mim.",
  ui_story_5040_50401301_70_dialog_content = "Não estou nem um pouco interessado neles! Eu não sou o tipo de pessoa que quer o que quer que eu veja!",
  ui_story_5040_50401301_71_dialog_content = "Tudo o que eu ia dizer é que mesmo que você diga que precisa deles... Você realmente não se importa muito com eles, não é?",
  ui_story_5040_50401301_72_dialog_content = "...",
  ui_story_5040_50401301_73_dialog_content = "Nenhuma dessas coisas é do Rediesel Desert, e você as usa para se convencer de que não faz parte da Rediesel Wrench.",
  ui_story_5040_50401301_74_dialog_content = "Mas se você não pertence à Rediesel Wrench, então onde você pertence? Acho que você também não sabe a resposta.",
  ui_story_5040_50401301_75_dialog_content = "(Isso explica por que o escritório de Jeriah está cheio de todas aquelas decorações empoeiradas...)",
  ui_story_5040_50401301_76_dialog_content = "(Talvez ela esteja apenas tentando preencher um vazio em seu coração?)",
  ui_story_5040_50401301_77_dialog_content = "Diga-me, que tipo de pessoa você pensa que eu sou?",
  ui_story_5040_50401301_78_dialog_content = "Você sempre age como se fosse tão enigmático e distante, mas no final do dia, você é apenas alguém que foi emocionalmente negligenciado a maior parte de sua vida.",
  ui_story_5040_50401301_79_dialog_content = "É por isso que você se recusa a amar alguém e rejeita qualquer um que possa se importar com você!",
  ui_story_5040_50401301_80_dialog_content = "Você espera que alguém que nunca foi amado, alguém que nem sabe o que é o amor, ame os outros?",
  ui_story_5040_50401301_81_dialog_content = "Eu não quis dizer nada disso...",
  ui_story_5040_50401301_82_dialog_content = "Diga, Jeriah... você não acha que está sendo um pouco duro demais consigo mesmo?",
  ui_story_5040_50401301_83_dialog_content = "O que você quer dizer?",
  ui_story_5040_50401301_84_dialog_content = "Não acredito nem por um segundo que você não saiba o que é o amor.",
  ui_story_5040_50401301_85_dialog_content = "Se você realmente não tivesse ideia, não teria se esforçado tanto para ajudar Adonis e Tara.",
  ui_story_5040_50401301_86_dialog_content = "Você os ensinou a vender selos quando estávamos em Lumopolis.",
  ui_story_5040_50401301_87_dialog_content = "Graças a você, eles puderam ajudar a Tina e, em troca... Ela nos indicou aquele laboratório de pesquisa em Illumina.",
  ui_story_5040_50401301_88_dialog_content = "E mesmo que Tara estivesse mentindo sobre sua perda de memória, você manteve seu segredo e a ajudou do mesmo jeito.",
  ui_story_5040_50401301_89_dialog_content = "Você também não queria ver o relacionamento deles desmoronar, queria?",
  ui_story_5040_50401301_90_dialog_content = "...",
  ui_story_5040_50401301_91_dialog_content = "Eu apenas os achei um casal interessante. Não é todo dia que duas pessoas de extremos opostos do Astra acabam juntas.",
  ui_story_5040_50401301_92_dialog_content = "É tão curioso como se um pássaro e um coelho se apaixonassem.",
  ui_story_5040_50401301_93_dialog_content = "Você não ouve histórias como essa todos os dias, muito menos tem a chance de testemunhá-las, e é por isso que decidi acompanhá-las.",
  ui_story_5040_50401301_94_dialog_content = "Então você poderia apenas sentar e observar em silêncio.",
  ui_story_5040_50401301_95_dialog_content = "Mas não foi isso que aconteceu, foi? Na verdade, você se esforçou para ajudá-los muitas vezes, admitindo ou não.",
  ui_story_5040_50401301_96_dialog_content = "Você pode não ter sido amado de todo o coração no passado, mas alguém tão forte e impressionante quanto você certamente encontrará pessoas no futuro que o amarão.",
  ui_story_5040_50401301_97_dialog_content = "Sério?",
  ui_story_5040_50401301_98_dialog_content = "Sou apenas uma mensageira que se apega a si mesma.",
  ui_story_5040_50401301_99_dialog_content = "Não subestime seu próprio significado!",
  ui_story_5040_50401301_100_dialog_content = "Você é um mensageiro e alguém que o povo do deserto não pode prescindir!",
  ui_story_5040_50401301_101_dialog_content = "Você importa muito mais do que imagina!",
  ui_story_5040_50401301_102_dialog_content = "...!",
  ui_story_5040_50401301_103_dialog_content = "Isso mesmo, Jerias! Você não tem ideia do quanto é importante para todos!",
  ui_story_5040_50401301_104_dialog_content = "A vida no deserto é brutal. As pessoas só podem sobreviver aqui confiando umas nas outras e ajudando umas às outras!",
  ui_story_5040_50401301_105_dialog_content = "Cada auroriano aqui é como um pequeno barco flutuando em um mar de areia. Sozinhos, é fácil nos perdermos ou até mesmo virarmos...",
  ui_story_5040_50401301_106_dialog_content = "Mas quando todos nos unimos, podemos enfrentar qualquer tempestade que surja em nosso caminho!",
  ui_story_5040_50401301_107_dialog_content = "E não há ninguém melhor para nos manter conectados do que a Rediesel Desert Courier Union!",
  ui_story_5040_50401301_108_dialog_content = "...",
  ui_story_5040_50401301_109_dialog_content = "Heheheh... Acho que finalmente entendi porque Adonis estava disposto a reunir coragem para deixar Northland.",
  ui_story_5040_50401301_110_dialog_content = "O quê?!",
  ui_story_5040_50401301_111_dialog_content = "Realmente? Por que?",
  ui_story_5040_50401301_112_dialog_content = "... Vou deixar você descobrir por si mesmo, pequeno celestita.",
  ui_story_5040_50401301_113_dialog_content = "Não seja tão vago e misterioso!",
  ui_story_5040_50401301_114_dialog_content = "Agora não é a hora. Temos assuntos mais importantes em mãos...",
  ui_story_5040_50401301_115_dialog_content = "Rugido-!!!",
  ui_story_5040_50401301_116_dialog_content = "Eclipsitos! Mas de onde eles vieram!?",
  ui_story_5040_50401301_117_dialog_content = "Sabe-se que os eclipsitos se abrigam nas tocas subterrâneas deixadas pelos vermes da areia...",
  ui_story_5040_50401301_118_dialog_content = "Estamos nos aproximando do nosso destino.",
  ui_story_5040_50401301_119_dialog_content = "Tudo bem! Vamos eliminá-los todos de uma vez!",
  ui_story_5040_50401302_1_dialog_content = "<color=#e8d9bb>Grito—!</color>",
  ui_story_5040_50401302_2_dialog_content = "Então este é o oásis em que vivem os vermes da areia?",
  ui_story_5040_50401302_3_dialog_content = "Sim. Este lugar seria perfeito para um assentamento auroriano se não fosse por todos os vermes da areia.",
  ui_story_5040_50401302_4_dialog_content = "Por causa deles, permanece completamente desabitado.",
  ui_story_5040_50401302_5_dialog_content = "Talvez seja melhor assim, sabe? Afinal, olha só como é lindo aqui.",
  ui_story_5040_50401302_6_dialog_content = "E se eu disser que as areias que cercam este oásis estão repletas de restos de aurorianos e animais que foram vítimas dos vermes da areia?",
  ui_story_5040_50401302_7_dialog_content = "O-O quê?!",
  ui_story_5040_50401302_8_dialog_content = "No deserto, quanto mais bonito algo é, mais provável é que tenha um lado macabro.",
  ui_story_5040_50401302_9_dialog_content = "Não baixe a guarda só porque parece bonito. Existem todos os tipos de perigos escondidos logo abaixo da superfície.",
  ui_story_5040_50401302_10_dialog_content = "G-Entendi...",
  ui_story_5040_50401302_11_dialog_content = "É estranho, no entanto. Não sinto nenhum verme da areia por perto... não há uma escama à vista.",
  ui_story_5040_50401302_12_dialog_content = "Eles poderiam ter migrado para outro lugar?",
  ui_story_5040_50401302_13_dialog_content = "Há outra possibilidade.",
  ui_story_5040_50401302_14_dialog_content = "O verme da areia rosa poderia tê-los afugentado para reivindicar este oásis como seu.",
  ui_story_5040_50401302_15_dialog_content = "Então devemos nos apressar e procurar por sinais daquele verme da areia!",
  ui_story_5040_50401302_16_dialog_content = "Parece que tenho que incomodá-lo novamente, Hawk.",
  ui_story_5040_50401302_17_dialog_content = "Shree!",
  ui_story_5040_50401302_18_dialog_content = "Vou usar minhas habilidades psíquicas para explorar também!",
  ui_story_5040_50401302_19_option_content = "Aumento de Força!",
  ui_story_5040_50401302_20_dialog_content = "(Por favor, mostre-me algo... Um vestígio do verme da areia rosa, um indício da presença dos meus amigos... qualquer coisa!)",
  ui_story_5040_50401302_21_dialog_content = "Espere, isso é...?",
  ui_story_5040_50401302_22_dialog_content = "Jerias! Tara! Acho que acabei de sentir Adonis e Kya!",
  ui_story_5040_50401302_23_dialog_content = "Realmente? Você é ainda mais rápido que Hawk...",
  ui_story_5040_50401302_24_dialog_content = "Onde eles estão?!",
  ui_story_5040_50401302_25_dialog_content = "Por aqui!",
  ui_story_5040_50401302_26_dialog_content = "Tem certeza de que os sentiu? Não há nada aqui, exceto alguns arbustos...",
  ui_story_5040_50401302_27_dialog_content = "Meus poderes ainda não mentiram para mim! Eles estão em algum lugar por aqui, mas parecem estar inconscientes... É por isso que não consigo identificar sua localização.",
  ui_story_5040_50401302_28_dialog_content = "Olá?",
  ui_story_5040_50401302_29_dialog_content = "Kya! Adônis! Sable!",
  ui_story_5040_50401302_30_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5040_50401302_31_dialog_content = "Espere... Olhe para o arbusto ali. Essas plantas geralmente crescem retas para cima, mas estas estão caídas no chão!",
  ui_story_5040_50401302_32_dialog_content = "Parece que alguém ou alguma coisa fez isso com eles...",
  ui_story_5040_50401302_33_dialog_content = "A-Adônis?!",
  ui_story_5040_50401302_34_dialog_content = "E Kya também! Mas onde está Sable?",
  ui_story_5040_50401302_35_dialog_content = "Eles ainda estão respirando... apenas inconscientes.",
  ui_story_5040_50401302_36_dialog_content = "Adônis! Acordar!",
  ui_story_5040_50401302_37_dialog_content = "Urgh... O-Onde estou...?",
  ui_story_5040_50401302_38_dialog_content = "Ah, graças a Deus você está bem!",
  ui_story_5040_50401302_39_dialog_content = "Uau! E-Calma, Tara! Minhas costelas vão quebrar... ou talvez já estejam quebradas.",
  ui_story_5040_50401302_40_dialog_content = "Desculpe, estou tão aliviado por você estar bem.",
  ui_story_5040_50401302_41_dialog_content = "Você se lembra como chegou aqui? Por que Sable não está com vocês dois?",
  ui_story_5040_50401302_42_dialog_content = "Me dê um segundo...",
  ui_story_5040_50401302_43_dialog_content = "Eu me lembro dessa louca tempestade de areia, e o chão afundando sob meus pés... E então, aquele verme da areia rosa vindo direto para mim...",
  ui_story_5040_50401302_44_dialog_content = "Eu entrei em panico. Eu não queria ser arrastado pela tempestade ou engolido pela areia, então agarrei uma das escamas do verme da areia e segurei firme.",
  ui_story_5040_50401302_45_dialog_content = "Depois, ele me carregou para um lugar escuro como breu... Acho que era algum tipo de toca?",
  ui_story_5040_50401302_46_dialog_content = "Chamei Kya e Sable, mas eles não responderam.",
  ui_story_5040_50401302_47_dialog_content = "Foi quando o verme da areia começou a se debater. Eu não ousei soltá-lo, então segurei até que finalmente desmaiei.",
  ui_story_5040_50401302_48_dialog_content = "Nunca mais faça isso da próxima vez que vir um verme da areia, Adonis.",
  ui_story_5040_50401302_49_dialog_content = "É uma das coisas mais perigosas que você poderia ter feito. Você é incrivelmente sortudo por estar vivo.",
  ui_story_5040_50401302_50_dialog_content = "Quero dizer, foi a primeira vez que fiquei cara a cara com um verme da areia...",
  ui_story_5040_50401302_51_dialog_content = "Em todo caso... Você está vivo e seguro, e isso é tudo que eu poderia pedir.",
  ui_story_5040_50401302_52_dialog_content = "Sim, graças a Deus.",
  ui_story_5040_50401302_53_dialog_content = "Ah, e eu tenho isso!",
  ui_story_5040_50401302_54_dialog_content = "Isso é uma escama do verme da areia rosa?!",
  ui_story_5040_50401302_55_dialog_content = "Sim! Consegui soltá-lo do monstro enquanto ele me arrastava pelo deserto.",
  ui_story_5040_50401302_56_dialog_content = "Mas só tenho um deles... Espero que seja o suficiente.",
  ui_story_5040_50401302_57_dialog_content = "(Mas Tara nem tem amnésia... Devemos contar a ele?)",
  ui_story_5040_50401302_58_dialog_content = "Na verdade, Adonis... Tenho uma coisa a confessar.",
  ui_story_5040_50401302_59_dialog_content = "O que foi?",
  ui_story_5040_50401302_60_dialog_content = "Eu nunca perdi minhas memórias em primeiro lugar.",
  ui_story_5040_50401302_61_dialog_content = "Estive fingindo esse tempo todo... Só queria ver se você era capaz de reunir coragem para deixar Northland...",
  ui_story_5040_50401302_62_dialog_content = "... Tara, você realmente não deveria ter feito isso.",
  ui_story_5040_50401302_63_dialog_content = "Sinto muito...",
  ui_story_5040_50401302_64_dialog_content = "Eu nunca deveria ter mentido para você, ou forçado você a deixar Northland, ou feito você enfrentar todos aqueles perigos... você tem todo o direito de estar chateado comigo.",
  ui_story_5040_50401302_65_dialog_content = "Eu prometo que nunca vou fazer você morar em qualquer lugar que você não queira morar de novo! Vou passar o resto da minha vida em Northland, se for preciso...",
  ui_story_5040_50401302_66_dialog_content = "Mas como você vai explorar se mora lá? Viajar em Northland é praticamente impossível.",
  ui_story_5040_50401302_67_dialog_content = "Eu... vou desistir de explorar.",
  ui_story_5040_50401302_68_dialog_content = "Você é muito mais importante para mim do que cavar algumas ruínas.",
  ui_story_5040_50401302_69_dialog_content = "...",
  ui_story_5040_50401302_70_dialog_content = "Eu não posso acreditar em você.",
  ui_story_5040_50401302_71_dialog_content = "O quê?!",
  ui_story_5040_50401401_1_dialog_content = "Eu... eu nem consigo descrever como estou com raiva de você!",
  ui_story_5040_50401401_2_dialog_content = "Sinto muito...",
  ui_story_5040_50401401_3_dialog_content = "Ouça o que tenho a dizer antes de começar a se desculpar!",
  ui_story_5040_50401401_4_dialog_content = "Eu costumava ser tão fraco antes... Não conseguia nem dar um passo para fora de Northland, muito menos lutar contra os Eclipsites.",
  ui_story_5040_50401401_5_dialog_content = "Não o culpo por fazer o que fez para me ajudar a superar meus medos... Afinal, tenho certeza de que você estava perdendo o juízo.",
  ui_story_5040_50401401_6_dialog_content = "Adônis...",
  ui_story_5040_50401401_7_dialog_content = "Então você não está chateado com ela porque ela mentiu sobre ter amnésia?",
  ui_story_5040_50401401_8_dialog_content = "Eu já suspeitava que ela não perdeu as memórias ontem à noite. Eu não estava bravo com isso.",
  ui_story_5040_50401401_9_dialog_content = "Pelo contrário, senti uma sensação avassaladora de alívio...",
  ui_story_5040_50401401_10_dialog_content = "porque eu finalmente soube que Tara não me esqueceu porque ela me odiava.",
  ui_story_5040_50401401_11_dialog_content = "Então por que você está tão bravo?",
  ui_story_5040_50401401_12_dialog_content = "Provavelmente porque ela está comprometendo?",
  ui_story_5040_50401401_13_dialog_content = "Comprometer como, exatamente?",
  ui_story_5040_50401401_14_dialog_content = "É exatamente por isso, Dona Jeriah! Fico feliz que alguém veja de onde estou vindo.",
  ui_story_5040_50401401_15_dialog_content = "Alguém poderia me dizer do que estamos falando?!",
  ui_story_5040_50401401_16_dialog_content = "Estou com raiva porque Tara acabou de dizer que estava disposta a desistir de explorar o mundo, só para poder morar comigo em Northland.",
  ui_story_5040_50401401_17_option_content = "Você não quer que ela se sinta confinada.",
  ui_story_5040_50401401_18_dialog_content = "Exatamente!",
  ui_story_5040_50401401_19_option_content = "Porque você não gosta mais dela?",
  ui_story_5040_50401401_20_dialog_content = "Claro que eu faço! Por que você pensaria isso?!",
  ui_story_5040_50401401_21_dialog_content = "Conheço Tara melhor do que ninguém, então posso dizer sem sombra de dúvida que ela nunca se mudaria de bom grado para Northland e viveria uma vida tranquila e pacífica.",
  ui_story_5040_50401401_22_dialog_content = "Mesmo que ela diga que está disposta a morar lá e estar comigo... Está claro para mim que ela está desistindo de suas esperanças e sonhos!",
  ui_story_5040_50401401_23_dialog_content = "Eu nunca poderia deixá-la fazer isso consigo mesma, especialmente por mim!",
  ui_story_5040_50401401_24_dialog_content = "Adônis, você...",
  ui_story_5040_50401401_25_dialog_content = "Eu te amo, Tara. O VERDADEIRO você. Aquele que quer viajar e explorar as ruínas em todos os cantos do mundo.",
  ui_story_5040_50401401_26_dialog_content = "Sem você, um covarde protegido como eu nunca teria aprendido tanto sobre o mundo fora de Northland.",
  ui_story_5040_50401401_27_dialog_content = "Ainda me lembro de ouvir você descrever a silhueta das paredes da linha de defesa de Illumina no horizonte do deserto de Rediesel.",
  ui_story_5040_50401401_28_dialog_content = "Ou como, de Lumopolis, você poderia olhar para baixo e ver todas as montanhas e planícies, bem como as nuvens que passavam sob seus pés...",
  ui_story_5040_50401401_29_dialog_content = "Pffft... Você não está esquecendo a parte em que os soldados de Lumopolis me confundiram com um ladrão?",
  ui_story_5040_50401401_30_dialog_content = "Foi tão caótico... Acabei passando o dia inteiro ajudando eles a pegar o verdadeiro criminoso!",
  ui_story_5040_50401401_31_dialog_content = "Hahaha! Isso mesmo, e graças a Deus você foi rápido o suficiente para pegá-lo! Caso contrário, você estaria em apuros!",
  ui_story_5040_50401401_32_dialog_content = "Eu tive que trabalhar muito para provar minha inocência!",
  ui_story_5040_50401401_33_dialog_content = "Tara... Poderíamos continuar por horas, mas o que eu realmente quero dizer...",
  ui_story_5040_50401401_34_dialog_content = "é que antes de te conhecer, meu mundo inteiro era tão branco e vazio quanto a neve que cobre Northland.",
  ui_story_5040_50401401_35_dialog_content = "Você é quem trouxe cor para minha vida chata e monótona.",
  ui_story_5040_50401401_36_dialog_content = "Isso é o que eu mais amo em você. Eu não quero te segurar ou te impedir de explorar o mundo...",
  ui_story_5040_50401401_37_dialog_content = "e é por isso que vou fazer o possível para ficar mais forte e mais corajosa, para poder ir com você!",
  ui_story_5040_50401401_38_dialog_content = "<size=45>Adônis-!</size>",
  ui_story_5040_50401401_39_dialog_content = "Ai-! V-Você está me esmagando de novo!!!",
  ui_story_5040_50401401_40_dialog_content = "Então é assim que eles se sentem, hein?",
  ui_story_5040_50401401_41_dialog_content = "Você pode ter a capacidade de ler a mente das pessoas, mas isso não significa que seja capaz de discernir o que há no coração delas.",
  ui_story_5040_50401401_42_dialog_content = "Ei! Eu nunca disse que minhas habilidades psíquicas eram oniscientes!!",
  ui_story_5040_50401401_43_dialog_content = "Na verdade, porque ninguém é. E é por isso que existem mal-entendidos que criam abismos entre as pessoas até gradualmente cortar suas conexões.",
  ui_story_5040_50401401_44_dialog_content = "Mas se as pessoas estiverem dispostas a se comunicar umas com as outras, elas podem superar os abismos e se reconectar.",
  ui_story_5040_50401401_45_dialog_content = "E eles voltam mais fortes e resistentes do que antes.",
  ui_story_5040_50401401_46_dialog_content = "Ugh ... O que há com toda a raquete ...?",
  ui_story_5040_50401401_47_dialog_content = "Kya! Você finalmente acordou!",
  ui_story_5040_50401401_48_dialog_content = "... PlayerName? Jerias? Tara e Adonis também estão aqui... Eles finalmente fizeram as pazes?",
  ui_story_5040_50401401_49_dialog_content = "Eles passaram por muita coisa, mas sim... agora estão bem!",
  ui_story_5040_50401401_50_dialog_content = "Fico feliz em ouvir isso... Quando aquele verme da areia varreu a mim e a Sable, fiquei muito preocupado com Adonis.",
  ui_story_5040_50401401_51_dialog_content = "Isso me lembra... Onde está Sable?",
  ui_story_5040_50401401_52_dialog_content = "Nós não a vimos... Quando chegamos aqui, só encontramos você e Adonis desmaiados. Também não consigo senti-la em nenhum lugar próximo...",
  ui_story_5040_50401401_53_dialog_content = "Você se lembra do que aconteceu antes de perder a consciência?",
  ui_story_5040_50401401_54_dialog_content = "Eu... só me lembro de ter sido lançada ao céu com Sable por aquela tempestade de areia... Acho que ela conseguiu agarrar o chifre do verme da areia.",
  ui_story_5040_50401401_55_dialog_content = "Depois disso, o verme da areia nos arrastou para o subsolo e bati minha cabeça em uma pedra ou algo assim... Tudo ficou preto depois disso.",
  ui_story_5040_50401401_56_dialog_content = "Então, se você e Adonis estavam inconscientes o tempo todo... quem foi que escondeu vocês dois aqui?",
  ui_story_5040_50401401_57_dialog_content = "A menos que fosse...",
  ui_story_5040_50401401_58_dialog_content = "Sabre?!",
  ui_story_5040_50401401_59_dialog_content = "Mas se foi ela quem te escondeu aqui, por que ela não está em lugar nenhum?",
  ui_story_5040_50401401_60_dialog_content = "Talvez ela quisesse atrair o verme da areia para longe de Kya e Adonis? Ou talvez...",
  ui_story_5040_50401401_61_dialog_content = "Ela sentiu que já estava no seu limite.",
  ui_story_5040_50401401_62_dialog_content = "\"Limite\"? Que \"limite\"? O que vocês dois estão aprontando dessa vez?",
  ui_story_5040_50401401_63_dialog_content = "A verdade é que Sable não é um auroriano. Ou melhor, ela costumava ser uma.",
  ui_story_5040_50401401_64_dialog_content = "O quê?!",
  ui_story_5040_50401401_65_dialog_content = "Sabia...",
  ui_story_5040_50401401_66_dialog_content = "Você não parece nem um pouco surpreso, Celestita.",
  ui_story_5040_50401401_67_dialog_content = "Eu tinha um palpite de que era esse o caso. Eu nunca tive nenhuma prova...",
  ui_story_5040_50401401_68_dialog_content = "Ela foi abandonada por seu amante quando ainda era auroriana. Em seu desespero, ela foi atraída pelo poder dos Eclipsitas e se tornou o Sable que conhecemos agora.",
  ui_story_5040_50401401_69_dialog_content = "Mas mesmo que seu corpo e mente estivessem fortemente afetados, sua consciência estava lutando para resistir ao desejo de lutar e destruir.",
  ui_story_5040_50401401_70_dialog_content = "Não faz muito tempo, porém, ela me disse que não aguentaria muito mais tempo...",
  ui_story_5040_50401401_71_dialog_content = "Como isso pode ser...?",
  ui_story_5040_50401401_72_dialog_content = "(Por que sinto que já vi esse tipo de coisa acontecer antes...?)",
  ui_story_5040_50401401_73_dialog_content = "Diga-me, PlayerName. Que tipo de pessoa você acha que Sable é?",
  ui_story_5040_50401401_74_option_content = "Uma boa.",
  ui_story_5040_50401401_75_dialog_content = "Ela pode parecer e agir um pouco diferente, mas ela tem sido nada além de amigável com todos. Eu acredito que ela é uma boa pessoa.",
  ui_story_5040_50401401_76_dialog_content = "Temos que fazer o que pudermos para ajudá-la.",
  ui_story_5040_50401401_77_option_content = "Eu realmente não a conheço...",
  ui_story_5040_50401401_78_dialog_content = "Ela parece muito tímida, então não conversamos muito... mas isso não me impede de acreditar que ela é uma boa pessoa!",
  ui_story_5040_50401401_79_dialog_content = "Eu gostaria muito de ser amigo dela, se ela estiver disposta.",
  ui_story_5040_50401401_80_dialog_content = "Então vamos fazer tudo ao nosso alcance para encontrar Sable.",
  ui_story_5040_50401401_81_dialog_content = "Acordado!",
  ui_story_5040_50401401_82_dialog_content = "Shreee—!",
  ui_story_5040_50401401_83_dialog_content = "Parece que Hawk tem algo a nos dizer. Obrigado, passarinho.",
  ui_story_5040_50401401_84_dialog_content = "Cree, cree!",
  ui_story_5040_50401401_85_dialog_content = "Você disse que viu sinais de Sable por perto?",
  ui_story_5040_50401401_86_dialog_content = "Onde ela está?!",
  ui_story_5040_50401401_87_dialog_content = "Shreee—",
  ui_story_5040_50401401_88_dialog_content = "\"Abaixo de nossos pés\"?",
  ui_story_5040_50401401_89_dialog_content = "O que isso significa...?",
  ui_story_5040_50401401_90_dialog_content = "Espere, eu sinto algo! É fraco, mas posso sentir uma pequena quantidade de Darkflow se aproximando...",
  ui_story_5040_50401401_91_dialog_content = "<color=#e8d9bb>Bum—!!!</color>",
  ui_story_5040_50401401_92_dialog_content = "Gaah! Um tremor! C-Será que é o verme da areia?!",
  ui_story_5040_50401401_93_dialog_content = "<size=45>Roooaaar!!!</size>",
  ui_story_5040_50401401_94_dialog_content = "Cuidado, Tara!",
  ui_story_5040_50401401_95_dialog_content = "Heh, eu sabia que ainda estava à espreita.",
  ui_story_5040_50401401_96_dialog_content = "<size=45>Boa!</size>",
  ui_story_5040_50401401_97_dialog_content = "Parece que algo está perseguindo o verme da areia para fora de seu túnel! Isso é... Sable?!",
  ui_story_5040_50401401_98_dialog_content = "Eu... não vou... deixar você!!!",
  ui_story_5040_50401401_99_dialog_content = "Sabre?! Ela parece uma—",
  ui_story_5040_50401401_100_dialog_content = "Não importa a aparência dela! Ela ainda está do nosso lado!",
  ui_story_5040_50401401_101_dialog_content = "Você tem que ajudá-la, PlayerName!",
  ui_story_5040_50401401_102_dialog_content = "...",
  ui_story_5040_50401401_103_dialog_content = "Eu entendi. Farei tudo o que puder.",
  ui_story_5040_50401401_104_dialog_content = "Acho que é hora de colocarmos essa ameaça rosa em seu lugar... Pronto, pequena Celestita?",
  ui_story_5040_50401401_105_dialog_content = "você vai ficar bem? Estamos travando batalhas consecutivas há muito tempo, e você queimou muito Lumina antes...",
  ui_story_5040_50401401_106_dialog_content = "Nossa, quanta consideração com você.",
  ui_story_5040_50401401_107_dialog_content = "Mas não se preocupe. Recuperei um pouco da minha Lumina no passeio até aqui.",
  ui_story_5040_50401401_108_dialog_content = "Vamos.",
  ui_story_5040_50401401_109_dialog_content = "Rogério! Vamos dar uma mãozinha a Sable com essa coisa!",
  ui_story_5040_50401402_1_dialog_content = "Minhas memórias... ficaram tão nebulosas...",
  ui_story_5040_50401402_2_dialog_content = "Eles são como pedaços de filme espalhados, flutuando em minha mente, mostrando imagens incompletas diante de meus olhos...",
  ui_story_5040_50401402_3_dialog_content = "Minha lembrança mais antiga é de um deserto... É onde nasci, onde cresci...",
  ui_story_5040_50401402_4_dialog_content = "Antes que o correio me trouxesse aquela carta, eu pensava que era apenas um zé-ninguém comum no mundo.",
  ui_story_5040_50401402_5_dialog_content = "Mas aquela carta abriu meus olhos para a beleza do mundo além do deserto... E foi assim que o conheci \"ele\"...",
  ui_story_5040_50401402_6_dialog_content = "Seu nome me escapa agora, mas eu me lembro de meu amor por ele crescendo mais a cada carta que mandávamos um para o outro.",
  ui_story_5040_50401402_7_dialog_content = "Quando eu finalmente confessei meus sentimentos a ele, e ele os retribuiu...",
  ui_story_5040_50401402_8_dialog_content = "meu coração estava transbordando de alegria e emoção.",
  ui_story_5040_50401402_9_dialog_content = "Mas foi também quando suas cartas começaram a chegar com menos frequência.",
  ui_story_5040_50401402_10_dialog_content = "Preocupava-me que minhas cartas não transmitissem meus sentimentos o suficiente, então comecei a enviar presentes para ele.",
  ui_story_5040_50401402_11_dialog_content = "No começo, eu só mandava coisas difíceis de encontrar no deserto, como flores e bijuterias antigas.",
  ui_story_5040_50401402_12_dialog_content = "Meus presentes ficaram mais extravagantes com o passar do tempo, até que comecei a enviar Nightium.",
  ui_story_5040_50401402_13_dialog_content = "Mas então, suas cartas tornaram-se cada vez mais escassas e, no lugar das palavras ternas que me dizia, ele apenas me pedia para enviar mais presentes.",
  ui_story_5040_50401402_14_dialog_content = "Eu não conseguia entender, mas nunca duvidei dele. Na verdade, eu queria conhecê-lo. E assim, ele me enviou um endereço.",
  ui_story_5040_50401402_15_dialog_content = "Juntei coragem e saí do deserto pela primeira vez.",
  ui_story_5040_50401402_16_dialog_content = "Seguindo suas cartas, fui para Illumina...",
  ui_story_5040_50401402_17_dialog_content = "E então Lumópolis...",
  ui_story_5040_50401402_18_dialog_content = "E finalmente... às margens do Lago Mirror.",
  ui_story_5040_50401402_19_dialog_content = "Ele me disse que havia preparado uma enorme festa de casamento para nós em Northland...",
  ui_story_5040_50401402_20_dialog_content = "... mas ele estava longe de ser visto.",
  ui_story_5040_50401402_21_dialog_content = "Fiquei arrasada, em lágrimas, sem saber para onde ir ou se poderia voltar para casa.",
  ui_story_5040_50401402_22_dialog_content = "Foi quando uma voz falou comigo.",
  ui_story_5040_50401402_23_dialog_content = "\"Pegue esta semente\", disse. \"Isso lhe concederá o poder de realizar todos os seus sonhos.\"",
  ui_story_5040_50401402_24_dialog_content = "Coloquei toda a minha fé naquela \"semente\", mas no final... perdi tudo.",
  ui_story_5040_50401402_25_dialog_content = "Minhas memórias, minha capacidade de pensar... Tornei-me nada mais que um monstro selvagem vagando pela terra sem um propósito...",
  ui_story_5040_50401402_26_dialog_content = "Até que conheci Adonis e Tara. Suas ações me mostraram que ainda há amor neste mundo.",
  ui_story_5040_50401402_27_dialog_content = "E Kya, que me mostrou que existem pessoas que cumprem suas promessas.",
  ui_story_5040_50401402_28_dialog_content = "E mesmo que ela pareça fria e distante às vezes, Jeriah é uma pessoa incrivelmente confiável.",
  ui_story_5040_50401402_29_dialog_content = "Com ela, vi o que significa ser despreocupado.",
  ui_story_5040_50401402_30_dialog_content = "Por isso... com o pouco tempo que me resta...",
  ui_story_5040_50401402_31_dialog_content = "Eu... não vou deixar você... chegar perto deles!!!",
  ui_story_5040_50401402_32_dialog_content = "<size=45>Roooaaar!!!</size>",
  ui_story_5040_50401402_33_dialog_content = "Urg-!",
  ui_story_5040_50401402_34_dialog_content = "Sable!",
  ui_story_5040_50401402_35_dialog_content = "O verme da areia tem Sable! Acerte a cabeça dele, Jeriah! Precisamos distraí-lo!",
  ui_story_5040_50401402_36_dialog_content = "Não se preocupe... comigo!",
  ui_story_5040_50401402_37_dialog_content = "Ataque... ponto fraco!",
  ui_story_5040_50401402_38_dialog_content = "...",
  ui_story_5040_50401402_39_dialog_content = "Deixa comigo.",
  ui_story_5040_50401402_40_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5040_50401402_41_dialog_content = "Rugido...",
  ui_story_5040_50401402_42_dialog_content = "Afe!",
  ui_story_5040_50401402_43_dialog_content = "(O verme da areia finalmente caiu...)",
  ui_story_5040_50401402_44_dialog_content = "(O ataque de Jeriah teve como alvo uma ferida antiga e perfurou sua casca...)",
  ui_story_5040_50401402_45_dialog_content = "(Mas não antes de dar uma grande mordida em Sable e jogá-la no ar...)",
  ui_story_5040_50401402_46_dialog_content = "Sable! Você está bem?!",
  ui_story_5040_50401402_47_dialog_content = "Dor...",
  ui_story_5040_50401402_48_dialog_content = "Sable! Sabre!! Sair dessa!!",
  ui_story_5040_50401402_49_dialog_content = "Essa ferida parece grave...",
  ui_story_5040_50401402_50_dialog_content = "Mesmo que ela seja tão resistente quanto um Eclipsite, eu não acho...",
  ui_story_5040_50401402_51_dialog_content = "Deixe-me tentar curá-la com meus Luminatics!",
  ui_story_5040_50401402_52_dialog_content = "É... Não está funcionando! Mas por que?!",
  ui_story_5040_50401402_53_dialog_content = "Não adianta, Adônis. Essa ferida não é algo que seus Luminatics possam tratar.",
  ui_story_5040_50401402_54_dialog_content = "Senhora Jeriah! Por que você não a ajudou?!",
  ui_story_5040_50401402_55_dialog_content = "Eu só fiz o que ela me pediu para fazer.",
  ui_story_5040_50401402_56_dialog_content = "Você também entende, não é? Mesmo se eu a tivesse salvado, ela teria se transformado em um monstro irracional em pouco tempo.",
  ui_story_5040_50401402_57_dialog_content = "...",
  ui_story_5040_50401402_58_dialog_content = "Kya...",
  ui_story_5040_50401402_59_dialog_content = "Sabre? Estou aqui, Sable!",
  ui_story_5040_50401402_60_dialog_content = "Por favor... não culpe... Jeriah...",
  ui_story_5040_50401402_61_dialog_content = "Eu não... queria te machucar... então eu fui embora. Mas então... eu vi... o verme da areia...",
  ui_story_5040_50401402_62_dialog_content = "Eu tenho... para ver você... todos vocês... uma última vez...",
  ui_story_5040_50401402_63_dialog_content = "E... eu lembrei... eu costumava ser... um auroriano.",
  ui_story_5040_50401402_64_dialog_content = "Feliz.",
  ui_story_5040_50401402_65_dialog_content = "M-Mas ainda não te levei para casa, Sable! Ainda não atendi seu pedido!",
  ui_story_5040_50401402_66_dialog_content = "Então... estou mudando... meu pedido.",
  ui_story_5040_50401402_67_dialog_content = "Por favor... leve isso... de volta para... minha casa.",
  ui_story_5040_50401402_68_dialog_content = "Diga a minha família... me desculpe...",
  ui_story_5040_50401402_69_dialog_content = "...",
  ui_story_5040_50401402_70_dialog_content = "... Courier Union Kya... ao seu dispor.",
  ui_story_5040_50401402_71_dialog_content = "A União Mensageira sempre entrega!",
  ui_story_5040_50401402_72_dialog_content = "Estou contando com você...",
  ui_story_5040_50401402_73_dialog_content = "Sable... Não...",
  ui_story_5040_50401402_74_dialog_content = "Tudo bem Kya...",
  ui_story_5040_50401402_75_dialog_content = "Eu vou pegar algo para você enxugar suas lágrimas...",
  ui_story_5040_50401402_76_dialog_content = "...",
  ui_story_5040_50401402_77_dialog_content = "Vá em frente e deixe tudo sair.",
  ui_story_5040_50401402_78_dialog_content = "Só então sua tristeza se tornará a motivação de que você precisa para continuar.",
  ui_story_5040_50401402_79_dialog_content = "Jerias...?",
  ui_story_5040_50401402_80_dialog_content = "Você está bem? Por que você saiu de repente?",
  ui_story_5040_50401402_81_dialog_content = "Até eu preciso de um tempo para me recompor de vez em quando, pequena celestita.",
  ui_story_5040_50401402_82_dialog_content = "Oh! D-Desculpe, Jeriah... Acho que acabei me acostumando a ver você lidando com tudo de uma maneira tão despreocupada.",
  ui_story_5040_50401402_83_dialog_content = "Heheh... Obrigado pelo elogio.",
  ui_story_5040_50401402_84_dialog_content = "Eu sabia há muito tempo que Sable não tinha muito tempo.",
  ui_story_5040_50401402_85_dialog_content = "Achei que conseguiria manter distância como sempre... mas não desta vez, ao que parece.",
  ui_story_5040_50401402_86_dialog_content = "Você sabia sobre ela? Por que você não contou a ninguém?",
  ui_story_5040_50401402_87_dialog_content = "Porque eu faria isso?",
  ui_story_5040_50401402_88_dialog_content = "Uh.. Bem, se todos tivéssemos sabido antes, poderíamos ter sido capazes de ajudá-la ainda mais!",
  ui_story_5040_50401402_89_dialog_content = "Tara e Adonis estariam bem com isso também.",
  ui_story_5040_50401402_90_dialog_content = "Eles podem ter sido capazes de guardar um segredo, claro... mas e os outros?",
  ui_story_5040_50401402_91_dialog_content = "Quanto mais pessoas souberem de um segredo, mais fácil será que ele venha à tona.",
  ui_story_5040_50401402_92_dialog_content = "Também existem muitos aurorianos no mundo que não pensariam duas vezes antes de se vingar dela.",
  ui_story_5040_50401402_93_dialog_content = "Aquele passarinho já havia voado muito perto do sol; não havia como voltar para ela.",
  ui_story_5040_50401402_94_dialog_content = "Se sua identidade tivesse sido descoberta, isso tornaria sua preciosa \"jornada final\" muito mais difícil do que era.",
  ui_story_5040_50401402_95_dialog_content = "Você tem razão...",
  ui_story_5040_50401402_96_dialog_content = "É por isso que, pequena celestita, você deve sempre se lembrar de uma coisa muito importante.",
  ui_story_5040_50401402_97_dialog_content = "Relacionamentos com outras pessoas são importantes, mas ter mais deles nem sempre é uma coisa boa.",
  ui_story_5040_50401402_98_dialog_content = "Na verdade, manter um nível adequado de distância e discrição às vezes é a melhor escolha.",
  ui_story_5040_50401402_99_dialog_content = "Deixe seus relacionamentos serem o vento sob as asas de seus camaradas, e não a rede que os prende.",
  ui_story_5040_50401402_100_dialog_content = "Eu sei...",
  ui_story_5040_50401402_101_dialog_content = "Estou de volta, Lady Jeriah.",
  ui_story_5040_50401402_102_dialog_content = "Me desculpe por ter chorado por tanto tempo...",
  ui_story_5040_50401402_103_dialog_content = "O que há para se desculpar? Você não pode reprimir emoções assim. É sempre melhor deixá-los sair quando precisam sair.",
  ui_story_5040_50401402_104_dialog_content = "Tara tem razão.",
  ui_story_5040_50401402_105_dialog_content = "Você parece ter decidido o que vai fazer a seguir, Kya.",
  ui_story_5040_50401402_106_dialog_content = "Sim. Cansei de chorar, porque ainda tenho o que fazer. Sable me pediu para entregar este selo em sua casa.",
  ui_story_5040_50401402_107_dialog_content = "Posso não ter como fazer isso agora, mas assim que tudo acabar... Vou enviar um pedido de transferência para a divisão Rediesel Wrench do Courier Union.",
  ui_story_5040_50401402_108_dialog_content = "Enquanto trabalho, vou me familiarizando com o deserto para um dia encontrar a casa de Sable.",
  ui_story_5040_50401402_109_dialog_content = "Nunca desistirei, mesmo que tenha que vasculhar cada centímetro do deserto de Rediesel.",
  ui_story_5040_50401402_110_dialog_content = "Desde que tenha um destino, um passarinho sempre pode terminar sua jornada, não importa a distância... Não é, Kya?",
  ui_story_5040_50401402_111_dialog_content = "Exatamente!",
  ui_story_5040_50401402_112_dialog_content = "E vocês?",
  ui_story_5040_50401402_113_dialog_content = "Não tenho mais dúvidas. Eu sei que realmente amo Adonis com todo o meu coração.",
  ui_story_5040_50401402_114_dialog_content = "Não preciso de mais nada para provar isso.",
  ui_story_5040_50401402_115_dialog_content = "Eu também tomei minha decisão. O mundo exterior pode ser perigoso, mas não é tão assustador quanto eu pensei que seria.",
  ui_story_5040_50401402_116_dialog_content = "O velho eu não tinha medo do mundo exterior... eu tinha medo do desconhecido.",
  ui_story_5040_50401402_117_dialog_content = "Mas com a ajuda de Tara, finalmente superei meus medos.",
  ui_story_5040_50401402_118_dialog_content = "Eu também nunca mais vou pedir a Adonis para fazer coisas malucas além dele.",
  ui_story_5040_50401402_119_dialog_content = "Viajamos por todo o continente, enfrentamos inúmeros perigos e experimentamos dor e perda...",
  ui_story_5040_50401402_120_dialog_content = "mas pelo menos no final vocês dois finalmente conseguiram se entender.",
  ui_story_5040_50401402_121_dialog_content = "Suponho que alguém poderia chamar isso de forro de prata.",
  ui_story_5040_50401402_122_dialog_content = "O que você teria feito se Adonis não tivesse conseguido aquela escama de verme da areia rosa, Tara?",
  ui_story_5040_50401402_123_dialog_content = "Você teria mantido sua pequena farsa?",
  ui_story_5040_50401402_124_dialog_content = "Sobre isso...",
  ui_story_5040_50401402_125_dialog_content = "Garanto que você tinha um plano B.",
  ui_story_5040_50401402_126_dialog_content = "Ehehe... Nada passa por você, Jeriah!",
  ui_story_5040_50401402_127_dialog_content = "A-Outra escama de verme da areia rosa?!",
  ui_story_5040_50401402_128_dialog_content = "Isso veio do primeiro encontro de Sinsa com o verme da areia rosa. Tive que dar um lance de uma fortuna para comprá-lo em um leilão.",
  ui_story_5040_50401402_129_dialog_content = "Foi você que comprou?!",
  ui_story_5040_50401402_130_dialog_content = "Não é à toa que você sabia que aquela poção era falsa logo de cara... O \"ingrediente raro\" que o médium mencionou estava em suas mãos o tempo todo!",
  ui_story_5040_50401402_131_dialog_content = "Não foi só isso... quer dizer, vamos lá! Uma \"Poção de Poder Ilimitado\"? Esse nome por si só é ridículo o suficiente!",
  ui_story_5040_50401402_132_dialog_content = "Você é a única pessoa ingênua e impulsiva o suficiente para saber quem se apaixonaria por algo assim.",
  ui_story_5040_50401402_133_dialog_content = "Eu, uh... Bem...",
  ui_story_5040_50401402_134_dialog_content = "Na verdade, eu estava preparado para esse resultado quando decidi fingir amnésia.",
  ui_story_5040_50401402_135_dialog_content = "Se Adonis falhou em seu julgamento...",
  ui_story_5040_50401402_135X1_dialog_content = "Ia dar esta balança à Jeriah e pedir-lhe que arranjasse outra forma de a conseguirmos.",
  ui_story_5040_50401402_136_dialog_content = "Entendo... Então, por que você comprou algo assim em primeiro lugar? ",
  ui_story_5040_50401402_137_dialog_content = "...!",
  ui_story_5040_50401402_138_dialog_content = "Er, b-bem... É uma escama de verme da areia super rara, você sabe! Além disso, é rosa, então eu...",
  ui_story_5040_50401402_139_dialog_content = "Eu queria mostrar para o Adonis... então meio que comprei por impulso.",
  ui_story_5040_50401402_140_dialog_content = "Originalmente, eu queria pedir a um ferreiro que fizesse uma aliança de casamento para ele.",
  ui_story_5040_50401402_141_dialog_content = "Oh? Essa é uma ideia interessante. Também não permitiria que a beleza da escama do verme da areia fosse desperdiçada.",
  ui_story_5040_50401402_142_dialog_content = "Mas se não me engano, só o centro da balança é duro o suficiente para o trabalho... o que significa que apenas um anel pode ser feito dele, certo?",
  ui_story_5040_50401402_143_dialog_content = "que você teria feito com seu próprio anel se Adonis não tivesse conseguido arrancar outra escama daquela besta hoje?",
  ui_story_5040_50401402_144_dialog_content = "Eu... eu nunca pensei sobre isso.",
  ui_story_5040_50401402_145_dialog_content = "Mas não é tão importante. Eu poderia me contentar com qualquer material, para ser honesto.",
  ui_story_5040_50401402_146_dialog_content = "Você nunca se importou com esse tipo de coisa, mas isso não significa que esteja tudo bem!",
  ui_story_5040_50401402_147_dialog_content = "Um casamento sem um par de alianças combinando simplesmente não está certo! Além do mais...",
  ui_story_5040_50401402_148_dialog_content = "Temos todas as escamas de verme da areia rosa que poderíamos desejar agora!",
  ui_story_5040_50401402_149_dialog_content = "<color=#e8d9bb>Screeech—</color>",
  ui_story_5040_50401402_150_dialog_content = "Onde está o verme da areia? não vejo em lugar nenhum!!",
  ui_story_5040_50401402_151_dialog_content = "Acalme-se, Brock. Olhe para lá.",
  ui_story_5040_50401402_152_dialog_content = "Caramba, é real! O verme da areia rosa é real! ... Mas por que não está se movendo?",
  ui_story_5040_50401402_153_dialog_content = "Espera... está morto?!?!",
  ui_story_5040_50401402_154_dialog_content = "Fleur? Brock? O que vocês dois estão fazendo aqui?",
  ui_story_5040_50401402_155_dialog_content = "Ah, PlayerName! Graças a Deus você não está ferido.",
  ui_story_5040_50401402_156_dialog_content = "Ouvi de Sinsa que você e seus amigos estavam caçando um verme da areia rosa, então, naturalmente, fiquei um pouco preocupado.",
  ui_story_5040_50401402_157_dialog_content = "Corri o mais rápido que pude, mas parece que minha ajuda não é mais necessária.",
  ui_story_5040_50401402_158_dialog_content = "Eu não tinha ideia de que alguém na Rediesel Wrench pudesse ser tão atencioso. Uma pena, então, que você tenha chegado tarde demais.",
  ui_story_5040_50401402_159_dialog_content = "Melhor sorte da próxima vez, suponho... Ligue-nos se precisar de ajuda novamente. Estaremos lá mais rápido do que você pode dizer \"sandworm\".",
  ui_story_5040_50401402_160_dialog_content = "Agora, se você já cuidou de tudo aqui, devemos voltar.",
  ui_story_5040_50401402_161_dialog_content = "Vocês podem ter vencido desta vez, mas juro que vou caçar um ainda maior e ainda mais cruel da próxima vez!",
  ui_story_5040_50401402_162_dialog_content = "Falando nisso, vocês precisam da nossa ajuda com isso? Ouvi dizer que escamas de vermes da areia rosa são vendidas por um bom dinheiro...",
  ui_story_5040_50401402_163_dialog_content = "Este verme da areia rosa custou a vida da amiga de Kya, então não podemos entregá-lo a você tão facilmente.",
  ui_story_5040_50401402_164_dialog_content = "No mínimo, você deve perguntar a Kya sobre isso primeiro.",
  ui_story_5040_50401402_165_dialog_content = "... Não me importa o que alguém faça com esse verme da areia.",
  ui_story_5040_50401402_166_dialog_content = "Contanto que Tara e Adonis tenham escamas suficientes para fazer suas alianças de casamento, vocês podem fazer o que quiserem com o resto.",
  ui_story_5040_50401402_167_dialog_content = "Tenho certeza de que Sable também gostaria disso.",
  ui_story_5040_50401402_168_dialog_content = "Não sei exatamente o que aconteceu aqui, mas... espero que você se sinta melhor logo!",
  ui_story_5040_50401402_169_dialog_content = "Prometo que faremos bom uso desse verme da areia. Não vamos desperdiçar nada!",
  ui_story_5040_50401402_170_dialog_content = "Estamos voltando para pedir ajuda. Para um verme da areia deste tamanho, definitivamente vamos precisar dele.",
  ui_story_5040_50401402_171_dialog_content = "Até a próxima vez, PlayerName.",
  ui_story_5040_50401402_172_dialog_content = "Claro, vejo você!",
  ui_story_5040_50401402_173_dialog_content = "Foi um dia bastante agitado, mas depois de todas as nossas lutas amargas, finalmente conseguimos derrotar o verme da areia rosa.",
  ui_story_5040_50401402_174_dialog_content = "O que significa que Adonis passou oficialmente em seu julgamento final.",
  ui_story_5040_50401402_175_dialog_content = "Eu só queria que as coisas tivessem terminado de forma diferente com Sable...",
  ui_story_5040_50401402_176_dialog_content = "Mas foi graças a ela e a todos os outros que finalmente entendi os verdadeiros sentimentos de Adonis.",
  ui_story_5040_50401402_177_dialog_content = "E pude entender mais a Tara, além de ganhar a coragem que finalmente precisava para sair para o mundo.",
  ui_story_5040_50401402_178_dialog_content = "Como todos parecem ter conseguido o que queriam, só resta uma coisa a fazer... Permita-me conceder-lhe o seu selo.",
  ui_story_5040_50401402_179_dialog_content = "<color=#e8d9bb>Carimbo!</color>",
  ui_story_5040_50401402_180_dialog_content = "Parabéns, vocês dois.",
  ui_story_5040_50401402_181_dialog_content = "Sim! Parabéns!",
  ui_story_5040_50401402_182_option_content = "Parabéns!",
  ui_story_5040_50401402_183_dialog_content = "Obrigada!",
  ui_story_5040_50401402_184_dialog_content = "Obrigado a todos!",
  ui_story_5040_50401402_185_dialog_content = "Se não fosse por todos vocês, eu ainda estaria encolhido em um canto em Northland...",
  ui_story_5040_50401402_186_dialog_content = "Mas você superou seus medos.",
  ui_story_5040_50401402_187_dialog_content = "Sim. Finalmente tenho coragem de acompanhá-lo pelo resto de nossas vidas.",
  ui_story_5040_50401402_188_dialog_content = "*Ahem* Não que eu queira atrapalhar esse momento íntimo entre vocês, mas antes de tudo isso, ainda há algo que precisa ser feito.",
  ui_story_5040_50401402_189_dialog_content = "...!",
  ui_story_5040_50401402_190_dialog_content = "Sim! E é o mais importante também!",
  ui_story_5040_50401402_191_dialog_content = "Bom, parece que todos os pássaros sabem qual é a etapa final mais importante desta jornada.",
  ui_story_5040_50401402_192_dialog_content = "Huh? Alguém quer me informar?",
  ui_story_5040_50401402_193_dialog_content = "Não é óbvio?",
  ui_story_5040_50401402_194_dialog_content = "O casamento!",
  ui_story_5040_50401501_1_dialog_content = "<color=#e8d9bb>Alguns dias depois, em Northland...</color>",
  ui_story_5040_50401501_2_dialog_content = "Adonis e Tara com certeza estão demorando...",
  ui_story_5040_50401501_3_dialog_content = "Atchim!",
  ui_story_5040_50401501_4_dialog_content = "Está congelando aqui fora... Quanto tempo mais teremos que esperar?!",
  ui_story_5040_50401501_5_dialog_content = "Paciência, pequena celestita. Este é um dos dias mais importantes de suas vidas, então vamos dar a eles um pouco mais de tempo para se prepararem.",
  ui_story_5040_50401501_6_dialog_content = "Chega.",
  ui_story_5040_50401501_7_dialog_content = "Falando nisso, este não é o lugar onde Adonis originalmente planejou realizar o casamento, é?",
  ui_story_5040_50401501_8_dialog_content = "Claro que não.",
  ui_story_5040_50401501_9_dialog_content = "Eles não têm mais motivos para fugir, então faz sentido que eles queiram hospedar um casamento maior e mais visível.",
  ui_story_5040_50401501_10_dialog_content = "Ou... talvez você prefira fazer as coisas de maneira ilícita?",
  ui_story_5040_50401501_11_dialog_content = "N-Não, está perfeitamente bem! Agora eles podem compartilhar sua felicidade com todos os seus amigos e familiares sem se preocupar!",
  ui_story_5040_50401501_12_dialog_content = "PlayerName?",
  ui_story_5040_50401501_13_dialog_content = "Não esperava vê-lo aqui hoje.",
  ui_story_5040_50401501_14_dialog_content = "Oi, Novio! Você está aqui para o casamento também?",
  ui_story_5040_50401501_15_dialog_content = "De fato. Recebi um convite de Adonis e seria negligente da minha parte não comparecer. ",
  ui_story_5040_50401501_16_dialog_content = "Como ele foi meu aluno, estou aqui para desejar felicidades ao Palácio de Inverno para ele e sua nova noiva.",
  ui_story_5040_50401501_17_dialog_content = "Ah sim, eu me lembro dos pais de Adonis e Naroxel mencionando algo sobre isso!",
  ui_story_5040_50401501_18_dialog_content = "Adonis sempre foi um garoto cauteloso e introvertido... Até onde eu sabia, ele nunca tinha posto os pés fora das fronteiras de Northland.",
  ui_story_5040_50401501_19_dialog_content = "Quando soube que ele estava se casando com Tara, uma jovem da Rediesel Wrench... Bem, fiquei surpreso, para dizer o mínimo.",
  ui_story_5040_50401501_20_dialog_content = "Ainda assim, Sua Majestade sempre fica satisfeita em ver seus súditos interagindo com o mundo exterior e expandindo seus horizontes... Assim como eu.",
  ui_story_5040_50401501_21_dialog_content = "Sim!",
  ui_story_5040_50401501_22_dialog_content = "Por favor, transmita nossos cumprimentos à Rainha Belém quando retornar ao palácio.",
  ui_story_5040_50401501_23_dialog_content = "De nada.",
  ui_story_5040_50401501_24_dialog_content = "Agora, se me der licença, ainda preciso oferecer meu presente de casamento a Adonis.",
  ui_story_5040_50401501_25_dialog_content = "Coisa certa. Até breve, Novio!",
  ui_story_5040_50401501_26_dialog_content = "Até a próxima vez, PlayerName.",
  ui_story_5040_50401501_27_dialog_content = "A propósito, por que Kya ainda não está aqui?",
  ui_story_5040_50401501_28_dialog_content = "Ela praticamente me ordenou que parasse o Colossus quando sobrevoamos Umbraton alguns dias atrás, dizendo que precisava fazer algo...",
  ui_story_5040_50401501_29_dialog_content = "Ela não me ouviu quando perguntei sobre isso e pulou antes mesmo que eu tivesse a chance de pousar Soroz corretamente!",
  ui_story_5040_50401501_30_dialog_content = "Ela não planeja ir ao casamento de Tara e Adonis?",
  ui_story_5040_50401501_31_dialog_content = "Kya não é de quebrar suas promessas.",
  ui_story_5040_50401501_32_dialog_content = "Eu... finalmente consegui!!!",
  ui_story_5040_50401501_33_dialog_content = "Ufa... Graças a Deus... Não estou atrasada!",
  ui_story_5040_50401501_34_dialog_content = "K-Kya?! Por que você está tão sem fôlego?",
  ui_story_5040_50401501_35_dialog_content = "Aqui, tome um pouco de água e recupere o fôlego. O casamento está prestes a começar.",
  ui_story_5040_50401501_36_dialog_content = "Obrigado, Lady Jeriah...",
  ui_story_5040_50401501_37_dialog_content = "<color=#e8d9bb>Glug, glug, glug—</color>",
  ui_story_5040_50401501_38_dialog_content = "Ahh... Estou tão feliz por ter chegado a tempo. Eu nunca me perdoaria se me atrasasse para isso!",
  ui_story_5040_50401501_39_dialog_content = "Onde você esteve nesses últimos dias, Kya?",
  ui_story_5040_50401501_40_dialog_content = "Ah sim, ainda não te contei.",
  ui_story_5040_50401501_41_dialog_content = "Tara e Adonis me pediram para levar suas escamas de verme da areia a um ferreiro e forjá-las em suas alianças de casamento.",
  ui_story_5040_50401501_42_dialog_content = "Dê uma olhada!",
  ui_story_5040_50401501_43_dialog_content = "São lindos... Nem dá para perceber que são feitos de escamas de vermes da areia!",
  ui_story_5040_50401501_44_dialog_content = "O ferreiro levou muito mais tempo do que esperava para forjar esses anéis.",
  ui_story_5040_50401501_45_dialog_content = "Se não fosse esse atalho que encontrei nas anotações que a Esmeralda me emprestou, eu teria me atrasado com certeza!",
  ui_story_5040_50401501_46_dialog_content = "Oh? Que atalho seria esse e por que não ouvi falar dele?",
  ui_story_5040_50401501_47_dialog_content = "O céu, claro! Eu tive que voar sem parar por horas só para pegar uma carruagem para Northland!",
  ui_story_5040_50401501_48_dialog_content = "Minhas asas ainda estão com tanta dor...",
  ui_story_5040_50401501_49_dialog_content = "Você sabia que o Courier Union de Umbraton teria lhe fornecido transporte se você tivesse enviado um pedido urgente?",
  ui_story_5040_50401501_50_dialog_content = "O quê?!",
  ui_story_5040_50401501_51_dialog_content = "Por que ninguém me disse isso! Também não há menção a isso nas anotações de Emerald...",
  ui_story_5040_50401501_52_dialog_content = "É um serviço relativamente novo oferecido pela divisão Umbraton. Naturalmente, você não encontraria nada sobre isso no caderno do seu último ano.",
  ui_story_5040_50401501_53_dialog_content = "Suspiro... Acho que ainda tenho muito a aprender sobre as diferentes divisões.",
  ui_story_5040_50401501_54_dialog_content = "Ainda assim, que bom que você conseguiu chegar aqui a tempo! Ainda estamos esperando a cerimônia começar, então descanse um pouco, Kya!",
  ui_story_5040_50401501_55_dialog_content = "Pode deixar!",
  ui_story_5040_50401501_56_dialog_content = "Como foram os preparativos enquanto estive fora?",
  ui_story_5040_50401501_57_dialog_content = "Por favor, diga-me que você encontrou aquele suposto \"médium\" e lhe deu uma lição para que ele não engane mais ninguém.",
  ui_story_5040_50401501_58_dialog_content = "Hehe... Claro.",
  ui_story_5040_50401501_59_dialog_content = "Fomos procurá-lo assim que chegamos.",
  ui_story_5040_50401501_60_dialog_content = "Esse é ele! Esse é o médium!",
  ui_story_5040_50401501_61_dialog_content = "Ah?! ... M-Posso ajudá-lo, gentil senhor?",
  ui_story_5040_50401501_62_dialog_content = "Você me vendeu uma \"poção mágica\" de má qualidade alguns dias atrás, mas era uma farsa total!",
  ui_story_5040_50401501_63_dialog_content = "Ah sim! lembrei de vc agora...",
  ui_story_5040_50401501_64_dialog_content = "Devo pedir que pare de manchar meu bom nome com suas alegações ridículas, senhor. Posso garantir que minhas poções são 100% genuínas e eficazes.",
  ui_story_5040_50401501_65_dialog_content = "É feito da escama do raro verme da areia rosa!",
  ui_story_5040_50401501_66_dialog_content = "E se bem me lembro, não foi você quem veio até mim quando minha poção fez com que sua noiva perdesse as memórias?",
  ui_story_5040_50401501_67_dialog_content = "Essa sou eu, e eu estava inventando isso o tempo todo. Sua poção não teve nenhum efeito sobre mim.",
  ui_story_5040_50401501_68_dialog_content = "Além disso, você nunca usou uma escama de verme da areia rosa para prepará-lo!",
  ui_story_5040_50401501_69_dialog_content = "O-Oh sim? Onde está a sua prova então?!",
  ui_story_5040_50401501_70_dialog_content = "Você primeiro! Onde você conseguiu uma escama de verme da areia rosa em primeiro lugar?",
  ui_story_5040_50401501_71_dialog_content = "Avisa-te que o comprei num leilão há pouco tempo! Havia apenas um de seu tipo em todo o Astra!",
  ui_story_5040_50401501_72_dialog_content = "Uau, que coincidência... porque eu também comprei uma escama de verme da areia rosa em um leilão um tempo atrás.",
  ui_story_5040_50401501_73_dialog_content = "O quê?!",
  ui_story_5040_50401501_74_dialog_content = "Na verdade, ainda tenho o certificado oficial de venda de quando o comprei... Quer dar uma olhada?",
  ui_story_5040_50401501_75_dialog_content = "Você foi o comprador misterioso que fugiu com a escama do verme da areia naquele leilão?!",
  ui_story_5040_50401501_76_dialog_content = "Ora, ora... Conseguir que você se implique dificilmente exigiu qualquer esforço.",
  ui_story_5040_50401501_77_dialog_content = "Não estou totalmente familiarizado com a forma como Northland pune os vigaristas, mas...",
  ui_story_5040_50401501_78_dialog_content = "Aposto que vocês não querem saber como os punimos no Deserto Rediesel.",
  ui_story_5040_50401501_79_dialog_content = "Uh... nós realmente não temos que ouvir isso, obrigado...",
  ui_story_5040_50401501_80_dialog_content = "Eu sinto Muito!",
  ui_story_5040_50401501_81_dialog_content = "Aqui, você pode ter seu dinheiro de volta! Eu vou me entregar!",
  ui_story_5040_50401501_82_dialog_content = "Isso é bom de ouvir. Estou feliz que tudo deu certo.",
  ui_story_5040_50401501_83_dialog_content = "Então, e os pais de Adonis? Eles concordaram com o casamento?",
  ui_story_5040_50401501_84_dialog_content = "Depois de ver o quanto Adonis havia mudado, eles realmente não tinham mais nada a dizer sobre isso.",
  ui_story_5040_50401501_85_dialog_content = "Eles ficaram mais do que felizes em aprovar o casamento de Tara e Adonis!",
  ui_story_5040_50401501_86_dialog_content = "Realmente? Isso é quase bom demais para ser verdade!",
  ui_story_5040_50401501_87_dialog_content = "Afinal, eles eram completamente contra a ideia de Adonis fugir com Tara antes.",
  ui_story_5040_50401501_88_dialog_content = "Você só pensa isso porque não conseguiu ver como eles realmente se sentiam.",
  ui_story_5040_50401501_89_dialog_content = "Eu acho que se há uma pessoa que pode ver através das pessoas, é você...",
  ui_story_5040_50401501_90_dialog_content = "Se os poderes do celestita pudessem ler o coração das pessoas, imagino que ele também conseguiria.",
  ui_story_5040_50401501_91_dialog_content = "Eu não uso minhas habilidades para me intrometer na mente das pessoas! Isso é completamente inapropriado!",
  ui_story_5040_50401501_92_dialog_content = "A melhor maneira de entender os outros é se comunicar com eles.",
  ui_story_5040_50401501_93_dialog_content = "Então, o que os pais de Adonis estavam pensando naquela época?",
  ui_story_5040_50401501_94_dialog_content = "mesma coisa que qualquer mãe e pai comuns pensariam em sua posição.",
  ui_story_5040_50401501_95_dialog_content = "Eles estavam simplesmente preocupados que seu filho, que nunca havia deixado Northland, fosse incapaz de se adaptar ao mundo externo desconhecido.",
  ui_story_5040_50401501_96_dialog_content = "Isso, por sua vez, os deixou ainda mais relutantes em deixá-lo pisar fora de sua terra natal.",
  ui_story_5040_50401501_97_dialog_content = "Isso soa como um ciclo vicioso.",
  ui_story_5040_50401501_98_dialog_content = "Isso é verdade, e é por isso que eu tive que dar uma pequena cutucada neles para dar uma chance ao filho deles.",
  ui_story_5040_50401501_99_dialog_content = "D-Não me diga que você os ameaçou como fez com a vidente?!",
  ui_story_5040_50401501_100_dialog_content = "Eu realmente pareço esse tipo de pessoa para você?",
  ui_story_5040_50401501_101_dialog_content = "N-não...",
  ui_story_5040_50401501_102_dialog_content = "Você tem que empregar métodos diferentes com pessoas diferentes.",
  ui_story_5040_50401501_103_dialog_content = "Os pais de Adonis são pessoas perfeitamente razoáveis. Eles estavam apenas relutantes em deixar seu precioso filho fora de vista.",
  ui_story_5040_50401501_104_dialog_content = "Tudo o que fiz foi apontar o problema de tratá-lo assim, e eles rapidamente perceberam que deixá-lo ir era o melhor.",
  ui_story_5040_50401501_105_dialog_content = "Eu o invejo por ter pais assim.",
  ui_story_5040_50401501_106_dialog_content = "Não sabia que você fazia tanto nos bastidores!",
  ui_story_5040_50401501_107_dialog_content = "Só dei uma mãozinha aqui e ali... Queria ver como terminaria a história deles, esses dois amantes de lados opostos.",
  ui_story_5040_50401501_108_dialog_content = "Tem um final bastante satisfatório, se assim posso dizer.",
  ui_story_5040_50401501_109_dialog_content = "Olha, eles estão aqui!",
  ui_story_5040_50401501_110_dialog_content = "É Adonis e Tara!",
  ui_story_5040_50401501_111_dialog_content = "Suas roupas parecem incríveis!",
  ui_story_5040_50401501_112_dialog_content = "Tara parece absolutamente deslumbrante! E Adonis... não fazia ideia que ele limpava tão bem!",
  ui_story_5040_50401501_113_dialog_content = "Parabéns, vocês dois.",
  ui_story_5040_50401501_114_dialog_content = "Parabéns!",
  ui_story_5040_50401501_115_dialog_content = "Parabéns!",
  ui_story_5040_50401501_116_dialog_content = "Obrigada!",
  ui_story_5040_50401501_117_dialog_content = "Muito obrigado a todos! Desculpe por deixar todos vocês esperando!",
  ui_story_5040_50401501_118_dialog_content = "Somos os recém-casados mais sortudos de todo o Astra por ter dois de seus maiores mensageiros como testemunhas de nosso casamento!",
  ui_story_5040_50401501_119_dialog_content = "O sentimento é mútuo. Agora então, vamos começar, certo?",
  ui_story_5040_50401501_120_dialog_content = "Tara, você aceita Adonis como seu marido legítimo?",
  ui_story_5040_50401501_121_dialog_content = "Ter e manter deste dia em diante, na saúde e na doença, na riqueza ou na pobreza, em todas as tribulações—",
  ui_story_5040_50401501_122_dialog_content = "Amá-lo, honrá-lo e aceitá-lo, agora e para sempre, até que a morte os separe?",
  ui_story_5040_50401501_123_dialog_content = "Sim!",
  ui_story_5040_50401501_124_dialog_content = "Adônis, você aceita Tara como sua legítima esposa?",
  ui_story_5040_50401501_125_dialog_content = "Ter e manter deste dia em diante, na saúde e na doença, na riqueza ou na pobreza, em todas as tribulações—",
  ui_story_5040_50401501_126_dialog_content = "Amá-la, honrá-la e aceitá-la, agora e para sempre, até que a morte os separe?",
  ui_story_5040_50401501_127_dialog_content = "Sim!",
  ui_story_5040_50401501_128_dialog_content = "Seu amor atravessou rios e resistiu a montanhas de diferenças; enfrentou todos os tipos de obstáculos e perigos e durou. Agora então, meus passarinhos...",
  ui_story_5040_50401501_129_dialog_content = "Peço que troquem suas alianças.",
  ui_story_5040_50401501_130_dialog_content = "Ufa... Graças a Deus a cerimônia acabou!",
  ui_story_5040_50401501_131_dialog_content = "Finalmente conseguimos trocar essas roupas por algo mais confortável!",
  ui_story_5040_50401501_132_dialog_content = "Você não gostou do seu vestido de noiva?!",
  ui_story_5040_50401501_133_dialog_content = "Claro que sim! Nós escolhemos juntos, não é?",
  ui_story_5040_50401501_134_dialog_content = "Estava um pouco abafado de usar, só isso... eu mal conseguia me mexer dentro dele!",
  ui_story_5040_50401501_135_dialog_content = "Quase caí algumas vezes quando você estava me levando até o altar!",
  ui_story_5040_50401501_136_dialog_content = "Hahahaha! Para ser honesto, foi um pouco estranho ver você em um vestido tão extravagante.",
  ui_story_5040_50401501_137_dialog_content = "Vestir suas roupas favoritas e fazer o que você gosta é sempre o melhor, não é?",
  ui_story_5040_50401501_138_dialog_content = "Sim, mas tenho que dizer, esse terno realmente ficou ótimo em você.",
  ui_story_5040_50401501_139_dialog_content = "Também estou curioso, considerando que o traje formal está muito longe do seu traje habitual.",
  ui_story_5040_50401501_140_dialog_content = "Como você conseguiu ficar tão bem nele?",
  ui_story_5040_50401501_141_dialog_content = "Er, na verdade...",
  ui_story_5040_50401501_142_dialog_content = "Adonis está se preparando para este casamento em segredo há muito, muito tempo.",
  ui_story_5040_50401501_143_dialog_content = "Pai? Mãe?!",
  ui_story_5040_50401501_144_dialog_content = "Muitas vezes ele esperava até que estivéssemos dormindo tarde da noite e experimentava na frente do espelho, trabalhando em sua estatura.",
  ui_story_5040_50401501_145_dialog_content = "Este casamento significou o mundo para ele... Mais do que tudo, ele queria proporcionar a você uma experiência inesquecível.",
  ui_story_5040_50401501_146_dialog_content = "Mesmo assim, ele ficava tão empolgado praticando que nos acordava no meio da noite...",
  ui_story_5040_50401501_147_dialog_content = "Espere, então vocês dois sabiam o tempo todo?!",
  ui_story_5040_50401501_148_dialog_content = "Claro que sim.",
  ui_story_5040_50401501_149_dialog_content = "Nunca nos opusemos verdadeiramente a que te casasses, filho. Você sempre foi livre para escolher se o faria ou não e para quem.",
  ui_story_5040_50401501_150_dialog_content = "Estávamos apenas preocupados com a possibilidade de você entrar de cabeça no casamento sem se preparar mental e emocionalmente de maneira adequada.",
  ui_story_5040_50401501_151_dialog_content = "Afinal, você não sabia praticamente nada do mundo exterior. Até mesmo um vigarista vendedor de poções levou a melhor sobre você!",
  ui_story_5040_50401501_152_dialog_content = "Seria irresponsável de nossa parte deixar você se casar naquele estado!",
  ui_story_5040_50401501_153_dialog_content = "Exatamente! E se um dia você percebesse que o mundo lá fora não era para você? Se você se arrependeu de sua decisão de deixar Northland,",
  ui_story_5040_50401501_154_dialog_content = "você teria responsabilizado Tara por ser o motivo de sua partida.",
  ui_story_5040_50401501_155_dialog_content = "E isso, meu filho, não seria justo com você ou com Tara. Você entende agora?",
  ui_story_5040_50401501_156_dialog_content = "Pai... Mãe... Me desculpe por ser tão egoísta...",
  ui_story_5040_50401501_157_dialog_content = "Mas agora posso dizer, com toda certeza, que sei como é o mundo lá fora, e mesmo assim... ainda quero me casar com Tara.",
  ui_story_5040_50401501_158_dialog_content = "Sim, testemunhamos como você mudou, então não nos opomos mais ao seu casamento.",
  ui_story_5040_50401501_159_dialog_content = "Desejamos a vocês dois todo o amor e felicidade do mundo.",
  ui_story_5040_50401501_160_dialog_content = "Esta não é mais apenas a nossa casa. É a casa de Tara também.",
  ui_story_5040_50401501_161_dialog_content = "Embora suas aventuras, sem dúvida, o levem a todos os cantos do Astra... Nunca se esqueça de que Northland sempre estará aqui para recebê-lo de volta.",
  ui_story_5040_50401501_162_dialog_content = "Mãe, Pai... Muito obrigado!",
  ui_story_5040_50401501_163_dialog_content = "A partir de agora, somos uma família!",
  ui_story_5040_50401501_164_dialog_content = "<color=#e8d9bb>Dois dias depois, a bordo do Soroz...</color>",
  ui_story_5040_50401501_165_dialog_content = "Essa aventura com certeza tomou muito tempo...",
  ui_story_5040_50401501_166_dialog_content = "No começo, eu estava apenas levando algumas pessoas do Deserto de Rediesel para Northland... Nunca esperei viajar por todo o Astra por causa disso!",
  ui_story_5040_50401501_167_dialog_content = "Ainda bem que consegui encerrar tudo antes que Vice e Carleen voltassem das férias... Consegui até comprar o toca-discos chique com o pagamento que recebi da Naroxel!",
  ui_story_5040_50401501_168_dialog_content = "Eles sempre me ajudam muito, mas dessa vez fiz uma surpresa para eles sozinha!",
  ui_story_5040_50401501_169_dialog_content = "Estamos de volta, PlayerName!",
  ui_story_5040_50401501_170_dialog_content = "O Mooncrown Day foi tão agitado quanto qualquer outro ano, mas graças a Deus tudo permaneceu relativamente calmo este ano.",
  ui_story_5040_50401501_171_dialog_content = "Como foram as coisas enquanto estivemos fora?",
  ui_story_5040_50401501_172_dialog_content = "Ah, como de costume.",
  ui_story_5040_50401501_173_dialog_content = "Eu apenas voei com Soroz por alguns dias e experimentei o Mooncrown Day em alguns lugares diferentes.",
  ui_story_5040_50401501_174_dialog_content = "Até aceitei um emprego no Courier Union e ganhei algum dinheiro!",
  ui_story_5040_50401501_175_dialog_content = "Eu ouvi isso! Jola me perguntou por que não estava com você.",
  ui_story_5040_50401501_176_dialog_content = "Vários soldados de Lumopolis também viram você ajudando o Courier Union local alguns dias atrás. Você tem trabalhado duro.",
  ui_story_5040_50401501_177_dialog_content = "Oh, não foi nada, realmente.",
  ui_story_5040_50401501_178_dialog_content = "Eu estava muito ocupado!",
  ui_story_5040_50401501_179_dialog_content = "Aceitei um emprego no Courier Union e ganhei algum dinheiro!",
  ui_story_5040_50401501_180_dialog_content = "Era para ser uma viagem rápida, mas o trabalho acabou demorando alguns dias.",
  ui_story_5040_50401501_181_dialog_content = "Eu ouvi sobre isso, sim. Você estava em Lumopolis em um ponto, então eu acho que você foi para Illumina?",
  ui_story_5040_50401501_182_dialog_content = "Ouvi dizer que você foi até o Deserto Rediesel e Northland! Deve ter sido uma viagem e tanto!",
  ui_story_5040_50401501_183_dialog_content = "Espere um segundo... Por que vocês dois sabem onde eu estive esse tempo todo?!",
  ui_story_5040_50401501_184_dialog_content = "Bem, Soroz não é exatamente difícil de perder... Você chama muita atenção por onde passa!",
  ui_story_5040_50401501_185_dialog_content = "Acho que isso faz sentido...",
  ui_story_5040_50401501_186_dialog_content = "De qualquer forma, usei o pagamento para fazer uma surpresinha para vocês!",
  ui_story_5040_50401501_187_dialog_content = "Aí está!",
  ui_story_5040_50401501_188_dialog_content = "Esse é o toca-discos de antes?!",
  ui_story_5040_50401501_189_dialog_content = "Foi bastante caro, se bem me lembro.",
  ui_story_5040_50401501_190_dialog_content = "Quando fomos fazer compras em Umbraton, lembro de vocês dois olhando pela janela por um longo tempo.",
  ui_story_5040_50401501_191_dialog_content = "Achei que vocês devem ter gostado muito, então dei uma olhada no preço e fiquei genuinamente chocado.",
  ui_story_5040_50401501_192_dialog_content = "Mas quando pensei em todas as vezes que você me ajudou, percebi que não tinha feito muito para mostrar minha gratidão...",
  ui_story_5040_50401501_193_dialog_content = "Foi quando decidi comprar aquele toca-discos para vocês dois!",
  ui_story_5040_50401501_194_dialog_content = "Tenho feito biscates aqui e ali, e desta vez finalmente pude pagar!",
  ui_story_5040_50401501_195_dialog_content = "PlayerName...",
  ui_story_5040_50401501_196_dialog_content = "Há uma razão para estarmos olhando para aquele toca-discos por tanto tempo...",
  ui_story_5040_50401501_197_dialog_content = "Carleen e eu conversamos sobre isso por dias... Queríamos algo especial para você.",
  ui_story_5040_50401501_198_dialog_content = "Então, quando nós dois vimos aquele toca-discos em Umbraton, imediatamente soubemos que era a escolha certa!",
  ui_story_5040_50401501_199_dialog_content = "Afinal, os celestitas sempre amaram música, certo? E que melhor maneira de aproveitá-lo do que com um toca-discos de alta qualidade!",
  ui_story_5040_50401501_200_dialog_content = "Foi aí que decidimos juntar nosso dinheiro para comprá-lo para você.",
  ui_story_5040_50401501_201_dialog_content = "É também a razão pela qual voltamos a trabalhar para o Mooncrown Day...",
  ui_story_5040_50401501_202_dialog_content = "Trabalhar...? Espere, então nenhum de vocês saiu de férias?!",
  ui_story_5040_50401501_203_dialog_content = "Sim... Não queríamos que você descobrisse, então guardamos nosso segredinho...",
  ui_story_5040_50401501_204_dialog_content = "Mas foi só depois que chegamos em Umbraton que percebemos... que alguém já havia comprado o toca-discos.",
  ui_story_5040_50401501_205_dialog_content = "Tudo o que podíamos fazer era comprar alguns doces Umbraton e alguns livros novos para dar de presente.",
  ui_story_5040_50401501_206_dialog_content = "Então vocês dois não queriam aquele toca-discos em primeiro lugar?!",
  ui_story_5040_50401501_207_dialog_content = "Isso é...",
  ui_story_5040_50401501_208_dialog_content = "Está bem! Claro, não aconteceu como esperávamos, mas conseguimos a vitrola no final, não é?",
  ui_story_5040_50401501_209_dialog_content = "Sem mencionar alguns livros novos e alguns lanches.",
  ui_story_5040_50401501_210_dialog_content = "Sim você está certo!",
  ui_story_5040_50401501_211_dialog_content = "Vamos lá, vamos colocar música e lanches em dia!"
}
return config
